update public.course_modules set title = 'Lire les journaux', description = 'Ce module pose la méthode de base avant toute enquête : reconnaître une source, lire un événement sans surinterpréter, remettre les heures dans le bon ordre, puis relier des traces par une clé commune sans confondre indice et preuve. Critères de réussite : identifier le format et les champs utiles d’un extrait ; convertir des horodatages vers une chronologie UTC ; formuler une hypothèse prudente et la tester avec au moins une seconde source.'
where id = '3f229e54-4809-d296-89e3-14648080233a' and title = 'Lire les journaux';
