update public.course_modules set title = 'Qualifier une alerte', description = 'Tu y apprends à décider sans te précipiter : qualifier une alerte, ordonner une file d’attente et enrichir les indicateurs sans perdre la confidentialité des journaux. Critères de réussite : rédiger une note de triage qui sépare faits et hypothèses ; classer plusieurs alertes par priorité avec une justification claire ; enrichir un indicateur en notant la source, la date et les limites de l’information obtenue.'
where id = '9bbc731c-3ce3-2024-c67b-c719856c68ac' and title = 'Qualifier une alerte';
