update public.course_modules set title = 'Investiguer un incident', description = 'Ce module te fait passer de la lecture de traces à la preuve défendable. Tu y relies des journaux déjà publiés à une méthode d’investigation plus formelle. Critères de réussite : préserver l’intégrité des preuves, structurer une chronologie en UTC, et rédiger un rapport qui distingue clairement les faits, les hypothèses et les recommandations.'
where id = '44bd6cd9-5751-ccb1-3836-e36284128600' and title = 'Investiguer un incident';
