insert into public.course_modules (id, course_id, title, description, position) values
  ('d1f9c8f6-6ed7-21f6-1f47-57215d368839', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Journaux Linux et serveurs', 'Tu entres ici dans les traces les plus courantes d’un serveur Linux : syslog, journald, authentification, sudo et audit d’exécution. L’objectif n’est pas de mémoriser des fichiers, mais de savoir où chercher, quoi compter et comment mesurer la force probante de chaque source. Critères de réussite : choisir le bon journal pour une question précise ; repérer une séquence de connexion ou d’élévation de droits significative ; relier une exécution sensible à sa session d’origine avec prudence.', 2),
  ('8d425d0f-033b-ed31-c89b-e193593fecef', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Journaux Windows', 'Ce module t’apprend à lire les événements Windows sans te perdre dans l’interface : choisir le bon journal, comprendre ce que la stratégie d’audit produit, puis relier sessions, comptes, processus, DNS, réseau et PowerShell. Critères de réussite : filtrer un export Windows de façon reproductible, relire une séquence 4625 puis 4624 avec ses types et ses codes, et reconstituer une exécution en reliant Sysmon et PowerShell par leurs champs communs.', 3),
  ('855f3363-e64e-319b-81d6-4e39a7693320', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Journaux web et applications', 'Ce module te donne une lecture complète des traces web et métier : format des accès, signaux d’attaque visibles, puis confirmation par les journaux applicatifs et de base de données. Critères de réussite : décomposer une ligne « combined », distinguer bruit et succès probable dans une séquence web, et raconter un incident à partir d’un journal d’accès, d’un « request_id » applicatif et d’un effet côté base.', 4),
  ('ed4716b0-947a-9860-7eca-36051d075eaa', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Réseau, pare-feu, DNS et proxy', 'Ce module t’apprend à lire les journaux réseau sans te laisser impressionner par le volume : pare-feu, DNS, proxy, flux et alertes IDS disent chacun une partie de l’histoire. Critères de réussite : distinguer bruit entrant et signal utile ; relier un domaine à un poste, un volume et un rythme ; qualifier une alerte réseau avec prudence avant d’escalader.', 5),
  ('b9cf9654-4f18-dd0b-f095-aa48e72eb099', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Outils d’analyse', 'Tu y développes ta boîte à outils quotidienne pour transformer un journal brut en réponse argumentée, puis en analyse rejouable. Critères de réussite : construire un pipeline texte fiable ; extraire proprement des champs avec regex, jq ou PowerShell ; automatiser une analyse simple avec un résultat vérifiable.', 6),
  ('8dfef90e-761f-7bcb-6d62-86dc99d68558', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Corrélation et détection', 'Ce module t’apprend à transformer des traces isolées en une lecture défensive cohérente, puis à écrire des détections simples que tu sais mesurer et régler. Critères de réussite : choisir une clé de corrélation et bâtir une chronologie en UTC ; écrire une règle avec seuil, fenêtre et groupement explicites ; mesurer précision et rappel avant de modifier une détection.', 7),
  ('5dd6e48c-0126-4785-322d-289797dd3f4e', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Centraliser et conserver les journaux', 'Ce module t’apprend à regrouper des journaux sans perdre leur contexte, à choisir un premier outillage réaliste et à protéger des traces qui deviennent vite sensibles. Critères de réussite : expliquer pourquoi une copie distante améliore l’enquête, estimer un besoin de stockage à partir d’hypothèses simples, et proposer une conservation proportionnée avec des garanties d’intégrité et de confidentialité.', 9)
insert into public.lessons (id, course_id, module_id, title, summary, content, duration_minutes, xp_reward, position) values
  ('68e79828-c0ed-2694-e32e-275fb4abdeca', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '3f229e54-4809-d296-89e3-14648080233a', 'D’où viennent les journaux : sources, formats et niveaux de gravité', 'Comprends ce qu’est un journal, d’où il vient, sous quelles formes il arrive, et pourquoi le niveau de gravité change tout pour l’analyse comme pour le stockage.', '{"blocks":[{"type":"callout","content":"Objectifs : définir un journal, repérer une source, reconnaître plusieurs formats, décoder un niveau de gravité, puis expliquer pourquoi un journal reste une preuve fragile."},{"type":"callout","content":"Prérequis : aucun, sauf la curiosité et l’envie de lire des traces avec méthode."},{"type":"callout","content":"Mise en situation : Awa rejoint l’équipe de support de Baobab Tech. Un matin, elle reçoit un fichier de journal Linux, un export CSV, deux lignes JSON et une alerte du pare-feu. Tout le monde lui demande ce qu’il faut regarder d’abord. Avant de parler d’attaque ou de panne, elle doit reconnaître ce qu’elle a sous les yeux et ce que chaque format peut réellement raconter."},{"type":"callout","content":"Vidéo à venir : Reconnaître les sources et formats de journaux sans se perdre"},{"type":"text","content":"Un journal, ou log, est un enregistrement horodaté d’un événement. Un événement dit qu’une chose s’est produite : une connexion réussie, un échec, un redémarrage, une requête web, un refus du pare-feu, un changement de mot de passe. Pour l’analyser, tu cherches toujours les mêmes repères : quand, qui, quoi, où, d’où, avec quel résultat. Le journal n’est pas réservé à la sécurité : il sert aussi au diagnostic, à l’exploitation, à l’audit et parfois à la conformité."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Petite organisation : sources courantes de journaux\",\"columns\":2,\"items\":[{\"term\":\"Poste Windows\",\"text\":\"connexions, processus, erreurs\",\"icon\":\"pc\",\"tone\":\"blue\"},{\"term\":\"Serveur Linux\",\"text\":\"ssh, sudo, services, noyau\",\"icon\":\"server\",\"tone\":\"green\"},{\"term\":\"Site web\",\"text\":\"accès, erreurs, comptes applicatifs\",\"icon\":\"globe\",\"tone\":\"cyan\"},{\"term\":\"Pare-feu\",\"text\":\"ALLOW, DENY, ports, adresses\",\"icon\":\"firewall\",\"tone\":\"red\"},{\"term\":\"Routeur ou proxy\",\"text\":\"navigation, DNS, volumes\",\"icon\":\"router\",\"tone\":\"violet\"},{\"term\":\"Service en ligne\",\"text\":\"audit, connexions, changements sensibles\",\"icon\":\"cloud\",\"tone\":\"amber\"}]}"},{"type":"text","content":"Les sources se multiplient vite : systèmes, applications, équipements réseau, services en ligne. Le premier piège est de croire qu’elles parlent toutes la même langue. En pratique, tu rencontres du texte libre, du syslog, du JSON lignes, du CSV, du XML et des formats binaires. Un bon analyste commence donc par reconnaître la forme avant d’inventer une interprétation. Cette discipline t’évite de confondre un champ, un fuseau horaire ou même une simple colonne."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Formats fréquents et difficulté d’analyse\",\"columns\":[\"Format\",\"Atout principal\",\"Point de vigilance\"],\"rows\":[[\"Texte libre\",\"facile à lire\",\"variable selon le logiciel\"],[\"Syslog\",\"très courant\",\"gravité et source visibles\"],[\"JSON lignes\",\"champs explicites\",\"pratique à filtrer\"],[\"CSV\",\"simple à exporter\",\"dépend de l’ordre des colonnes\"],[\"XML\",\"structuré\",\"parfois verbeux\"],[\"Binaire\",\"compact et fidèle\",\"illisible sans l’outil prévu\"]]}"},{"type":"text","content":"Le syslog traditionnel montre souvent, dans les fichiers texte, une date courte, une machine, un programme et un message. Le syslog RFC 5424 normalise au contraire un en-tête avec « PRI », une version et un horodatage complet RFC 3339. Le JSON lignes stocke un objet par ligne, pratique pour filtrer un champ comme « level » ou « ip ». Le CSV fonctionne bien pour des exports d’événements ou d’inventaire, mais tu dois connaître l’ordre des colonnes. Le XML sert beaucoup dans l’univers Windows. Les formats binaires, comme journald, wtmp ou les fichiers EVTX, imposent un outil spécialisé : « cat » ne suffit pas."},{"type":"text","content":"Démonstration guidée : prends six lignes mélangées, puis classe-les sans encore parler de compromission. Tu peux refaire cet exercice dans Git Bash, PowerShell, WSL, une machine virtuelle ou Termux. Si tu n’as qu’un poste Windows, Git Bash et PowerShell suffisent déjà pour apprendre à reconnaître les formats sans disposer d’un serveur."},{"type":"code","content":"# Classer six lignes selon leur forme\nawk ''\n/^<[0-9]+>1 / { kind=\"syslog-rfc5424\"; print NR \":\" kind \" => \" $0; next }\n/^[A-Z][a-z][a-z] [ 0-9][0-9] / { kind=\"syslog-rfc3164\"; print NR \":\" kind \" => \" $0; next }\n/^\\{/ { kind=\"jsonl\"; print NR \":\" kind \" => \" $0; next }\n/^[0-9]{4}-[0-9]{2}-[0-9]{2},/ { kind=\"csv\"; print NR \":\" kind \" => \" $0; next }\n/^<Event>/ { kind=\"xml\"; print NR \":\" kind \" => \" $0; next }\n/^binary:/ { kind=\"binaire\"; print NR \":\" kind \" => \" $0; next }\n{ print NR \":inconnu => \" $0 }\n'' formats-mixes.log\n# exemple de sortie (valeurs fictives)\n# 1:syslog-rfc5424 => <34>1 2026-03-10T08:15:00Z web01 sshd 1201 ID47 - Failed password for invalid user admin from 192.0.2.10 port 51234 ssh2\n# 2:syslog-rfc3164 => Mar 10 08:15:04 web01 sshd[1201]: Failed password for awa from 192.0.2.10 port 51235 ssh2\n# 3:jsonl => {\"ts\":\"2026-03-10T08:15:08Z\",\"service\":\"api\",\"level\":\"error\",\"ip\":\"192.0.2.44\",\"message\":\"login failed\"}\n# 4:csv => 2026-03-10,08:15:12,pc-awa,4625,awa,192.0.2.10\n# 5:xml => <Event><System><EventID>4625</EventID><TimeCreated SystemTime=\"2026-03-10T08:15:12.0000000Z\"/></System></Event>\n# 6:binaire => binary:wtmp","language":"bash"},{"type":"code","content":"# Lire le même principe côté Windows sur deux formats simples\nGet-Content .\\events.jsonl | ForEach-Object { $_ | ConvertFrom-Json } |\n  Format-Table ts, service, level, ip -AutoSize\n# exemple de sortie (valeurs fictives)\n# ts                   service level ip\n# --                   ------- ----- --\n# 2026-03-10T08:15:08Z api     error 192.0.2.44\n# 2026-03-10T08:15:10Z api     info  192.0.2.44\n\nImport-Csv .\\events.csv | Format-Table date, time, host, event, user, ip -AutoSize\n# exemple de sortie (valeurs fictives)\n# date       time     host   event user ip\n# ----       ----     ----   ----- ---- --\n# 2026-03-10 08:15:12 pc-awa 4625  awa  192.0.2.10\n# 2026-03-10 08:16:04 pc-awa 4624  awa  192.0.2.10","language":"powershell"},{"type":"text","content":"Les niveaux de gravité servent à hiérarchiser le bruit. En syslog, la gravité va de 0 à 7 : 0 Emergency, 1 Alert, 2 Critical, 3 Error, 4 Warning, 5 Notice, 6 Informational, 7 Debug. Plus le chiffre est bas, plus la situation est critique. Un « DEBUG » partout peut noyer l’essentiel et coûter du disque. Un niveau trop haut, au contraire, peut faire disparaître les événements utiles. Il faut donc journaliser assez pour enquêter, sans fabriquer un océan de lignes inutiles."},{"type":"example","content":"Exemple corrigé : « <34> » se décode en facilité 4 et gravité 2, car 34 = 4 × 8 + 2. La facilité 4 correspond aux messages de sécurité ou d’autorisation, et la gravité 2 à « Critical ». Le message n’est pas automatiquement une compromission : le code t’indique la famille et l’importance annoncée par la source, pas la vérité finale. Rappelle-toi aussi qu’un journal reste une preuve fragile : incomplet, falsifiable par un attaquant root, trompeur si l’horloge est fausse, et sensible car il contient souvent des adresses, des comptes ou des courriels."},{"type":"callout","content":"Erreurs fréquentes : confondre la forme et le fond, par exemple croire qu’un JSON est forcément plus fiable qu’un texte libre ; oublier que les formats binaires demandent leur outil de lecture ; traiter le niveau « error » comme une preuve d’incident ; publier des extraits réels contenant des données personnelles sans nécessité."},{"type":"callout","content":"Sécurité : analyse seulement les journaux de ton organisation ou d’un système pour lequel tu as un mandat écrit. Les journaux réels contiennent des données à protéger : n’envoie pas des extraits sensibles à un service tiers sans nécessité, et masque les identifiants avant un partage pédagogique ou un rapport large."},{"type":"callout","content":"À retenir : commence toujours par reconnaître la source et le format. Cherche ensuite les champs utiles : temps, source, action, résultat, identifiants. Le niveau de gravité aide à trier, mais il ne remplace jamais l’analyse. Un journal absent n’est pas une preuve d’absence d’événement."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 1 : lire, normaliser et dater des journaux de formats différents » : refais la partie où tu reconnais le format, identifies les champs et compares ce que chaque source permet ou non de conclure. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"},{"type":"resource","content":"NIST SP 800-92 : guide de la gestion des journaux de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/92/final"},{"type":"resource","content":"RFC 5424 : protocole Syslog (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc5424"}]}'::jsonb, 22, 30, 1),
  ('82da3b35-54fe-ad32-abd2-be099ee8184b', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '3f229e54-4809-d296-89e3-14648080233a', 'Le temps dans les journaux : horodatage, fuseaux horaires et horloges', 'Apprends à convertir les horodatages, à repérer les décalages de fuseau ou d’horloge, et à remettre plusieurs sources dans une seule chronologie UTC.', '{"blocks":[{"type":"callout","content":"Objectifs : lire plusieurs formats d’horodatage, convertir une heure en UTC, distinguer heure locale et heure de réception, mesurer une dérive d’horloge, puis expliquer pourquoi une chronologie se construit sur un fuseau commun."},{"type":"callout","content":"Prérequis : savoir repérer les champs principaux d’un événement et accepter de ne pas comparer des heures avant de les avoir normalisées."},{"type":"callout","content":"Mise en situation : Moussa reçoit trois traces d’un même incident apparent : un accès web à 09:15 +01:00, un refus de pare-feu à 08:15Z et un extrait syslog sans fuseau. Au premier regard, tout semble se contredire. S’il compare ces heures brutes, il peut raconter une cause qui vient après sa conséquence. Il doit d’abord remettre tout le monde sur la même montre."},{"type":"callout","content":"Vidéo à venir : Reconstituer une chronologie sans se faire piéger par les fuseaux"},{"type":"text","content":"Le temps est la colonne vertébrale d’une analyse. Sans horodatage fiable, tu peux difficilement dire ce qui s’est passé avant, pendant ou après. Le problème est que toutes les sources n’écrivent pas le temps de la même manière. Certaines donnent un RFC 3339 complet, comme « 2026-03-10T09:15:00+01:00 ». D’autres écrivent une heure locale dans une interface et gardent l’UTC dans le fichier brut. Le syslog traditionnel, lui, n’indique ni l’année ni le fuseau. Si tu oublies ces différences, ta chronologie devient fausse avant même d’avoir commencé."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Formats fréquents de temps\",\"columns\":[\"Format\",\"Exemple\",\"Repère utile\"],\"rows\":[[\"RFC 3339\",\"2026-03-10T08:15:00Z\",\"UTC explicite avec Z\"],[\"ISO 8601\",\"2026-03-10T09:15:00+01:00\",\"décalage horaire explicite\"],[\"syslog BSD\",\"Mar 10 08:15:00\",\"sans année ni fuseau\"],[\"accès web\",\"[10/Mar/2026:08:15:00 +0000]\",\"fuseau dans les crochets\"],[\"epoch Unix\",\"1700000000\",\"secondes depuis l’epoch\"],[\"auditd\",\"audit(1700000000.123:456)\",\"epoch avec millisecondes\"],[\"journald JSON\",\"__REALTIME_TIMESTAMP=1773130805123456\",\"microsecondes UTC\"]],\"mono\":[1]}"},{"type":"text","content":"L’UTC, temps universel coordonné, sert de référence commune. Le suffixe « Z » signifie UTC. Un décalage comme « +01:00 » signifie « une heure en avance sur UTC ». Ainsi, « 2026-03-10T09:15:00+01:00 » et « 2026-03-10T08:15:00Z » désignent le même instant. Le but n’est pas de préférer un format à un autre, mais de les traduire dans une échelle unique avant toute comparaison. Cette règle vaut aussi pour l’heure d’un événement et l’heure de réception dans un collecteur : ce sont parfois deux moments différents, tous deux utiles. Avec « journalctl -o json », journald expose aussi « __REALTIME_TIMESTAMP », c’est-à-dire l’heure de réception par le journal en microsecondes depuis l’epoch UTC : c’est précis, mais il faut le convertir proprement."},{"type":"code","content":"# Conversions rapides dans Git Bash\ndate -u -d ''2026-03-10 09:15:00 +0100'' ''+%Y-%m-%dT%H:%M:%SZ''\ndate -u -d ''10 Mar 2026 08:15:00 +0000'' ''+%Y-%m-%dT%H:%M:%SZ''\ndate -u -d ''10 Mar 2026 08:15:00 +0100'' ''+%Y-%m-%dT%H:%M:%SZ''\ndate -u -d @1700000000 ''+%Y-%m-%dT%H:%M:%SZ''\n# exemple de sortie (valeurs fictives)\n# 2026-03-10T08:15:00Z\n# 2026-03-10T08:15:00Z\n# 2026-03-10T07:15:00Z\n# 2023-11-14T22:13:20Z","language":"bash"},{"type":"code","content":"# Même idée dans PowerShell 5.1\n[DateTimeOffset]::Parse(''2026-03-10T09:15:00+01:00'').ToUniversalTime().ToString(''yyyy-MM-ddTHH:mm:ssZ'')\n[DateTimeOffset]::ParseExact(''10/Mar/2026:08:15:00 +0000'', ''dd/MMM/yyyy:HH:mm:ss zzz'', [System.Globalization.CultureInfo]::InvariantCulture).ToUniversalTime().ToString(''yyyy-MM-ddTHH:mm:ssZ'')\n[DateTimeOffset]::Parse(''2026-03-10T08:15:12.0000000Z'').ToUniversalTime().ToString(''yyyy-MM-ddTHH:mm:ssZ'')\n[DateTimeOffset]::FromUnixTimeMilliseconds([long](1773130805123456 / 1000)).ToUniversalTime().ToString(''yyyy-MM-ddTHH:mm:ss.fffZ'')\n# exemple de sortie (valeurs fictives)\n# 2026-03-10T08:15:00Z\n# 2026-03-10T08:15:00Z\n# 2026-03-10T08:15:12Z\n# 2026-03-10T08:20:05.123Z","language":"powershell"},{"type":"text","content":"Démonstration guidée : convertis toujours d’abord, interprète ensuite. Si deux lignes disent « 09:15 +01:00 » et « 08:15Z », tu ne les ranges pas l’une après l’autre : tu notes qu’elles parlent du même instant. Si une machine dérive de quatre minutes, tu l’écris comme un problème de qualité de preuve. Une dérive n’invalide pas tout le journal, mais elle interdit les conclusions trop fines tant que tu n’as pas corrigé ou estimé l’écart."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Chronologie saine\",\"numbered\":true,\"items\":[{\"title\":\"Noter la source\",\"text\":\"format et fuseau de chaque source\",\"tone\":\"blue\"},{\"title\":\"Convertir en UTC\",\"text\":\"passer tout le monde sur la même montre\",\"tone\":\"green\"},{\"title\":\"Distinguer les temps\",\"text\":\"heure de l’événement et heure de réception\",\"tone\":\"violet\"},{\"title\":\"Signaler l’écart\",\"text\":\"toute dérive connue de l’horloge\",\"tone\":\"amber\"},{\"title\":\"Trier seulement après\",\"text\":\"ordonner les lignes une fois normalisées\",\"tone\":\"cyan\"}]}"},{"type":"text","content":"Le syslog traditionnel demande une prudence supplémentaire : sans année ni fuseau, « Mar 10 08:15:00 » doit être replacé dans le contexte de la machine qui l’a produit et de la période d’enquête. Tu n’inventes donc pas une conversion RFC 3164 sans écrire l’hypothèse retenue, par exemple « serveur en UTC+01, enquête sur mars 2026 ». Les journaux Windows affichés dans l’Observateur d’événements utilisent souvent l’heure locale, alors que le XML contient « SystemTime » en UTC. Les journaux web incluent souvent un décalage explicite dans les crochets. auditd écrit une époque Unix avec millisecondes, et journald JSON une époque en microsecondes. Dans tous les cas, la bonne méthode reste la même : noter, convertir, comparer."},{"type":"example","content":"Exemple corrigé : un portail écrit « 2026-03-10T09:15:00+01:00 ». Le pare-feu distant écrit « 2026-03-10T08:15:04Z ». Quatre secondes séparent donc les deux événements, pas une heure et quatre secondes. Autre cas : une ligne RFC 3164 « Mar 10 08:15:00 » venant d’un serveur réglé en UTC+01 correspond à « 2026-03-10T07:15:00Z », mais seulement si tu notes explicitement cette hypothèse de fuseau et d’année. Enfin, si une machine A annonce 08:21Z alors qu’une autre annonce 08:17Z pour le même échange, une dérive connue de quatre minutes peut rétablir une chronologie plausible, à condition de documenter cette correction."},{"type":"callout","content":"Erreurs fréquentes : mélanger heure locale et UTC dans le même tableau ; oublier que le syslog traditionnel ne donne pas l’année ni le fuseau ; comparer un temps d’événement à un temps de réception sans le dire ; corriger une dérive d’horloge sans la documenter."},{"type":"callout","content":"Sécurité : ne manipule pas les horodatages pour « faire tenir » une hypothèse. Toute conversion ou correction d’écart doit être reproductible. Si tu partages une chronologie, garde les traces originales et note clairement quel outil ou quelle commande a servi à normaliser les heures."},{"type":"callout","content":"À retenir : avant de comparer deux heures, convertis-les dans un même fuseau, idéalement l’UTC. Note la différence entre l’heure de l’événement et l’heure de réception. Une petite dérive d’horloge peut suffire à casser toute une chronologie si tu ne la détectes pas."},{"type":"callout","content":"Pour pratiquer : Dans « TP 1 : lire, normaliser et dater des journaux de formats différents », refais toute la partie conversion vers l’UTC, puis vérifie quels événements sont réellement simultanés et lesquels ne le sont qu’en apparence. Termine par le quiz."},{"type":"resource","content":"RFC 3339 : date et heure sur Internet (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc3339"},{"type":"resource","content":"chrony : documentation (synchronisation d’horloge) (en anglais)","url":"https://chrony-project.org/documentation.html"},{"type":"resource","content":"Wikipédia : temps universel coordonné","url":"https://fr.wikipedia.org/wiki/Temps_universel_coordonn%C3%A9"}]}'::jsonb, 22, 30, 3),
  ('9ce3af04-6403-f91e-bdee-d9bf4ba0c2fe', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'd1f9c8f6-6ed7-21f6-1f47-57215d368839', 'Les journaux Linux : syslog, journald et /var/log', 'Repère où Linux écrit ses traces, quand utiliser les fichiers ou journald, et comment retrouver une activité de service dans une plage de temps ou une archive tournée.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer syslog et journald, choisir le bon emplacement de journal, filtrer un service sur une plage de temps, lire une archive tournée, puis expliquer pourquoi une copie distante protège mieux la preuve."},{"type":"callout","content":"Prérequis : savoir reconnaître un format syslog et comprendre que le temps doit être normalisé avant toute comparaison sérieuse."},{"type":"callout","content":"Mise en situation : Yacine doit répondre à trois questions simples sur un serveur Debian : qui s’est connecté, quel service a échoué et qu’est-ce qui s’est passé avant le redémarrage du matin. Le collègue précédent lui dit seulement « regarde dans /var/log ». Pour aller vite sans se tromper, Yacine doit savoir où chercher et quand passer de fichiers texte à « journalctl »."},{"type":"callout","content":"Vidéo à venir : Trouver le bon journal Linux avant de filtrer"},{"type":"text","content":"Sous Linux, les journaux viennent surtout de deux mondes qui cohabitent souvent : les fichiers texte gérés par syslog ou rsyslog, et le journal binaire géré par journald. Un fichier syslog traditionnel ressemble à « Mar 10 08:15:00 web01 sshd[1201]: ... ». En RFC 5424, tu vois au contraire un « <PRI> », une version, puis un horodatage complet RFC 3339. journald stocke ces événements sous forme structurée et peut les ressortir au format court, détaillé ou JSON. Sur Debian ou Ubuntu avec rsyslog, tu rencontres souvent « /var/log/syslog », « /var/log/auth.log », « /var/log/kern.log », « /var/log/dpkg.log » et les dossiers de services comme « /var/log/nginx/ ». Sur RHEL ou Fedora, tu vois plutôt « /var/log/messages », « /var/log/secure », « /var/log/audit/audit.log » et « /var/log/httpd/ ». Sur certaines installations récentes de Debian, rsyslog n’est pas installé par défaut : il faut alors lire journald avec « journalctl »."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Où chercher selon la question\",\"columns\":[\"Question\",\"Première source à lire\"],\"rows\":[[\"authentification\",\"`/var/log/auth.log` ou `/var/log/secure`\"],[\"activité générale\",\"`/var/log/syslog` ou `/var/log/messages`\"],[\"noyau\",\"`/var/log/kern.log` ou `journalctl -k`\"],[\"paquets et mises à jour\",\"`/var/log/dpkg.log`, `/var/log/apt/`\"],[\"service web\",\"`/var/log/nginx/` ou `/var/log/apache2/`\"],[\"journal binaire\",\"`journalctl`, pas `cat`\"]],\"mono\":[1]}"},{"type":"text","content":"Le champ « PRI » du syslog combine facilité et gravité, mais le plus utile au quotidien est souvent l’emplacement. Si tu cherches une connexion SSH, commence par le journal d’authentification. Si tu veux suivre un service systemd, « journalctl -u service » est souvent plus pratique qu’un « grep » large dans « /var/log/syslog ». journald sait filtrer par unité, par gravité, par démarrage, par plage de temps et même sortir du JSON. Les fichiers texte restent très pratiques pour des pipelines simples et pour les archives tournées."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Repères journald utiles\",\"columns\":2,\"items\":[{\"term\":\"`-u ssh.service`\",\"text\":\"ou `sshd.service` : une unité précise\",\"tone\":\"blue\"},{\"term\":\"`-b`\",\"text\":\"démarrage courant\",\"tone\":\"green\"},{\"term\":\"`--since` / `--until`\",\"text\":\"plage de temps\",\"tone\":\"violet\"},{\"term\":\"`-p err`\",\"text\":\"erreurs et niveaux plus urgents\",\"tone\":\"red\"},{\"term\":\"`-o json`\",\"text\":\"champs structurés exportables\",\"tone\":\"cyan\"},{\"term\":\"`--no-pager`, `-f`\",\"text\":\"sans pager, puis suivre en direct\",\"tone\":\"amber\"}]}"},{"type":"text","content":"Démonstration guidée : commence par le fichier texte, puis pense à l’archive tournée. Beaucoup d’analyses ratent une information simplement parce qu’elle a déjà quitté « auth.log » pour « auth.log.1 » ou « auth.log.2.gz ». La rotation protège le disque, mais elle oblige l’analyste à regarder aussi les anciennes copies. Sur un vrai serveur, « journalctl -u ssh.service --since \"2026-03-10 08:00\" --no-pager » ou « journalctl -o json » font gagner du temps, car tu récupères à la fois l’heure, l’unité systemd et l’identifiant du programme. Ici, sur un simple extrait, tu peux déjà travailler la méthode."},{"type":"code","content":"# Chercher l’activité SSH d’une plage courte dans un fichier syslog\ngrep ''sshd'' syslog-demo.log | awk ''$3 >= \"08:16:00\" && $3 <= \"08:17:00\"''\n# exemple de sortie (valeurs fictives)\n# Mar 10 08:16:04 web01 sshd[1201]: Failed password for awa from 192.0.2.10 port 51235 ssh2\n# Mar 10 08:16:41 web01 sshd[1201]: Accepted password for awa from 192.0.2.10 port 51240 ssh2\n\n# Ne pas oublier les archives tournées\ngzip -dc syslog-demo.log.1.gz | grep ''CRON''\n# exemple de sortie (valeurs fictives)\n# Mar 10 08:18:11 web01 CRON[1300]: pam_unix(cron:session): session opened for user root(uid=0) by root(uid=0)","language":"bash"},{"type":"text","content":"Les fichiers « wtmp », « btmp » et « lastlog » méritent un rappel spécial : ils sont binaires. On les lit avec « last », « lastb » et « lastlog », pas avec « cat ». « last » s’appuie sur « wtmp » pour les connexions réussies, « lastb » sur « btmp » pour les échecs, et « lastlog » résume la dernière connexion par compte. De la même manière, les droits d’accès comptent : tout le monde ne doit pas lire les journaux d’authentification, car ils révèlent des comptes, des adresses et des habitudes. Enfin, un attaquant root peut falsifier ou effacer des traces locales. C’est l’une des raisons majeures pour lesquelles une copie distante et quasi immédiate est plus robuste qu’un stockage uniquement local."},{"type":"example","content":"Exemple corrigé : si l’on te demande « qui s’est connecté ? », tu commences par « auth.log » ou « secure », puis éventuellement « last » pour les connexions réussies. Pour « quel service a planté ? », tu regardes « syslog », « messages » ou « journalctl -u service ». Pour « quel paquet a été installé ? », tu vas vers « dpkg.log », « /var/log/apt/ » ou l’outil équivalent de la distribution. La bonne réponse dépend moins du mot “incident” que de la source qui raconte le mieux le fait recherché."},{"type":"callout","content":"Erreurs fréquentes : chercher partout en même temps au lieu de choisir d’abord la source la plus probable ; oublier les fichiers tournés et compressés ; essayer de lire « wtmp » ou « btmp » comme du texte ; croire qu’un journal local intact suffit toujours comme preuve."},{"type":"callout","content":"Sécurité : ne change pas la configuration de journalisation d’un serveur de production sans autorisation. Les journaux contiennent des données personnelles et parfois des secrets applicatifs. Limite les droits de lecture, évite les copies inutiles et privilégie une collecte distante sécurisée quand ton organisation la permet."},{"type":"callout","content":"À retenir : sur Linux, la question « où chercher ? » précède souvent la question « que chercher ? ». Syslog, journald et « /var/log » se complètent. Pense à la rotation, aux formats binaires et à la nécessité d’une copie distante pour mieux protéger la preuve."},{"type":"callout","content":"Pour pratiquer : Travaille d’abord « TP 1 : lire, normaliser et dater des journaux de formats différents » pour les formats, puis « Force brute SSH : de l’échec à la prise de contrôle » pour voir comment le choix du bon journal change l’enquête. Termine par le quiz."},{"type":"resource","content":"Debian : manuel de journalctl (en anglais)","url":"https://manpages.debian.org/stable/systemd/journalctl.1.en.html"},{"type":"resource","content":"Manuel : logrotate(8), la rotation des journaux (en anglais)","url":"https://man7.org/linux/man-pages/man8/logrotate.8.html"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"}]}'::jsonb, 24, 30, 1),
  ('486be8f3-befc-23b5-72de-3a78a6b80500', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'd1f9c8f6-6ed7-21f6-1f47-57215d368839', 'Authentification, sudo et sessions : lire auth.log, secure et last', 'Interprète les lignes SSH, PAM, sudo et useradd, compte les échecs avec méthode, puis distingue un bruit opportuniste d’une séquence plus inquiétante.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître les lignes d’authentification usuelles, compter les échecs par source et par compte, distinguer succès et refus, repérer une élévation de droits, puis formuler une conclusion prudente."},{"type":"callout","content":"Prérequis : savoir où se trouvent les journaux Linux et comprendre qu’un seul événement n’autorise pas une conclusion définitive."},{"type":"callout","content":"Mise en situation : Amina ouvre « auth.log » d’un serveur exposé à Internet et voit une rafale de tentatives. Le responsable lui demande si c’est juste le bruit habituel ou le début d’un incident. Pour répondre utilement, elle doit lire les messages de « sshd », de PAM et de « sudo », puis résumer ce qui mérite vraiment une suite."},{"type":"callout","content":"Vidéo à venir : Lire auth.log et repérer le moment qui change tout"},{"type":"text","content":"Les journaux d’authentification Linux racontent l’accès au système. Dans « auth.log » ou « secure », tu rencontres des lignes « Failed password for invalid user admin » quand le compte n’existe pas, et « Failed password for awa » quand le compte existe. Cette nuance importe : dans le second cas, la source a déjà deviné ou découvert un compte valide. Tu vois aussi « Accepted password », « Accepted publickey », « Invalid user », « Connection closed ... [preauth] », ainsi que les messages PAM qui détaillent un refus ou l’ouverture d’une session."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Indices fréquents dans auth.log\",\"columns\":[\"Ligne ou motif\",\"Lecture prudente\"],\"rows\":[[\"Failed password for invalid user admin\",\"compte inexistant\"],[\"Failed password for awa\",\"compte existant\"],[\"Accepted password for awa\",\"réussite par mot de passe\"],[\"Accepted publickey for awa\",\"réussite par clé\"],[\"pam_unix(... authentication failure ...)\",\"échec vu par PAM\"],[\"sudo: awa ... USER=root ... COMMAND=...\",\"élévation ou action privilégiée\"]],\"mono\":[0]}"},{"type":"text","content":"La force d’« auth.log » tient à la séquence. Beaucoup d’échecs rapprochés depuis une même source, sur plusieurs comptes, font penser à une force brute ou à un arrosage de mots de passe. Une réussite juste après plusieurs échecs sur un compte réel est plus inquiétante qu’un simple bruit opportuniste. En revanche, le journal ne montre pas le mot de passe essayé, ni ce que l’attaquant pense faire ensuite. Il te faut donc une conclusion prudente : ce que la ligne prouve, et ce qu’elle ne prouve pas."},{"type":"code","content":"# Compter les échecs par adresse source\ngrep ''Failed password'' auth-demo.log | awk ''{for (i=1;i<=NF;i++) if ($i==\"from\") print $(i+1)}'' | sort | uniq -c | sort -rn\n# exemple de sortie (valeurs fictives)\n#       7 192.0.2.10\n#       3 192.0.2.55\n#       1 192.0.2.15\n\n# Compter les échecs par compte visé\ngrep ''Failed password'' auth-demo.log | awk ''{for (i=1;i<=NF;i++) if ($i==\"for\") { if ($(i+1)==\"invalid\") print $(i+3); else print $(i+1) }}'' | sort | uniq -c | sort -rn\n# exemple de sortie (valeurs fictives)\n#       4 admin\n#       3 awa\n#       1 test\n#       1 support\n#       1 moussa\n#       1 backup","language":"bash"},{"type":"text","content":"Démonstration guidée : dans cet extrait, « 192.0.2.10 » vise plusieurs fois « awa », puis réussit, et le même journal montre aussitôt une commande « sudo » et l’ouverture de session root par PAM. Tu peux donc écrire : « une réussite depuis 192.0.2.10 sur le compte awa est suivie d’une action privilégiée ». Tu n’écris pas encore : « l’attaquant a tout compromis ». Peut-être s’agit-il d’un administrateur légitime qui s’est trompé deux fois, ou d’un test interne. La différence se fera avec le contexte habituel du compte, de la source et de l’horaire."},{"type":"schema","content":"{\"v\":1,\"kind\":\"flow\",\"title\":\"Lire le contexte après la réussite\",\"nodes\":[{\"label\":\"Succès SSH\",\"text\":\"`Accepted password` ou `publickey`\",\"icon\":\"key\",\"tone\":\"green\"},{\"label\":\"Puis sudo\",\"text\":\"commande sensible ou session root\",\"icon\":\"shield\",\"tone\":\"amber\"},{\"label\":\"Puis useradd\",\"text\":\"création de compte\",\"icon\":\"user-plus\",\"tone\":\"red\"},{\"label\":\"Puis `last` / `lastb`\",\"text\":\"historique synthétique des succès ou échecs\",\"icon\":\"clock\",\"tone\":\"blue\"}]}"},{"type":"text","content":"Les commandes « last -F », « lastb » et « lastlog » complètent cette lecture. « last -F » montre les connexions réussies avec les dates et heures complètes d’ouverture et de fermeture quand elles sont connues. « lastb » lit « btmp » pour les échecs enregistrés, souvent avec des droits root selon la distribution. « lastlog » résume la dernière connexion connue par compte et aide à repérer un « Never logged in ». Eux aussi ont des limites : un historique synthétique n’explique pas tout. Enfin, attention aux réactions trop rapides. Bannir une adresse partagée ou couper un compte sans vérifier peut gêner une personne légitime. Le journal te pousse à enquêter, pas à punir avant d’avoir compris."},{"type":"example","content":"Exemple corrigé : si une même adresse produit 7 échecs, puis « Accepted password for awa », puis « sudo: awa ... USER=root ... COMMAND=/usr/bin/apt update », la conclusion prudente est : « réussite suspecte suivie d’une action privilégiée, à confirmer avec le contexte du compte et des accès habituels ». Si, en revanche, tu ne vois que trois échecs sur « admin » sans succès, tu parleras plutôt de bruit opportuniste courant sur un serveur exposé."},{"type":"callout","content":"Erreurs fréquentes : oublier la différence entre compte inexistant et compte réel ; compter les échecs sans regarder s’il existe aussi un succès ; prendre « sudo » pour une preuve d’attaque alors qu’il peut s’agir d’une maintenance légitime ; bannir une adresse sans réfléchir au partage d’IP."},{"type":"callout","content":"Sécurité : sur un système réel, ne diffuse pas les journaux d’authentification plus largement que nécessaire. Ils révèlent des comptes, des habitudes de connexion et parfois des actions d’administration. Toute mesure de blocage doit suivre la procédure de ton organisation et un mandat clair."},{"type":"callout","content":"À retenir : dans les journaux d’authentification, la séquence compte plus qu’une ligne isolée. Compte les échecs, regarde les comptes visés, cherche le premier succès, puis lis ce qui se passe après. Garde une conclusion prudente tant que tu n’as pas recoupé le contexte."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Force brute SSH : de l’échec à la prise de contrôle » : compte les échecs, repère la réussite et relie les lignes « sudo » ou « useradd » qui suivent. Termine par le quiz."},{"type":"resource","content":"OpenBSD : le manuel de sshd(8) (en anglais)","url":"https://man.openbsd.org/sshd"},{"type":"resource","content":"Manuel : last(1) et lastb(1), l’historique des connexions (util-linux) (en anglais)","url":"https://man7.org/linux/man-pages/man1/last.1@@util-linux.html"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"}]}'::jsonb, 24, 30, 2),
  ('c4d212cd-33bb-84a5-4f83-364e8f64acde', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'd1f9c8f6-6ed7-21f6-1f47-57215d368839', 'Traces d’exécution : auditd, historique des commandes et processus', 'Croise auditd, l’historique des commandes et les processus pour répondre à la vraie question : qui a lancé quoi, quand, et avec quelle force de preuve.', '{"blocks":[{"type":"callout","content":"Objectifs : lire un enregistrement auditd, convertir son epoch, distinguer « auid » et « uid », juger la valeur probante d’un historique shell, puis relier une exécution à une session plus large."},{"type":"callout","content":"Prérequis : avoir compris les journaux d’authentification Linux et savoir qu’une réussite SSH ne dit pas tout de ce qu’une personne ou un intrus a ensuite exécuté."},{"type":"callout","content":"Mise en situation : Koffi sait déjà qu’un compte s’est connecté en SSH. Ce qu’il doit maintenant établir, c’est l’action précise qui a suivi : simple maintenance, curiosité maladroite ou lecture d’un fichier sensible. Pour le démontrer proprement, il ne peut pas s’appuyer uniquement sur « auth.log ». Il doit croiser l’audit, l’historique du shell et les processus observés."},{"type":"callout","content":"Vidéo à venir : Relier une session SSH à une commande exécutée"},{"type":"text","content":"Les journaux d’authentification disent qu’une session existe. Ils ne suffisent pas à dire tout ce qui a été lancé ensuite. C’est le rôle de sources comme auditd, de l’historique du shell et des processus actifs. auditd est la source la plus solide des trois quand il est correctement configuré : il enregistre des appels système et associe une action à un identifiant de connexion d’origine, « auid ». Cet identifiant survit à « sudo », ce qui aide à relier une action root à la personne initialement connectée."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Auditd : champs à connaître\",\"columns\":2,\"items\":[{\"term\":\"`type=SYSCALL`\",\"text\":\"appel système et identité du contexte\",\"tone\":\"blue\"},{\"term\":\"`type=EXECVE`\",\"text\":\"arguments, comme `a0=` et `a1=`\",\"tone\":\"violet\"},{\"term\":\"`type=PATH`\",\"text\":\"chemin touché, par exemple `name=\\\"/etc/shadow\\\"`\",\"tone\":\"cyan\"},{\"term\":\"`msg=audit(epoch:seq)`\",\"text\":\"temps et numéro de séquence de l’événement\",\"tone\":\"green\"},{\"term\":\"`auid`\",\"text\":\"identité d’origine de la session\",\"tone\":\"amber\"},{\"term\":\"`uid`\",\"text\":\"identité effective au moment de l’action\",\"tone\":\"amber\"},{\"term\":\"`comm` / `exe`\",\"text\":\"nom court et chemin du binaire\",\"tone\":\"neutral\"},{\"term\":\"`key`\",\"text\":\"règle d’audit qui a produit l’événement\",\"tone\":\"red\"}]}"},{"type":"text","content":"L’historique « ~/.bash_history » a une valeur plus faible. Il s’écrit souvent à la fermeture du shell, il peut être modifié, désactivé ou incomplet. Avec « HISTTIMEFORMAT », tu récupères parfois une ligne « #epoch » avant chaque commande. C’est utile, mais pas suffisant pour accuser ou innocenter seul. Les processus du moment, lus avec « ps » ou « ss », sont encore plus volatils : ils montrent l’instant présent, pas toute l’histoire. La bonne pratique consiste donc à croiser ces sources, en notant leur force probante respective. Sur un vrai hôte Linux, « ausearch -k exec -ts today » regroupe justement les enregistrements d’un même événement partageant le même numéro de séquence."},{"type":"code","content":"# Relier une réussite SSH à une exécution auditée\ngrep ''Accepted password for awa'' auth-demo.log\ngrep ''msg=audit(1773130805.123:456)'' audit-demo.log\ndate -u -d @1773130805 ''+%Y-%m-%dT%H:%M:%SZ''\n# exemple de sortie (valeurs fictives)\n# Mar 10 08:16:31 web01 sshd[2201]: Accepted password for awa from 192.0.2.10 port 51240 ssh2\n# type=SYSCALL msg=audit(1773130805.123:456): arch=c000003e syscall=59 success=yes exit=0 auid=1001 uid=0 gid=0 tty=pts0 ses=17 comm=\"cat\" exe=\"/usr/bin/cat\" key=\"exec\"\n# type=EXECVE msg=audit(1773130805.123:456): argc=2 a0=\"cat\" a1=\"/etc/shadow\"\n# type=PATH msg=audit(1773130805.123:456): item=0 name=\"/etc/shadow\"\n# 2026-03-10T08:20:05Z","language":"bash"},{"type":"text","content":"Démonstration guidée : la lecture prudente est la suivante. Le compte « awa » s’est connecté avec succès. Quelques minutes plus tard, auditd émet trois enregistrements portant le même « msg=audit(...:456) ». Le premier, « type=SYSCALL », donne le contexte d’exécution, dont « auid=1001 » et « uid=0 ». Le deuxième, « type=EXECVE », montre les arguments « a0=\"cat\" » et « a1=\"/etc/shadow\" ». Le troisième, « type=PATH », confirme le chemin touché. Tu peux donc écrire : « une session ouverte par awa a exécuté cat sur /etc/shadow avec des privilèges root à 08:20:05Z ». Tu ne dis pas encore pourquoi, ni si cette lecture était autorisée. Le journal ne donne pas l’intention."},{"type":"code","content":"# Montrer pourquoi l’historique seul reste une preuve faible\ncat history-demo.txt\ngrep ''cat /etc/shadow'' ps-demo.txt\n# exemple de sortie (valeurs fictives)\n# #1773130798\n# sudo -i\n# #1773130805\n# cat /etc/shadow\n# #1773130820\n# exit\n# root     1012  0.0  0.0   3076  1048 pts/0    S+   08:20   0:00 cat /etc/shadow","language":"bash"},{"type":"text","content":"auditd demande cependant de la prudence de configuration. Une règle trop large génère beaucoup de volume et peut saturer le disque. Certains arguments capturés peuvent aussi révéler des secrets. Il faut donc choisir les points d’audit avec discernement : fichiers sensibles, exécutions critiques, changements d’identité. Quand l’audit manque, tu reviens aux autres traces : journal d’authentification, historique du shell, processus, connexions réseau et journaux applicatifs éventuels. Sur un serveur réel, « ausearch -k exec » sert à relire proprement les événements, et « aureport --auth » à résumer l’authentification."},{"type":"example","content":"Exemple corrigé : trois lignes d’historique qui montrent « sudo -i », « cat /etc/shadow », « exit » ne prouvent pas, seules, que la commande a vraiment été exécutée au moment affiché. Elles peuvent avoir été écrites après coup ou incomplètement. Si auditd confirme la même séquence avec « type=SYSCALL », « type=EXECVE », « auid=1001 », « uid=0 » et l’epoch convertie, ta reconstruction devient beaucoup plus solide. Le bon réflexe est donc : historique pour l’indice, auditd pour la preuve plus forte, processus pour le contexte immédiat."},{"type":"callout","content":"Erreurs fréquentes : prendre « bash_history » pour une preuve aussi forte qu’un audit ; oublier que « uid » et « auid » répondent à deux questions différentes ; lire un epoch sans le convertir proprement ; activer des règles d’audit trop larges au point de noyer ou de saturer le système."},{"type":"callout","content":"Sécurité : les journaux d’audit peuvent contenir des chemins sensibles, des noms de fichiers confidentiels et parfois des fragments de secrets. Analyse-les dans un cadre autorisé, sur une copie de travail si possible, et ne modifie pas la machine examinée plus que nécessaire tant que la collecte n’est pas stabilisée."},{"type":"callout","content":"À retenir : pour savoir qui a lancé quoi, croise les sources. auditd donne une trace solide si la règle existe. L’historique du shell est utile mais faible. Les processus montrent l’instant présent. La vraie qualité d’enquête vient du recoupement et de la conversion propre des temps."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Investigation SOC : reconstituer une intrusion complète » : suis une session depuis l’accès initial jusqu’aux exécutions sensibles, puis note ce que chaque source prouve vraiment. Termine par le quiz."},{"type":"resource","content":"Linux : manuel du démon d’audit auditd (en anglais)","url":"https://man7.org/linux/man-pages/man8/auditd.8.html"},{"type":"resource","content":"Manuel : auditctl(8), les règles d’audit (en anglais)","url":"https://man7.org/linux/man-pages/man8/auditctl.8.html"},{"type":"resource","content":"Manuel : ausearch(8), chercher dans les journaux d’audit (en anglais)","url":"https://man7.org/linux/man-pages/man8/ausearch.8.html"}]}'::jsonb, 24, 30, 3),
  ('0b688d54-a030-a103-9936-8f85077df556', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8d425d0f-033b-ed31-c89b-e193593fecef', 'Les journaux d’événements Windows : Security, System et Application', 'Repère les grands journaux Windows, lis la structure d’un événement, comprends ce que l’audit produit ou ne produit pas, puis filtre un export sans dépendre de l’Observateur d’événements.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer le rôle des journaux Security, System, Application et des journaux « Applications et services », lire les champs d’un événement, expliquer ce qu’une stratégie d’audit doit activer, filtrer un export avec PowerShell, puis reconnaître un effacement de journal comme un signal à vérifier."},{"type":"callout","content":"Prérequis : avoir suivi « D’où viennent les journaux : sources, formats et niveaux de gravité » et « Lire un événement dans un journal »."},{"type":"callout","content":"Mise en situation : Nadia reçoit d’un collègue un export « .evtx » et un CSV issus d’un poste Windows 11 de l’association Teranga. Le collègue a vu des ouvertures de session étranges, mais il n’est pas sûr d’avoir regardé le bon journal. Nadia doit d’abord choisir où lire, puis vérifier si les événements utiles existent vraiment avant d’interpréter quoi que ce soit."},{"type":"callout","content":"Vidéo à venir : Trouver le bon journal Windows avant de conclure"},{"type":"text","content":"Sous Windows, un événement n’est pas une simple ligne de texte : il appartient à un journal, a un fournisseur, un identifiant, un niveau, une heure et des données propres à son type. Les journaux les plus utilisés au début sont « Security » pour l’audit de sécurité, « System » pour le système et les services, « Application » pour les applications classiques, puis les journaux « Applications et services » pour des composants plus spécialisés comme PowerShell ou Sysmon. Les fichiers sont stockés au format « .evtx », que tu lis avec l’Observateur d’événements, « Get-WinEvent » ou « wevtutil »."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Journal Windows : ce qu’on y cherche souvent\",\"columns\":[\"Journal Windows\",\"Ce qu’on y cherche souvent\"],\"rows\":[[\"Security\",\"ouvertures de session, comptes, audit\"],[\"System\",\"services, pilotes, démarrages, arrêts\"],[\"Application\",\"erreurs et messages applicatifs\"],[\"Applications et services\",\"vue spécialisée par composant\"],[\"PowerShell\",\"blocs de script, journalisation du moteur\"],[\"Sysmon\",\"processus, DNS, réseau, fichiers\"]]}"},{"type":"text","content":"L’anatomie d’un événement reste stable d’un journal à l’autre : « EventID », fournisseur, machine, heure, niveau, puis un bloc de données. Dans le XML, « TimeCreated SystemTime » est écrit en UTC, ce qui est précieux pour une chronologie. L’Observateur d’événements l’affiche souvent en heure locale : ne mélange pas ces deux lectures sans noter le fuseau. Dans « Security », tu verras aussi des champs comme « TargetUserName », « IpAddress », « LogonType » ou « Status », mais seulement pour les événements qui les définissent."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Exemple de lecture d’un événement de sécurité\",\"columns\":[\"Champ\",\"Valeur\"],\"rows\":[[\"EventID\",\"4624\"],[\"Provider\",\"Microsoft-Windows-Security-Auditing\"],[\"Computer\",\"atelier-pc\"],[\"TimeCreated\",\"2026-03-10T08:15:21Z\"],[\"Data\",\"TargetUserName=awa\"],[\"Data\",\"LogonType=10\"],[\"Data\",\"IpAddress=192.168.1.77\"],[\"Data\",\"AuthenticationPackageName=Negotiate\"]],\"mono\":[1]}"},{"type":"text","content":"Le piège classique est de croire qu’un événement absent prouve qu’il ne s’est rien passé. Sous Windows, l’audit doit être activé pour produire les événements de sécurité utiles. Sans sous-catégorie d’audit adaptée, tu n’auras pas de 4624 ou de 4625 à analyser. Il faut aussi surveiller la taille maximale du journal et son mode d’écrasement : un journal trop petit écrase les vieux événements exactement quand tu as besoin d’eux. Enfin, lire « Security » demande souvent des droits d’administration, ce qui explique pourquoi un export CSV ou XML est pratique pour relire ailleurs un sous-ensemble autorisé. Pense aussi au 104 du fournisseur « Microsoft-Windows-Eventlog », souvent visible quand un journal Windows est effacé, et au 1102 dans « Security » : ce sont des signaux d’effacement à expliquer."},{"type":"text","content":"Démonstration guidée : sur Windows, tu peux exporter des événements puis filtrer la copie au lieu d’ouvrir le journal réel à chaque fois. Ici, le CSV est inventé mais dans un format banal : une ligne par événement, avec les champs utiles. La commande ci-dessous isole les identifiants 4624, 4625 et 1102. Le 1102 signifie que le journal d’audit de sécurité a été effacé : c’est un signal à expliquer, pas une preuve automatique de malveillance."},{"type":"code","content":"# Filtrer un export CSV d''événements Windows\nImport-Csv .\\windows-events.csv |\n  Where-Object { $_.Id -in ''4624'',''4625'',''1102'' } |\n  Select-Object TimeCreated, Id, TargetUserName, IpAddress, LogonType, Status |\n  Format-Table -AutoSize\n# exemple de sortie (valeurs fictives)\n# TimeCreated          Id   TargetUserName IpAddress    LogonType Status\n# -----------          --   -------------- ---------    --------- ------\n# 2026-03-10T08:14:52Z 4625 awa            192.168.1.77 10        0xC000006A\n# 2026-03-10T08:15:04Z 4625 awa            192.168.1.77 10        0xC000006A\n# 2026-03-10T08:15:21Z 4624 awa            192.168.1.77 10        -\n# 2026-03-10T08:20:35Z 4624 svc-sync       -            5         -\n# 2026-03-10T08:21:02Z 4625 nadia          192.168.1.90 2         0xC0000234\n# 2026-03-10T08:22:10Z 1102 -              -            -         -","language":"powershell"},{"type":"text","content":"Tu peux aussi interroger directement Windows avec « Get-WinEvent -FilterHashtable » ou « wevtutil qe », mais sur une machine partagée ou peu puissante, travailler sur un export réduit le risque d’erreur et facilite le partage interne. Garde en tête que ces journaux contiennent des noms de comptes, parfois des adresses IP et d’autres données personnelles. Un export doit être protégé comme une donnée sensible et ne pas partir vers un service tiers sans nécessité ni mandat."},{"type":"example","content":"Exemple corrigé : si tu lis un 4624 avec « TargetUserName=awa », « LogonType=10 », « IpAddress=192.168.1.77 » et « AuthenticationPackageName=Negotiate », tu peux dire : une session RDP réussie a été créée pour le compte « awa » depuis l’adresse interne « 192.168.1.77 ». Tu ne peux pas encore dire : c’était une attaque. Il te manque le contexte habituel du compte, la machine source réelle et les événements juste avant."},{"type":"callout","content":"Erreurs fréquentes : ouvrir seulement « Application » et oublier que l’audit de sécurité est ailleurs ; confondre heure locale affichée et heure UTC du XML ; croire qu’un identifiant absent prouve l’absence d’action alors que l’audit n’était peut-être pas activé ; exporter des journaux réels puis les envoyer hors de l’organisation sans précaution."},{"type":"callout","content":"Sécurité : Tu analyses les journaux de ton organisation ou d’un système pour lequel tu as un mandat écrit. Lire « Security » peut demander des droits élevés : privilégie un export limité quand c’est possible. Ne vide jamais un journal réel pour « faire propre » avant d’avoir suivi la procédure de conservation des preuves."},{"type":"callout","content":"À retenir : Sous Windows, il faut d’abord choisir le bon journal, puis lire l’événement dans sa structure complète. L’heure UTC du XML sert de référence. Un événement manquant peut venir d’une stratégie d’audit absente, et l’effacement du journal de sécurité mérite toujours une explication."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 2 : journaux Windows : sessions, comptes et PowerShell » : repère quel export correspond à « Security », filtre les identifiants utiles avec PowerShell, puis explique à quoi sert chaque champ avant de passer au quiz."},{"type":"resource","content":"Microsoft : la journalisation d’événements Windows","url":"https://learn.microsoft.com/fr-fr/windows/win32/eventlog/event-logging"},{"type":"resource","content":"Microsoft : l’applet de commande Get-WinEvent","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.diagnostics/get-winevent"},{"type":"resource","content":"Microsoft : événement 1102, effacement du journal d’audit","url":"https://learn.microsoft.com/fr-fr/previous-versions/windows/it-pro/windows-10/security/threat-protection/auditing/event-1102"}]}'::jsonb, 22, 30, 1),
  ('c045ce75-1795-2e49-69ca-372c2978faf4', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8d425d0f-033b-ed31-c89b-e193593fecef', 'Ouvertures de session et comptes : événements 4624, 4625, 4672 et 4720', 'Lis les principaux événements de session et de comptes sous Windows, interprète les types d’ouverture de session et les codes d’échec, puis groupe les traces par source et par compte sans confondre automatisme et intrusion.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer 4624 et 4625, relire les types de session les plus courants, interpréter des codes d’échec vérifiés, repérer un verrouillage ou une création de compte, compter les rafales par source avec PowerShell, puis formuler une conclusion prudente."},{"type":"callout","content":"Prérequis : avoir suivi « Les journaux d’événements Windows : Security, System et Application »."},{"type":"callout","content":"Mise en situation : Awa reçoit un export du journal « Security » d’un poste « pc-awa » et d’un serveur « srv-demo ». Plusieurs collègues se plaignent d’un verrouillage de compte et d’une session Bureau à distance inhabituelle. Awa doit séparer trois choses : le bruit normal des services, les erreurs de mot de passe humaines et une éventuelle séquence de connexion anormale."},{"type":"callout","content":"Vidéo à venir : Lire 4624 et 4625 comme un analyste prudent"},{"type":"text","content":"Les événements centraux ici sont 4624 pour une ouverture de session réussie et 4625 pour un échec. Microsoft documente aussi 4672 quand une nouvelle session reçoit des privilèges sensibles, 4720 quand un compte est créé, 4740 quand un compte est verrouillé, et 4648 quand un processus tente une ouverture de session avec des identifiants explicites. Tu verras souvent 4634 pour la fermeture de session. Chaque identifiant n’est qu’un morceau de l’histoire : c’est la séquence qui compte."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"LogonType à retenir d’abord\",\"columns\":[\"Type\",\"Nom\",\"Lecture rapide\"],\"rows\":[[\"2\",\"Interactive\",\"clavier local\"],[\"3\",\"Network\",\"accès réseau, partage, service distant\"],[\"4\",\"Batch\",\"tâche planifiée\"],[\"5\",\"Service\",\"service Windows\"],[\"7\",\"Unlock\",\"déverrouillage\"],[\"10\",\"RemoteInteractive\",\"RDP\"],[\"11\",\"CachedInteractive\",\"ouverture hors ligne avec cache\"]],\"mono\":[0,1]}"},{"type":"text","content":"Pour 4624 et 4625, les champs utiles sont souvent « SubjectUserName » et « SubjectDomainName » pour l’acteur qui tente ou lance l’action, puis « TargetUserName » et « TargetDomainName » pour le compte visé par l’ouverture de session. Tu ajoutes « LogonType », « AuthenticationPackageName », « WorkstationName », « IpAddress » et « IpPort ». Pour 4625, Microsoft documente aussi des codes d’échec utiles dans « Status » et parfois « SubStatus » : « 0xC000006A » pour un nom correct mais un mauvais mot de passe, « 0xC0000064 » pour un nom d’utilisateur inexistant, « 0xC0000234 » pour un compte verrouillé et « 0xC0000072 » pour un compte désactivé. Ne récite pas ces codes par cœur : lis-les dans les champs avant d’interpréter."},{"type":"text","content":"Le type de session t’aide à éviter les faux positifs. Un 4624 de type 5 correspond souvent à un service qui démarre, un type 4 à une tâche planifiée, un type 3 à un accès réseau comme un partage, et un type 10 à du Bureau à distance. Une alerte sur un compte de service peut donc être bénigne si elle correspond à son rôle attendu. Inversement, un type 10 depuis une machine qui n’utilise jamais RDP mérite de l’attention, surtout s’il suit plusieurs 4625 sur le même compte. Garde aussi la chronologie fine en tête : 4647 indique une déconnexion demandée par l’utilisateur, alors que 4634 signale surtout que la session se ferme ; ce n’est pas tout à fait la même histoire."},{"type":"text","content":"Démonstration guidée : commence par compter les échecs par source et par compte. La commande ci-dessous groupe tous les 4625 d’un export CSV inventé. Tu vois immédiatement qu’une même adresse a tenté plusieurs comptes, puis qu’un seul compte a été retenté plusieurs fois. C’est la différence entre arrosage, brute force ciblée et simple oubli de mot de passe."},{"type":"code","content":"# Compter les échecs 4625 par adresse et par compte\nImport-Csv .\\windows-sessions.csv |\n  Where-Object { $_.Id -eq ''4625'' } |\n  Group-Object IpAddress, TargetUserName |\n  Sort-Object Count -Descending |\n  Select-Object Count, Name |\n  Format-Table -AutoSize\n# exemple de sortie (valeurs fictives)\n# Count Name\n# ----- ----\n#     4 192.168.1.77, awa\n#     1 192.168.1.90, nadia\n#     1 192.168.1.77, koffi\n#     1 192.168.1.77, moussa\n#     1 192.168.1.77, ama","language":"powershell"},{"type":"schema","content":"{\"v\":1,\"kind\":\"timeline\",\"title\":\"Lecture prudente d’une séquence\",\"events\":[{\"at\":\"4625\",\"title\":\"Échec pour awa\",\"text\":\"type 10, 192.168.1.77, status 0xC000006A\",\"tone\":\"amber\"},{\"at\":\"4625\",\"title\":\"Nouvel échec pour awa\",\"text\":\"type 10, 192.168.1.77, status 0xC000006A\",\"tone\":\"amber\"},{\"at\":\"4624\",\"title\":\"Succès pour awa\",\"text\":\"type 10, 192.168.1.77\",\"tone\":\"green\"},{\"at\":\"4672\",\"title\":\"Privilèges sensibles\",\"text\":\"attribués à la nouvelle session\",\"tone\":\"red\"},{\"at\":\"4634\",\"title\":\"Fin de session\",\"text\":\"awa\",\"tone\":\"blue\"}],\"caption\":\"Série à vérifier, pas preuve suffisante seule.\"}"},{"type":"text","content":"Quand tu vois 4720, tu regardes qui a créé le compte et depuis quelle session. Si, juste après, tu observes 4728 ou 4732, donc un ajout à un groupe de sécurité, l’histoire devient plus lourde. Selon l’environnement, 4768, 4769, 4771 ou 4776 peuvent compléter la même enquête côté Kerberos ou NTLM : ils aident à comprendre quel protocole a porté l’authentification, pas à remplacer 4624 et 4625. Enfin, 4648 apparaît souvent avec « RUNAS » ou certaines tâches : ce n’est pas malveillant par nature, mais utile pour comprendre quel processus a utilisé des identifiants explicites. Et 4740 te donne au minimum le compte verrouillé à pivoter avec les échecs précédents."},{"type":"example","content":"Exemple corrigé : la séquence « 4625 awa type 10 depuis 192.168.1.77 », répétée deux fois, puis « 4624 awa type 10 » et juste après « 4672 awa » raconte ceci : une session RDP du compte « awa » a finalement réussi depuis cette adresse, et cette session dispose de privilèges sensibles. Tu ne peux pas encore affirmer une compromission, mais tu as assez d’indices pour pivoter vers la machine source, l’horaire habituel du compte et les événements de processus qui suivent."},{"type":"callout","content":"Erreurs fréquentes : lire un type 5 comme une session humaine alors qu’il s’agit d’un service ; oublier qu’un compte verrouillé génère un code précis dans 4625 ; traiter un 4672 isolé comme une preuve d’attaque alors qu’un compte administrateur légitime peut le produire ; bloquer trop vite une adresse partagée sans vérifier le contexte métier."},{"type":"callout","content":"Sécurité : Ces journaux relient des comptes à des machines et parfois à des personnes. Tu les traites comme des données à protéger. Si tu dois surveiller des salariés ou des comptes nominatifs, applique la politique de ton organisation, l’information préalable et la proportionnalité attendues par le cadre légal."},{"type":"callout","content":"À retenir : Les événements de session Windows se lisent en séquence, pas un par un. Le type d’ouverture, l’adresse source et le code d’échec changent totalement l’interprétation. Les comptes de service et les tâches planifiées expliquent beaucoup de bruit, mais une réussite inattendue après plusieurs échecs reste un pivot fort."},{"type":"callout","content":"Pour pratiquer : Dans « TP 2 : journaux Windows : sessions, comptes et PowerShell », groupe les 4625 par source, relis une séquence 4625 puis 4624 puis 4672, et explique quels comptes relèvent d’un service, d’une tâche ou d’une session humaine avant le quiz."},{"type":"resource","content":"Microsoft : événement 4624, ouverture de session réussie","url":"https://learn.microsoft.com/fr-fr/previous-versions/windows/it-pro/windows-10/security/threat-protection/auditing/event-4624"},{"type":"resource","content":"Microsoft : événement 4625, échec d’ouverture de session","url":"https://learn.microsoft.com/fr-fr/previous-versions/windows/it-pro/windows-10/security/threat-protection/auditing/event-4625"},{"type":"resource","content":"Microsoft : les types d’ouverture de session","url":"https://learn.microsoft.com/fr-fr/windows-server/identity/securing-privileged-access/reference-tools-logon-types"}]}'::jsonb, 24, 30, 2),
  ('af9b35ee-f81b-ca2a-79f4-da5f14c036af', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8d425d0f-033b-ed31-c89b-e193593fecef', 'Processus, Sysmon et PowerShell : reconstituer une exécution', 'Comprends ce que le journal Security ne montre pas toujours, ce que Sysmon ajoute, comment la journalisation PowerShell complète la vue, puis relie processus, DNS, réseau et fichier pour raconter une exécution.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer les limites de 4688, distinguer ce que Sysmon ajoute, relier des événements par « ProcessGuid », décoder une commande PowerShell encodée, reconnaître des parentés de processus suspectes, puis reconstituer une exécution en quatre étapes."},{"type":"callout","content":"Prérequis : avoir suivi « Ouvertures de session et comptes : événements 4624, 4625, 4672 et 4720 »."},{"type":"callout","content":"Mise en situation : Moussa reçoit l’export d’un poste « atelier-pc » sur lequel un document Word a été ouvert juste avant un trafic réseau étrange. Le journal « Security » montre bien des ouvertures de session, mais pas assez de détails sur les processus. Moussa doit décider s’il lui faut Sysmon, les journaux PowerShell ou les deux pour raconter ce que le poste a exécuté."},{"type":"callout","content":"Vidéo à venir : Relier Word, PowerShell, DNS et réseau dans les traces Windows"},{"type":"text","content":"Le journal « Security » peut produire 4688 quand un processus démarre, mais la ligne de commande n’y apparaît que si la stratégie dédiée est activée. C’est utile, pas suffisant. Sysmon, lui, n’est pas présent par défaut : c’est un service à installer avec une configuration. Une fois actif, il écrit dans « Microsoft-Windows-Sysmon/Operational » et ajoute des détails précieux comme la ligne de commande complète, les hachages, les parents, les connexions réseau, les créations de fichiers, les chargements d’image, certaines actions sur le registre et les requêtes DNS."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Comparer les sources\",\"columns\":[\"Source\",\"Ce qu’elle apporte\"],\"rows\":[[\"4688 Security\",\"nouveau processus, selon la stratégie\"],[\"Sysmon 1\",\"image, ligne de commande, parent, hachages\"],[\"Sysmon 3\",\"connexion réseau liée au processus\"],[\"Sysmon 7\",\"image chargée dans un processus\"],[\"Sysmon 8 et 10\",\"thread distant ou accès à un processus\"],[\"Sysmon 11\",\"fichier créé ou remplacé\"],[\"Sysmon 12 à 14\",\"création, suppression ou modification du registre\"],[\"Sysmon 22\",\"requête DNS liée au processus\"],[\"PowerShell 4103\",\"journalisation de module\"],[\"PowerShell 4104\",\"contenu d’un bloc de script si activée\"]],\"mono\":[0]}"},{"type":"text","content":"Microsoft documente pour Sysmon l’intérêt de « ProcessGuid » : il reste stable pour la corrélation même si l’identifiant numérique du processus est réutilisé plus tard. C’est la clé idéale pour suivre une exécution de l’événement 1 vers l’événement 3 ou 22. Les champs utiles à retenir sont « Image », « CommandLine », « ParentImage », « ParentCommandLine », « User », « ProcessGuid », « QueryName », « QueryResults », « DestinationIp » et « DestinationPort ». Tu ne juges pas un seul champ : tu combines la parenté, le contexte utilisateur et la suite des actions."},{"type":"text","content":"Pour PowerShell, 4103 enregistre surtout l’activité du module et 4104 le texte des blocs de script quand la journalisation est activée. C’est précieux quand une commande a été passée via « -EncodedCommand ». Cette chaîne est du Base64 en UTF-16LE : tu peux la décoder localement avec PowerShell sans rejouer la commande. Attention : les journaux PowerShell et Sysmon peuvent contenir des secrets ou des chemins sensibles. On les protège comme n’importe quelle preuve."},{"type":"text","content":"Démonstration guidée : le fichier JSON lignes ci-dessous est inventé, mais il respecte le style d’une télémétrie exportée. La commande relit les événements 1, 3 et 22, puis décode la commande PowerShell encodée. L’intérêt n’est pas la charge utile, ici volontairement bénigne, mais la méthode de lecture : parent, DNS, réseau, puis fichier ou autre effet visible."},{"type":"code","content":"# Relire des événements Sysmon exportés en JSON lignes\n$events = Get-Content .\\sysmon.jsonl | ForEach-Object { $_ | ConvertFrom-Json }\n$events | Where-Object { $_.EventID -in 1,3,22 } | ForEach-Object {\n  ''{0} id={1} image={2} parent={3} dns={4} dst={5}:{6} guid={7}'' -f $_.UtcTime, $_.EventID, $_.Image, $_.ParentImage, $_.QueryName, $_.DestinationIp, $_.DestinationPort, $_.ProcessGuid\n}\n$commandLine = ($events | Where-Object { $_.EventID -eq 1 -and $_.Image -like ''*powershell.exe'' } | Select-Object -First 1).CommandLine\n$encoded = [regex]::Match($commandLine, ''(?i)(?:-EncodedCommand|-enc)\\s+([A-Za-z0-9+/=]+)'').Groups[1].Value\n[Text.Encoding]::Unicode.GetString([Convert]::FromBase64String($encoded))\n# exemple de sortie (valeurs fictives)\n# 2026-03-10 08:30:00.100 id=1 image=C:\\Program Files\\Microsoft Office\\root\\Office16\\WINWORD.EXE parent=C:\\Windows\\explorer.exe dns= dst=: guid={11111111-1111-1111-1111-111111111111}\n# 2026-03-10 08:30:02.220 id=1 image=C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe parent=C:\\Program Files\\Microsoft Office\\root\\Office16\\WINWORD.EXE dns= dst=: guid={22222222-2222-2222-2222-222222222222}\n# 2026-03-10 08:30:03.010 id=22 image=C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe parent= dns=cdn-status.example.org dst=: guid={22222222-2222-2222-2222-222222222222}\n# 2026-03-10 08:30:03.600 id=3 image=C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe parent= dns= dst=192.0.2.44:443 guid={22222222-2222-2222-2222-222222222222}\n# Get-ChildItem C:\\Users\\Public | Select-Object -First 3","language":"powershell"},{"type":"schema","content":"{\"v\":1,\"kind\":\"flow\",\"title\":\"Indices forts sans automatisme\",\"nodes\":[{\"label\":\"WINWORD.EXE\",\"text\":\"lance `powershell.exe`\",\"icon\":\"document\",\"tone\":\"amber\"},{\"label\":\"`powershell.exe`\",\"text\":\"parenté inhabituelle\",\"icon\":\"terminal\",\"tone\":\"red\"},{\"label\":\"Requête DNS\",\"text\":\"pivot vers le domaine\",\"icon\":\"network\",\"tone\":\"violet\"},{\"label\":\"`192.0.2.44:443`\",\"text\":\"pivot vers la connexion\",\"icon\":\"internet\",\"tone\":\"blue\"},{\"label\":\"Fichier temp\",\"text\":\"effet local observable\",\"icon\":\"file\",\"tone\":\"green\"}]}"},{"type":"text","content":"Certaines parentés attirent l’attention : un document Office qui lance « powershell.exe » ou « cmd.exe », ou un processus serveur web qui lance un interpréteur. Ce sont des indices, pas une preuve. Un administrateur peut avoir de bonnes raisons, un produit métier aussi. L’important est la chaîne complète : qui a lancé quoi, avec quelle ligne de commande, vers quel domaine, puis vers quelle adresse, et quel fichier ou autre artefact apparaît ensuite."},{"type":"example","content":"Exemple corrigé : tu peux raconter l’exécution fictive ainsi. Étape 1, « WINWORD.EXE » est ouvert par « awa ». Étape 2, il lance « powershell.exe » avec une commande encodée. Étape 3, ce même « ProcessGuid » effectue une requête DNS pour « cdn-status.example.org », puis une connexion HTTPS vers « 192.0.2.44 ». Étape 4, un fichier temporaire apparaît. Ce n’est pas une preuve suffisante d’infection à lui seul, mais c’est une chronologie nette qui justifie un pivot vers les journaux web, proxy ou EDR."},{"type":"callout","content":"Erreurs fréquentes : attendre de Sysmon qu’il existe partout alors qu’il est absent par défaut ; confondre « ProcessId » et « ProcessGuid » lors d’une corrélation ; décoder une commande puis la réexécuter par curiosité ; oublier que les journaux de script peuvent contenir des secrets ou des données internes."},{"type":"callout","content":"Sécurité : Tu analyses seulement des exports autorisés de ta propre organisation. Ne lance jamais une commande encodée lue dans un journal sur une machine réelle pour « voir ce qu’elle fait ». Décode-la en texte, travaille sur une copie et conserve les exports comme des preuves sensibles."},{"type":"callout","content":"À retenir : 4688 donne un point de départ, Sysmon ajoute le détail, et la journalisation PowerShell peut révéler le contenu d’un script. Le meilleur pivot est souvent « ProcessGuid ». Une parenté inhabituelle attire l’attention, mais c’est la chaîne complète qui construit l’analyse."},{"type":"callout","content":"Pour pratiquer : Dans « TP 2 : journaux Windows : sessions, comptes et PowerShell », relie un processus PowerShell à une requête DNS, une connexion réseau et une commande encodée décodée proprement, puis réponds au quiz."},{"type":"resource","content":"Microsoft : événement 4688, création d’un processus","url":"https://learn.microsoft.com/fr-fr/previous-versions/windows/it-pro/windows-10/security/threat-protection/auditing/event-4688"},{"type":"resource","content":"Microsoft : Sysmon, le moniteur système de Sysinternals","url":"https://learn.microsoft.com/fr-fr/sysinternals/downloads/sysmon"},{"type":"resource","content":"Microsoft : la journalisation de PowerShell","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.core/about/about_logging_windows"}]}'::jsonb, 24, 30, 3),
  ('471c0b05-57de-a3a0-f60c-2c0e8ae9dde3', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '855f3363-e64e-319b-81d6-4e39a7693320', 'Les journaux d’accès web : format, codes HTTP et agents utilisateurs', 'Décompose une ligne « combined », comprends ce qu’elle montre et ce qu’elle ne montre pas, puis compte les clients, les codes et les chemins les plus visibles avec des commandes simples.', '{"blocks":[{"type":"callout","content":"Objectifs : lire une ligne de journal d’accès web champ par champ, expliquer les familles de codes HTTP, reconnaître les limites du référent et de l’agent utilisateur, compter les requêtes par adresse et par code, puis distinguer le journal d’accès du journal d’erreurs."},{"type":"callout","content":"Prérequis : avoir suivi « Lire un événement dans un journal »."},{"type":"callout","content":"Mise en situation : Fatou administre le site vitrine de la coopérative Harmattan. Le site répond encore, mais elle reçoit des plaintes sur des lenteurs et quelques erreurs aléatoires. Avant de parler d’attaque, elle veut lire le format des accès, voir quels clients parlent le plus, quels codes reviennent et si les erreurs viennent du client ou du serveur."},{"type":"callout","content":"Vidéo à venir : Lire un journal d’accès web sans se noyer"},{"type":"text","content":"Le format « combined », courant sur Apache et nginx, écrit une ligne par requête servie. Dans Apache, on le résume souvent par « %h %l %u %t \\\"%r\\\" %>s %b \\\"%{Referer}i\\\" \\\"%{User-Agent}i\\\" ». Dans nginx, le format prédéfini « combined » est « $remote_addr - $remote_user [$time_local] \\\"$request\\\" $status $body_bytes_sent \\\"$http_referer\\\" \\\"$http_user_agent\\\" ». On y voit l’adresse du client, l’identité éventuelle, la date, la requête HTTP, le code de statut, la taille du corps de réponse, le référent et l’agent utilisateur. Le champ Apache « %t » et la variable nginx « $time_local » gardent le fuseau horaire, par exemple « [10/Mar/2026:09:00:01 +0000] ». Avec Apache, « %b » écrit « - » quand aucun octet de corps n’est envoyé, alors que nginx « $body_bytes_sent » écrit un nombre. Le journal d’accès est écrit après la réponse : il te montre donc le résultat visible côté serveur web, pas le corps d’un « POST » ni tout le contexte applicatif."},{"type":"schema","content":"{\"v\":1,\"kind\":\"packet\",\"title\":\"Lire une ligne d’accès web « combined »\",\"rows\":[{\"label\":\"Première moitié\",\"fields\":[{\"name\":\"Adresse\",\"note\":\"192.168.1.20\",\"weight\":2,\"tone\":\"blue\"},{\"name\":\"Date et fuseau\",\"note\":\"[10/Mar/2026:09:00:01 +0000]\",\"weight\":4,\"tone\":\"violet\"}]},{\"label\":\"Seconde moitié\",\"fields\":[{\"name\":\"Requête\",\"note\":\"\\\"GET / HTTP/1.1\\\"\",\"weight\":3,\"tone\":\"green\"},{\"name\":\"Code\",\"note\":\"200\",\"weight\":1,\"tone\":\"amber\"},{\"name\":\"Octets\",\"note\":\"5120\",\"weight\":1,\"tone\":\"cyan\"},{\"name\":\"Référent\",\"note\":\"\\\"-\\\"\",\"weight\":1,\"tone\":\"neutral\"},{\"name\":\"User-Agent\",\"note\":\"\\\"Mozilla/5.0\\\"\",\"weight\":2,\"tone\":\"red\"}]}]}"},{"type":"text","content":"Les familles de codes HTTP servent d’abord à classer. Les « 2xx » indiquent un succès, les « 3xx » une redirection, les « 4xx » une erreur côté client, par exemple 401 pour une requête non authentifiée, 403 pour un accès interdit, 404 pour une ressource introuvable et 429 pour trop de requêtes, et les « 5xx » une erreur côté serveur ou de passerelle, par exemple 500, 502 ou 503. Un 404 isolé n’est pas forcément grave. Une rafale de 404 sur des chemins très différents ou un groupe de 500 sur la même page raconte déjà autre chose."},{"type":"text","content":"Le référent et l’agent utilisateur sont utiles, mais falsifiables. Ils aident à comprendre un parcours ou à repérer un robot bruyant, pas à prouver l’identité d’une personne. Derrière un proxy inverse ou un CDN, l’adresse apparente peut être celle du proxy si la chaîne « X-Forwarded-For » n’est pas correctement traitée. Et si une requête est en « POST », le journal d’accès n’enregistre pas son corps : une erreur d’authentification applicative devra souvent être confirmée dans les journaux de l’application."},{"type":"text","content":"Démonstration guidée : avec un fichier « access.log » inventé, tu peux déjà produire un mini tableau de bord. Les commandes ci-dessous donnent les adresses les plus bavardes, les codes les plus fréquents, les chemins les plus demandés et la charge par minute. Elles tournent dans Git Bash et restent lisibles sur un poste Windows modeste."},{"type":"code","content":"# Top des adresses, des codes et des chemins\nawk ''{print $1}'' access.log | sort | uniq -c | sort -rn | head -5\nawk ''{print $9}'' access.log | sort | uniq -c | sort -n\nawk -F''\"'' ''{print $2}'' access.log | awk ''{print $2}'' | sort | uniq -c | sort -rn | head -5\nawk ''{gsub(/\\[/, \"\", $4); print substr($4,1,17)}'' access.log | sort | uniq -c | sort -rn | head -5\n# exemple de sortie (valeurs fictives)\n#      10 192.168.1.77\n#       8 192.168.1.21\n#       7 192.168.1.44\n#       4 192.168.1.63\n#       4 192.168.1.30\n#\n#       1 403\n#       1 502\n#       1 503\n#       2 302\n#       2 429\n#       2 500\n#       3 404\n#       5 401\n#      24 200\n#\n#      10 /login\n#       4 /intranet\n#       4 /admin/login\n#       3 /profile\n#       3 /api/orders\n#\n#       9 10/Mar/2026:09:04\n#       7 10/Mar/2026:09:03\n#       6 10/Mar/2026:09:02","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"compare\",\"title\":\"Accès vs erreurs\",\"sides\":[{\"title\":\"`access.log`\",\"tone\":\"blue\",\"items\":[\"qui a demandé quoi\",\"quand\",\"avec quel code\"],\"mark\":\"dot\"},{\"title\":\"`error.log`\",\"tone\":\"red\",\"items\":[\"pourquoi le serveur a échoué\",\"pourquoi le service a échoué\"],\"mark\":\"dot\"}],\"verdict\":\"404 sur un chemin rare : `access.log` d’abord. 500 répétés sur `/intranet` : `access.log` puis `error.log`.\"}"},{"type":"text","content":"Quand tu vois beaucoup de « 5xx », le journal d’erreurs devient indispensable, car lui seul dit souvent pourquoi le serveur a échoué. À l’inverse, pour mesurer un balayage de chemins ou un client bruyant, le journal d’accès suffit souvent. N’oublie jamais que ces journaux contiennent des adresses IP, parfois des identifiants dans l’URL et des habitudes de navigation : ils doivent être protégés, archivés avec prudence et partagés seulement si c’est nécessaire."},{"type":"example","content":"Exemple corrigé : dans l’extrait ci-dessus, « 192.168.1.77 » est le client le plus bavard, « /login » est la page la plus demandée, et « /admin/login » apparaît assez souvent pour mériter une lecture de séquence avec ses 401 puis son 200. Les « 500 », « 502 » et « 503 » concentrés sur « /intranet » racontent plutôt un problème côté service ou passerelle qu’un simple lien cassé."},{"type":"callout","content":"Erreurs fréquentes : prendre le « User-Agent » pour une identité fiable ; oublier qu’un 200 peut être banal ou inquiétant selon le chemin ; conclure depuis le seul journal d’accès quand un « POST » ou une erreur applicative exige d’autres sources ; publier des journaux web complets alors qu’ils contiennent des données personnelles."},{"type":"callout","content":"Sécurité : Tu analyses les journaux de ton organisation ou d’un environnement d’exercice autorisé. Ne place jamais de secrets dans une URL, car ils se retrouveraient dans les journaux. Si tu partages un extrait, retire ce qui n’est pas nécessaire et garde la trace du fichier d’origine."},{"type":"callout","content":"À retenir : Le format « combined » raconte l’adresse, la date, la requête, le code et quelques indices de contexte. Les familles de codes servent à trier, pas à juger seules. Le journal d’accès montre le résultat visible, tandis que le journal d’erreurs explique souvent le pourquoi."},{"type":"callout","content":"Pour pratiquer : Dans « Intrusion web : du scan au webshell », commence par relire chaque ligne au format « combined », compte les 404, 401, 200 et 5xx, puis compare cette vue de format à la chronologie d’investigation déjà publiée avant le quiz."},{"type":"resource","content":"Apache : le format des journaux (mod_log_config) (en anglais)","url":"https://httpd.apache.org/docs/2.4/mod/mod_log_config.html"},{"type":"resource","content":"nginx : le module de journalisation des accès (en anglais)","url":"https://nginx.org/en/docs/http/ngx_http_log_module.html"},{"type":"resource","content":"MDN : les codes de statut HTTP","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Status"}]}'::jsonb, 22, 30, 1),
  ('6712fc42-6c85-9c15-7359-c51e147b0350', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '855f3363-e64e-319b-81d6-4e39a7693320', 'Reconnaître scans, injections et force brute dans les accès web', 'Apprends à reconnaître dans les journaux d’accès les traces de balayage, de force brute, d’injection ou de traversée, puis à distinguer bruit opportuniste et séquence plus ciblée.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître une rafale de 404 comme un balayage possible, distinguer une force brute d’un simple oubli de mot de passe, repérer dans les URL des indices d’injection SQL, de traversée ou de script, relier un succès probable à ce qui le précède, puis classer une séquence sans tirer de conclusion trop large."},{"type":"callout","content":"Prérequis : avoir suivi « Les journaux d’accès web : format, codes HTTP et agents utilisateurs »."},{"type":"callout","content":"Mise en situation : Koffi doit relire les accès du site de Baobab Tech après un signalement : l’équipe a vu des pages d’administration consultées hors horaire et un fichier étrange dans un dossier de téléversement. Koffi n’a pas le droit de rejouer les URL, seulement de lire les traces. Son travail est donc de reconnaître des motifs dans les accès, puis de séparer le bruit opportuniste d’une séquence plus dangereuse."},{"type":"callout","content":"Vidéo à venir : Reconnaître une intrusion web sans rejouer l’attaque"},{"type":"text","content":"Dans un journal d’accès, beaucoup d’attaques se voient d’abord comme des motifs. Un scanner opportuniste enchaîne souvent des 404 sur des chemins connus comme « /admin », « /.env » ou « /.git/config ». Une force brute sur une page de connexion produit des « POST » répétés vers la même URL, avec des 401, 403 ou parfois des 200 et 302 selon l’application. Une injection SQL laisse souvent des signes dans l’URL : apostrophe encodée, « UNION SELECT », « OR 1=1 ». Une traversée de répertoires montre « ../ » ou son encodage en pourcentage."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Quelques signatures à reconnaître\",\"columns\":[\"Motif visible\",\"Lecture prudente\"],\"rows\":[[\"404 404 403 sur chemins sensibles\",\"sondage ou scan\"],[\"POST /login répété + 401\",\"brute force probable\"],[\"id=7%27 puis UNION SELECT\",\"injection SQL à lire\"],[\"file=%2e%2e%2f...\",\"traversée de répertoires\"],[\"/uploads/rapport.php?cmd=...\",\"appel d’un fichier téléversé\"]]}"},{"type":"text","content":"Le piège est de lire une seule URL comme une preuve. Une requête contenant « %27 » peut être un test isolé sans effet. Une requête vers « /admin », « /.env » ou un fichier téléversé prouve seulement que le serveur web a reçu cette demande et qu’il a répondu par tel code ; elle ne prouve ni une exécution de code, ni un vol de données à elle seule. Ce qui compte est la séquence : quels chemins ont été sondés avant, quel code est revenu, puis qu’est-ce qui a suivi. Un 200 ou un 302 sur un chemin d’administration juste après plusieurs échecs vaut davantage qu’un 404 isolé. De même, l’agent utilisateur « curl » ou « python-requests » est utile, mais pas définitif : il peut être falsifié ou tout simplement utilisé par un administrateur en test."},{"type":"text","content":"Démonstration guidée : le fichier ci-dessous contient douze accès inventés, tous au format réel. La première commande isole les lignes qui portent des indices d’injection, de traversée, de script ou d’appel d’un fichier téléversé. La seconde relit les réponses 200 et 302 pour chercher un succès probable après la phase de bruit ou de sondage."},{"type":"code","content":"# Repérer des motifs web à vérifier\ngrep -nEi ''%27|UNION|%2e%2e|%3Cscript%3E|/uploads/.*\\.php\\?cmd='' access-attaque.log\nprintf ''\\nSucces probables\\n''\nawk ''$9 ~ /200|302/ {print NR \":\" $0}'' access-attaque.log\n# exemple de sortie (valeurs fictives)\n# 8:192.168.1.77 - - [10/Mar/2026:10:10:21 +0000] \"GET /report?id=7%27 HTTP/1.1\" 500 640 \"-\" \"curl/8.5.0\"\n# 9:192.168.1.77 - - [10/Mar/2026:10:10:24 +0000] \"GET /report?id=-1%20UNION%20SELECT%201,2 HTTP/1.1\" 200 840 \"-\" \"curl/8.5.0\"\n# 10:192.168.1.77 - - [10/Mar/2026:10:10:28 +0000] \"GET /download?file=%2e%2e%2f%2e%2e%2fwin.ini HTTP/1.1\" 403 220 \"-\" \"curl/8.5.0\"\n# 11:192.168.1.60 - - [10/Mar/2026:10:11:00 +0000] \"GET /uploads/rapport.php?cmd=REDACTED HTTP/1.1\" 200 128 \"https://example.org/uploads/fiche.pdf\" \"Mozilla/5.0\"\n# 12:192.168.1.60 - - [10/Mar/2026:10:11:04 +0000] \"GET /search?q=%3Cscript%3Ealert(1)%3C/script%3E HTTP/1.1\" 200 980 \"https://example.org/\" \"Mozilla/5.0\"\n#\n# Succes probables\n# 4:192.168.1.77 - - [10/Mar/2026:10:10:08 +0000] \"GET /admin/login HTTP/1.1\" 200 1180 \"-\" \"curl/8.5.0\"\n# 7:192.168.1.77 - - [10/Mar/2026:10:10:18 +0000] \"POST /admin/login HTTP/1.1\" 200 512 \"https://example.org/admin/login\" \"curl/8.5.0\"\n# 9:192.168.1.77 - - [10/Mar/2026:10:10:24 +0000] \"GET /report?id=-1%20UNION%20SELECT%201,2 HTTP/1.1\" 200 840 \"-\" \"curl/8.5.0\"\n# 11:192.168.1.60 - - [10/Mar/2026:10:11:00 +0000] \"GET /uploads/rapport.php?cmd=REDACTED HTTP/1.1\" 200 128 \"https://example.org/uploads/fiche.pdf\" \"Mozilla/5.0\"\n# 12:192.168.1.60 - - [10/Mar/2026:10:11:04 +0000] \"GET /search?q=%3Cscript%3Ealert(1)%3C/script%3E HTTP/1.1\" 200 980 \"https://example.org/\" \"Mozilla/5.0\"","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"compare\",\"title\":\"Scanner opportuniste vs attaque plus ciblée\",\"sides\":[{\"title\":\"Opportuniste\",\"tone\":\"amber\",\"items\":[\"beaucoup de chemins\",\"peu ou pas de succès\"],\"mark\":\"dot\"},{\"title\":\"Plus ciblée\",\"tone\":\"red\",\"items\":[\"moins de bruit\",\"un succès\",\"puis de nouveaux chemins\"],\"mark\":\"dot\"}],\"verdict\":\"Signal fort : 404 404 403 200 sur `/admin/login`, puis 200 sur `/admin/export`.\"}"},{"type":"text","content":"Le succès final est souvent ce qui départage le bruit d’une séquence plus sérieuse. Un 200 sur « /admin/export » juste après plusieurs « POST /admin/login » vaut plus qu’un balayage de 404. De même, un appel à « /uploads/rapport.php?cmd=... » signale qu’un fichier téléversé exécutable a peut-être été appelé, mais ce journal ne te dit ni son contenu ni son impact exact. Tu devras pivoter vers les journaux applicatifs, système, ou vers une chronologie plus large."},{"type":"text","content":"Dans toutes ces lectures, reste défensif. Tu ne reproduis pas les charges vues dans les traces. Tu les reconnais seulement pour protéger ton système. Et tu rappelles que ces journaux contiennent des données personnelles et parfois des paramètres sensibles : ils restent internes, protégés et partagés seulement selon le besoin."},{"type":"example","content":"Exemple corrigé : la suite « 404, 404, 403, 200 sur /admin/login », puis « POST /admin/login 200 », puis « GET /admin/export 200 » se lit comme une exploration suivie d’une authentification probablement réussie et d’un accès à une ressource sensible. Ce n’est plus du simple bruit de scan. Il faut alors corréler avec l’application, les comptes et les autres journaux avant de mesurer l’impact."},{"type":"callout","content":"Erreurs fréquentes : prendre toute rafale de 404 pour une compromission ; oublier qu’une application peut répondre 200 à une erreur métier ; traiter un « ?cmd= » comme une preuve définitive sans autre source ; recopier une URL d’attaque dans un navigateur de test au lieu de la lire comme une preuve."},{"type":"callout","content":"Sécurité : Tu reconnais des attaques uniquement dans les traces de tes propres systèmes ou d’un exercice autorisé. Tu ne rejoues pas les URL offensives vues dans les journaux contre un tiers. Travaille sur des copies locales et masque ce qui n’est pas nécessaire dans les extraits partagés."},{"type":"callout","content":"À retenir : Les motifs comptent plus qu’une ligne isolée. Cherche la séquence complète : sondage, échec, succès probable, puis action sur une ressource sensible. Le code de réponse, le chemin et l’ordre temporel aident à distinguer bruit opportuniste et incident à investiguer."},{"type":"callout","content":"Pour pratiquer : Dans « Intrusion web : du scan au webshell », repère le moment où le bruit devient une séquence crédible, note les 404, 401, 403, 200 et 302 utiles, puis compare ta lecture avec l’investigation détaillée avant le quiz."},{"type":"resource","content":"OWASP : l’attaque par force brute (en anglais)","url":"https://owasp.org/www-community/attacks/Brute_force_attack"},{"type":"resource","content":"OWASP : l’injection SQL (en anglais)","url":"https://owasp.org/www-community/attacks/SQL_Injection"},{"type":"resource","content":"OWASP : la traversée de répertoires (en anglais)","url":"https://owasp.org/www-community/attacks/Path_Traversal"}]}'::jsonb, 24, 30, 2),
  ('f3295f6a-0338-999a-fd6d-e7e10c60a0d4', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '855f3363-e64e-319b-81d6-4e39a7693320', 'Journaux applicatifs et bases de données : ce qu’il faut y chercher', 'Lis des journaux applicatifs structurés, cherche les événements métier qui comptent, relie une requête web à l’application puis à la base, et évite les fuites de secrets dans les traces.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître un journal applicatif structuré, expliquer ce qu’une application devrait ou ne devrait jamais journaliser, filtrer du JSON lignes avec « jq » et PowerShell, relier un identifiant de requête à plusieurs sources, puis repérer des signes utiles côté base de données."},{"type":"callout","content":"Prérequis : avoir suivi « Les journaux d’accès web : format, codes HTTP et agents utilisateurs »."},{"type":"callout","content":"Mise en situation : Ama maintient une petite API qui alimente le site de Cabinet Moussa. Le journal web montre des exports et des erreurs 500, mais Ama veut savoir quel compte applicatif était concerné, quelle requête a échoué et si la base de données a vu la même histoire. Elle doit donc passer du serveur web aux journaux applicatifs, puis au journal de base."},{"type":"callout","content":"Vidéo à venir : Relier une requête web, l’application et la base de données"},{"type":"text","content":"Les journaux applicatifs parlent le langage du métier. Là où le serveur web voit une URL et un code, l’application peut écrire « login failed », « rôle changed », « export started » ou « password reset requested ». Le format le plus pratique pour les outils est souvent le JSON lignes : un objet JSON par ligne. C’est facile à filtrer, à grouper et à corréler, à condition que chaque ligne garde des champs stables comme l’heure, le niveau, le service, l’identifiant de requête et, si besoin, l’utilisateur ou l’adresse source. Les niveaux les plus courants restent « DEBUG », « INFO », « WARN », « ERROR » et parfois « FATAL » : ils aident à trier, pas à conclure seuls."},{"type":"schema","content":"{\"v\":1,\"kind\":\"packet\",\"title\":\"Exemple JSON lignes\",\"rows\":[{\"label\":\"En-tête logique\",\"fields\":[{\"name\":\"ts\",\"note\":\"\\\"2026-03-10T10:30:24Z\\\"\",\"weight\":3,\"tone\":\"blue\"},{\"name\":\"level\",\"note\":\"\\\"error\\\"\",\"weight\":2,\"tone\":\"red\"},{\"name\":\"service\",\"note\":\"\\\"api\\\"\",\"weight\":2,\"tone\":\"green\"},{\"name\":\"request_id\",\"note\":\"\\\"req-1005\\\"\",\"weight\":3,\"tone\":\"violet\"}]},{\"label\":\"Contexte métier\",\"fields\":[{\"name\":\"user\",\"note\":\"\\\"awa\\\"\",\"weight\":2,\"tone\":\"amber\"},{\"name\":\"ip\",\"note\":\"\\\"192.168.1.77\\\"\",\"weight\":3,\"tone\":\"cyan\"},{\"name\":\"msg\",\"note\":\"\\\"export started\\\"\",\"weight\":4,\"tone\":\"neutral\"},{\"name\":\"rows\",\"note\":\"850\",\"weight\":1,\"tone\":\"blue\"}]}]}"},{"type":"text","content":"Ce qu’une application devrait journaliser : authentifications réussies ou échouées, changements de droits, exports massifs, erreurs récurrentes, accès à des données sensibles, identifiants de corrélation. Ce qu’elle ne doit jamais journaliser : mots de passe, jetons, clés, numéros complets de carte, ou tout autre secret complet. L’OWASP insiste aussi sur un point discret mais important : empêcher l’injection dans les journaux, par exemple des retours à la ligne forgés qui casseraient le format ou tromperaient un analyste."},{"type":"text","content":"Côté base de données, tu cherches surtout des échecs de connexion, des requêtes lentes, des connexions depuis une machine inattendue et des volumes anormaux. Le journal applicatif te dira souvent « qui » au sens métier, tandis que le journal de base te dira plutôt « quel client », « quelle durée » ou « quel refus ». Les deux se complètent, surtout si un même « request_id » ou un même horodatage relie les sources."},{"type":"text","content":"Démonstration guidée : sur Windows, « jq » n’est pas installé chez tout le monde, donc tu montres les deux chemins. Le premier filtre une requête précise avec « jq » via un petit fichier de filtre, plus robuste que des guillemets fragiles dans PowerShell 5.1. Le second relit la même requête « req-1005 » en PowerShell pour reconstituer un export, une ouverture de connexion base, une requête lente puis un refus d’accès. La méthode est reproductible et n’envoie rien vers un service tiers."},{"type":"code","content":"# Filtrer une requête précise avec jq\n@''\nselect(.request_id==\"req-1005\") | \"\\(.ts)\\t\\(.service)\\t\\(.request_id)\\t\\(.msg)\"\n''@ | Out-File .\\req-1005.jq -Encoding ascii\n$env:TEMP\\tools\\jq.exe -r -f .\\req-1005.jq .\\app.jsonl\n# exemple de sortie (valeurs fictives)\n# 2026-03-10T10:30:22Z\tapi\treq-1005\tlogin ok\n# 2026-03-10T10:30:23Z\tapi\treq-1005\trole changed\n# 2026-03-10T10:30:24Z\tapi\treq-1005\texport started\n# 2026-03-10T10:30:26Z\tapi\treq-1005\texport completed\n# 2026-03-10T10:30:27Z\tdb\treq-1005\tconnection opened\n# 2026-03-10T10:30:28Z\tdb\treq-1005\tslow query\n# 2026-03-10T10:30:29Z\tdb\treq-1005\taccess denied for user report\n\n# Reconstituer une requête précise en PowerShell\nGet-Content .\\app.jsonl | ForEach-Object { $_ | ConvertFrom-Json } |\n  Where-Object { $_.request_id -eq ''req-1005'' } |\n  ForEach-Object {\n    ''{0} service={1} user={2} client={3}{4} msg={5} rows={6} bytes={7} duration_ms={8}'' -f $_.ts, $_.service, $_.user, $_.client, $(if ($_.ip) {\" ip=$($_.ip)\"} else {''''}), $_.msg, $_.rows, $_.bytes, $_.duration_ms\n  }\n# exemple de sortie (valeurs fictives)\n# 2026-03-10T10:30:22Z service=api user=awa client= ip=192.168.1.77 msg=login ok rows= bytes= duration_ms=\n# 2026-03-10T10:30:23Z service=api user=awa client= ip=192.168.1.77 msg=role changed rows= bytes= duration_ms=\n# 2026-03-10T10:30:24Z service=api user=awa client= ip=192.168.1.77 msg=export started rows=850 bytes= duration_ms=\n# 2026-03-10T10:30:26Z service=api user=awa client= ip=192.168.1.77 msg=export completed rows=850 bytes=1843200 duration_ms=\n# 2026-03-10T10:30:27Z service=db user= client=192.168.1.12 msg=connection opened rows= bytes= duration_ms=\n# 2026-03-10T10:30:28Z service=db user= client=192.168.1.12 msg=slow query rows= bytes= duration_ms=4120\n# 2026-03-10T10:30:29Z service=db user= client=192.168.1.12 msg=access denied for user report rows= bytes= duration_ms=","language":"powershell"},{"type":"schema","content":"{\"v\":1,\"kind\":\"flow\",\"title\":\"Trois sources pour un même incident\",\"nodes\":[{\"label\":\"`access.log`\",\"text\":\"POST /login 302 puis /admin/export 200\",\"icon\":\"globe\",\"tone\":\"blue\"},{\"label\":\"`app.jsonl`\",\"text\":\"request_id=req-1005, rôle changed, export\",\"icon\":\"braces\",\"tone\":\"violet\"},{\"label\":\"db log\",\"text\":\"connection opened, slow query, access denied\",\"icon\":\"database\",\"tone\":\"amber\"}]}"},{"type":"text","content":"Le grand intérêt du « request_id » est là : il relie l’accès web à la logique métier puis à l’effet côté base. Sans identifiant commun, tu es condamné à rapprocher seulement par heure et par adresse, ce qui est moins robuste. Si ton application n’écrit pas encore cet identifiant, c’est souvent l’une des améliorations les plus rentables à demander."},{"type":"text","content":"Rappelle-toi enfin que ces journaux sont très sensibles. Ils peuvent contenir des adresses IP, des noms de comptes, des chemins de fichiers, parfois des erreurs qui révèlent l’architecture. Tu les protèges, tu les minimises, et tu n’envoies jamais un extrait interne complet vers un service en ligne si tu n’as pas l’autorisation et le besoin réel."},{"type":"example","content":"Exemple corrigé : si le web montre un « POST /login 302 », puis l’application écrit « login ok », « rôle changed » et « export completed » pour « req-1005 », tandis que la base voit une requête lente puis « access denied for user report », tu peux raconter un incident cohérent : une session a réussi, un rôle a changé, un export a été lancé, puis la base a refusé une action supplémentaire. Le croisement évite de surinterpréter un seul « 500 » ou un seul « 200 »."},{"type":"callout","content":"Erreurs fréquentes : journaliser des secrets complets dans l’application ; écrire du JSON lignes sans identifiant de corrélation ; croire qu’un « 500 » seul suffit sans relire l’application et la base ; oublier qu’un retour à la ligne injecté peut casser la lecture du journal."},{"type":"callout","content":"Sécurité : Les journaux applicatifs et de base de données contiennent souvent des données personnelles et des détails d’architecture. Tu les gardes dans ton périmètre autorisé, tu retires les éléments inutiles avant partage et tu évites tout envoi vers un service tiers sans validation explicite."},{"type":"callout","content":"À retenir : Le journal applicatif explique l’intention métier, la base de données montre souvent l’effet technique, et le journal web donne la porte d’entrée. Un identifiant de corrélation les rend bien plus utiles. Aucun secret complet ne doit finir dans ces traces."},{"type":"callout","content":"Pour pratiquer : Dans « Intrusion web : du scan au webshell », relis d’abord la chronologie web, puis transpose la même méthode à un journal applicatif : cherche quel identifiant de requête, quel compte et quel export tu voudrais retrouver, puis termine par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur la journalisation (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html"},{"type":"resource","content":"jq : le manuel (en anglais)","url":"https://jqlang.github.io/jq/manual/"},{"type":"resource","content":"Microsoft : l’applet de commande ConvertFrom-Json","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.utility/convertfrom-json"}]}'::jsonb, 22, 30, 3),
  ('8a32f6d6-e51d-bf40-47b1-64f802729208', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'ed4716b0-947a-9860-7eca-36051d075eaa', 'Journaux de pare-feu : lire un ALLOW, un DENY et une série de ports', 'Apprends à lire une ligne de pare-feu champ par champ, à distinguer le bruit normal d’Internet d’un motif utile, et à compter ports, sources et actions sans conclure trop vite.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer l’action, l’interface, la source, la destination et les ports d’une ligne de pare-feu, distinguer ALLOW, DENY, DROP et REJECT, reconnaître un balayage de ports, compter par source et par port, et expliquer pourquoi un refus n’est pas un incident à lui seul."},{"type":"callout","content":"Prérequis : avoir déjà lu un journal horodaté et savoir qu’une adresse source et un port de destination ne racontent pas la même chose."},{"type":"callout","content":"Mise en situation : Awa surveille le petit réseau d’Atlas. Le pare-feu01 journalise des refus SSH et RDP toute la journée, mais un poste interne semble aussi parler vers une destination inhabituelle. Awa doit éviter deux erreurs : paniquer devant le bruit normal d’Internet, et manquer un flux autorisé qui mérite une vérification."},{"type":"callout","content":"Vidéo à venir : Lire un journal de pare-feu sans confondre bruit et incident"},{"type":"text","content":"Un journal de pare-feu enregistre surtout une décision : laisser passer, refuser en silence, ou refuser avec une réponse. Autour de cette décision, tu lis des champs techniques utiles : interface d’entrée ou de sortie, protocole, adresse source, adresse de destination, port source, port de destination, parfois les drapeaux TCP comme SYN, ACK, RST ou FIN. Le port source est souvent éphémère côté client. Le port de destination te dit plutôt quel service était visé."},{"type":"schema","content":"{\"v\":1,\"kind\":\"anatomy\",\"title\":\"Lire une ligne de pare-feu champ par champ\",\"lines\":[[{\"text\":\"2026-03-10T09:15:01Z\",\"label\":\"heure\",\"tone\":\"neutral\"},{\"text\":\"[UFW BLOCK]\",\"label\":\"action prise\",\"tone\":\"red\"},{\"text\":\"IN=eth0\",\"label\":\"interface d’entrée\",\"tone\":\"blue\"},{\"text\":\"SRC=192.0.2.11\",\"label\":\"adresse source\",\"tone\":\"violet\"}],[{\"text\":\"DST=10.1.0.10\",\"label\":\"adresse visée\",\"tone\":\"violet\"},{\"text\":\"PROTO=TCP\",\"label\":\"protocole\",\"tone\":\"green\"},{\"text\":\"SPT=52341\",\"label\":\"port source éphémère\",\"tone\":\"amber\"},{\"text\":\"DPT=22\",\"label\":\"service visé\",\"tone\":\"amber\"},{\"text\":\"SYN\",\"label\":\"début d’une tentative TCP\",\"tone\":\"red\"}]],\"caption\":\"Le port source 52341 varie côté client, le port 22 révèle le service ciblé.\"}"},{"type":"text","content":"ALLOW et ACCEPT signifient qu’une règle a laissé passer le trafic. DENY, DROP, BLOCK et REJECT signifient qu’il a été refusé, mais pas toujours de la même manière. Un DROP ne répond pas. Un REJECT renvoie un refus explicite, par exemple un reset TCP ou une erreur ICMP selon le protocole. Sur Linux, tu verras souvent des préfixes comme « [UFW BLOCK] », « [UFW ALLOW] » ou « [UFW LIMIT] ». Avec nftables ou un équipement comme pfSense, les noms et l’ordre changent, mais la logique reste la même : décision, sens, adresses, ports, indicateurs. Pour l’analyse défensive, retiens surtout ceci : un pare-feu exposé à Internet reçoit en permanence des refus. Le signal utile est souvent ailleurs, dans les flux autorisés inattendus, les sorties vers des ports peu habituels, ou une machine interne qui tente de joindre un segment qu’elle ne devrait pas atteindre."},{"type":"text","content":"Démonstration guidée : travaille sur une copie du journal, jamais sur l’original. Commence par compter les actions, puis les sources bloquées, puis les ports visés. Ensuite seulement, relis quelques lignes autour du motif dominant. Tu cherches une forme : une source qui essaie beaucoup de ports sur la même cible, ou au contraire la même machine qui insiste plusieurs fois sur un seul port."},{"type":"code","content":"# Répartir les actions observées\ngrep -Eo ''\\[UFW [A-Z]+\\]'' fw.log | sed ''s/\\[UFW //; s/\\]//'' | sort | uniq -c | sort -rn\n# exemple de sortie (valeurs fictives)\n#      20 BLOCK\n#       5 ALLOW\n\n# Sources qui déclenchent le plus de refus\ngrep \"UFW BLOCK\" fw.log | awk ''{for (i=1;i<=NF;i++) if ($i ~ /^SRC=/) {split($i,a,\"=\"); print a[2]}}'' | sort | uniq -c | sort -rn\n# exemple de sortie (valeurs fictives)\n#       8 192.0.2.11\n#       6 192.0.2.33\n#       3 192.0.2.22\n#       2 10.1.4.20\n#       1 192.0.2.44\n\n# Ports les plus visés dans les refus\ngrep \"UFW BLOCK\" fw.log | awk ''{for (i=1;i<=NF;i++) if ($i ~ /^DPT=/) {split($i,a,\"=\"); print a[2]}}'' | sort | uniq -c | sort -rn\n# exemple de sortie (valeurs fictives)\n#       4 443\n#       4 3306\n#       3 80\n#       2 445\n#       2 3389\n#       2 22\n#       1 8080\n#       1 5432\n#       1 23","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Motifs utiles et lecture prudente\",\"columns\":[\"Motif utile\",\"Lecture prudente\"],\"rows\":[[\"Une source, beaucoup de ports\",\"Balayage de ports probable\"],[\"Un port, beaucoup de cibles\",\"Balayage d’hôtes probable\"],[\"Beaucoup de refus sur 22\",\"Bruit courant d’Internet\"],[\"ALLOW sortant sur port rare\",\"À vérifier en priorité\"],[\"Trafic inter-segments refusé\",\"Peut révéler un poste mal placé\"]]}"},{"type":"example","content":"Exemple corrigé : l’adresse 192.0.2.11 touche successivement 22, 23, 80, 443, 445, 3389, 5432 et 3306 sur la même destination, avec le drapeau SYN et sans échange établi ensuite. C’est un balayage de ports probable : elle explore la surface d’exposition. À l’inverse, une même source qui ne réessaie que 443 plusieurs fois ressemble davantage à un client ou à un script qui tente encore le même service. Dans les deux cas, tu notes le contexte, mais tu priorises davantage un ALLOW sortant inattendu qu’un simple BLOCK entrant."},{"type":"callout","content":"Erreurs fréquentes : confondre le port source éphémère avec le service visé ; conclure à une intrusion sur la seule base d’un refus ; ignorer les flux autorisés sortants parce que le mot « ALLOW » semble rassurant ; oublier que la rotation peut déplacer les lignes anciennes dans un fichier archivé."},{"type":"callout","content":"Sécurité : analyse uniquement les journaux de ton organisation ou d’un système pour lequel tu as un mandat écrit. Les journaux de pare-feu contiennent des adresses IP et parfois des noms de segments : ne les publie pas et ne les envoie pas à un service tiers sans nécessité. Toute action de blocage durable suit la procédure prévue par ton organisation."},{"type":"callout","content":"À retenir : un journal de pare-feu raconte une décision, pas toute l’histoire. Les refus entrants sont souvent du bruit normal. Le vrai signal vient des motifs : beaucoup de ports, beaucoup de cibles, ou un flux autorisé qui ne colle pas à la base de référence."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 3 : pare-feu, DNS et proxy : trouver la machine qui balise » : compte les sources, les ports et les actions, puis distingue un balayage de ports d’un simple client qui réessaie avant de finir par le quiz."},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"},{"type":"resource","content":"netfilter : la documentation (en anglais)","url":"https://www.netfilter.org/documentation/"},{"type":"resource","content":"Debian : manuel de nft (nftables) (en anglais)","url":"https://manpages.debian.org/stable/nftables/nft.8.en.html"}]}'::jsonb, 24, 30, 1),
  ('cbef2648-8943-8fab-a3db-5750d73aebc3', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'ed4716b0-947a-9860-7eca-36051d075eaa', 'DNS et mandataire : domaines rares, volumes et appels réguliers', 'Tu apprendras à lire un journal DNS et un access.log Squid, à mesurer la régularité d’un domaine, et à relier un nom demandé à un volume sortant sans surévaluer un faux positif.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer le client, le nom demandé, le type et le code de réponse d’un journal DNS, lire le format natif de Squid, mesurer les intervalles entre appels, additionner un volume sortant, et conclure avec prudence sur un domaine rare ou régulier."},{"type":"callout","content":"Prérequis : savoir qu’un nom de domaine peut mener à une adresse IP, et qu’un proxy journalise des requêtes web même quand le contenu HTTPS reste chiffré."},{"type":"callout","content":"Mise en situation : Moussa doit expliquer pourquoi un poste de la comptabilité contacte toujours le même domaine à intervalles réguliers. En parallèle, un autre poste accumule des NXDOMAIN et des requêtes TXT étranges. Avec les journaux DNS et le mandataire, Moussa veut montrer ce qui est mesuré, ce qui manque encore, et ce qui doit être vérifié auprès de l’utilisateur avant de parler d’incident."},{"type":"callout","content":"Vidéo à venir : Relier DNS et proxy pour comprendre un trafic répétitif"},{"type":"text","content":"Le DNS transforme un nom en information exploitable par un logiciel : le plus souvent une adresse IP, parfois un serveur de messagerie ou un autre nom. Dans un journal DNS, tu cherches au minimum l’heure, le client, le nom demandé, le type de requête, par exemple A, AAAA, TXT, MX ou NS, et le code de réponse. Si la réponse est journalisée aussi, note l’adresse ou le CNAME renvoyé pour pouvoir relier ensuite ce nom à une destination vue dans un proxy ou un flux. « NOERROR » veut d’abord dire qu’il n’y a pas d’erreur DNS signalée. « NXDOMAIN » signifie que le nom n’existe pas. « SERVFAIL » indique un échec du résolveur ou de la chaîne amont. « REFUSED » veut dire qu’un serveur refuse de répondre à cette requête selon sa politique."},{"type":"schema","content":"{\"v\":1,\"kind\":\"anatomy\",\"title\":\"Lire un extrait DNS et une ligne Squid\",\"lines\":[[{\"text\":\"2026-03-10T09:18:02Z\",\"label\":\"heure\",\"tone\":\"neutral\"},{\"text\":\"192.168.1.50\",\"label\":\"client\",\"tone\":\"blue\"},{\"text\":\"k3n9za.service.example\",\"label\":\"qname\",\"tone\":\"violet\"},{\"text\":\"TXT\",\"label\":\"type\",\"tone\":\"green\"},{\"text\":\"NXDOMAIN\",\"label\":\"rcode\",\"tone\":\"red\"}],[{\"text\":\"1773134100.000\",\"label\":\"time\",\"tone\":\"neutral\"},{\"text\":\"120\",\"label\":\"durée ms\",\"tone\":\"amber\"},{\"text\":\"192.168.1.44\",\"label\":\"client\",\"tone\":\"blue\"},{\"text\":\"TCP_MISS/200\",\"label\":\"résultat et code\",\"tone\":\"green\"},{\"text\":\"512\",\"label\":\"octets\",\"tone\":\"amber\"},{\"text\":\"GET\",\"label\":\"méthode\",\"tone\":\"cyan\"},{\"text\":\"http://api.sync.example/health\",\"label\":\"URL\",\"tone\":\"violet\"},{\"text\":\"-\",\"label\":\"identité\",\"tone\":\"neutral\"},{\"text\":\"HIER_DIRECT/192.0.2.40\",\"label\":\"pair ou destination\",\"tone\":\"blue\"},{\"text\":\"application/json\",\"label\":\"type MIME\",\"tone\":\"green\"}]],\"caption\":\"Le DNS montre le nom demandé et sa réponse, Squid détaille la transaction web vue par le proxy.\"}"},{"type":"text","content":"Le mandataire Squid raconte autre chose. Son format natif commence par un horodatage epoch en secondes avec millisecondes, puis la durée en millisecondes, le client, le résultat du cache avec le code HTTP, le nombre d’octets, la méthode, l’URL, l’identité éventuelle, le pair ou la destination, puis le type MIME. La ligne est en général écrite à la fin de la transaction. « TCP_MISS/200 » veut dire que l’objet n’a pas été servi depuis le cache et qu’une réponse HTTP 200 est partie vers le client. Pour HTTPS sans déchiffrement, tu verras surtout des lignes CONNECT, souvent avec un résultat comme « TCP_TUNNEL/200 » : le domaine et le port, pas le chemin ni le contenu. « TCP_DENIED/403 » montre qu’une politique locale a refusé la requête."},{"type":"text","content":"Un domaine rare, des noms aléatoires, une rafale de NXDOMAIN, beaucoup de TXT ou des appels très réguliers peuvent être utiles. Ce ne sont pas des preuves à eux seuls. Un antivirus, une mise à jour automatique, un CDN ou un agent de supervision peuvent faire la même chose. L’analyste vérifie donc trois choses : la régularité des horodatages, la gigue entre deux appels, le volume échangé, et le contexte métier de la machine qui appelle."},{"type":"text","content":"Démonstration guidée : commence par le DNS. Compte les NXDOMAIN par client. Puis calcule les écarts successifs pour un domaine répété. Enfin, ouvre le journal Squid pour voir si le même poste transfère peu d’octets, ou au contraire un volume qui mérite une vérification. Tu ne cherches pas encore une certitude, tu cherches un motif reproductible et une éventuelle gigue autour d’un rythme stable."},{"type":"code","content":"# Quels clients cumulent des NXDOMAIN ?\nawk -F ''\\t'' ''$5==\"NXDOMAIN\" {print $2}'' dns.log | sort | uniq -c | sort -rn\n# exemple de sortie (valeurs fictives)\n#       4 192.168.1.50\n\n# Intervalles, en secondes, entre les requêtes vers le même domaine\nawk -F ''\\t'' ''$2==\"192.168.1.44\" && $3==\"api.sync.example\" { split(substr($1,12,8),t,\":\"); s=t[1]*3600+t[2]*60+t[3]; if (prev != \"\") print s-prev; prev=s }'' dns.log\n# exemple de sortie (valeurs fictives)\n# 16\n# 17\n# 18\n# 17\n# 16\n\n# Volume HTTP vu par Squid pour le client régulier\nawk ''$3==\"192.168.1.44\" {bytes += $5} END {print bytes}'' squid.log\n# exemple de sortie (valeurs fictives)\n# 19086","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Signal observé et question suivante\",\"columns\":[\"Signal observé\",\"Question suivante\"],\"rows\":[[\"NXDOMAIN en rafale\",\"Le domaine est-il aléatoire ou juste mal saisi ?\"],[\"Beaucoup de TXT\",\"Quel logiciel légitime peut faire cela ?\"],[\"CONNECT vers un domaine rare\",\"Quel poste, quel utilisateur, quelle heure ?\"],[\"Intervalles réguliers\",\"Supervision légitime ou balisage ?\"],[\"Volume sortant élevé\",\"Sauvegarde, mise à jour ou exfiltration ?\"]]}"},{"type":"example","content":"Exemple corrigé : le poste 192.168.1.44 demande « api.sync.example » avec des écarts de 16, 17, 18, 17 et 16 secondes. La médiane vaut 17 secondes et la gigue reste faible, avec seulement 2 secondes entre l’intervalle le plus court et le plus long. Squid montre ensuite 19 086 octets au total pour ces appels, soit environ 18,64 Kio. Le volume reste faible et le chemin « /health » ressemble à une sonde applicative. À l’inverse, 192.168.1.50 cumule quatre NXDOMAIN en TXT : cela mérite davantage de contexte avant de conclure, surtout si aucun gros volume proxy n’apparaît pour ce même poste."},{"type":"callout","content":"Erreurs fréquentes : prendre NXDOMAIN comme une preuve de malware ; oublier qu’un CONNECT HTTPS ne montre pas le chemin ; additionner les octets sans vérifier s’il s’agit d’une erreur HTML ou d’un vrai contenu ; ignorer les exceptions légitimes comme les mises à jour, l’antivirus ou la supervision."},{"type":"callout","content":"Sécurité : les journaux DNS et proxy peuvent révéler les habitudes de navigation et des données personnelles. Analyse-les seulement dans le cadre de ton organisation ou d’un mandat écrit, informe-toi des règles internes, et n’envoie pas des domaines internes ou des URL sensibles à un service public sans autorisation. Le principe reste défensif : comprendre et protéger, jamais suivre ou profiler sans cadre."},{"type":"callout","content":"À retenir : DNS te dit ce qui a été demandé. Le proxy te dit ce qui a été tenté en HTTP ou HTTPS visible. La régularité, le code de réponse et le volume sont des indices à croiser, jamais une preuve isolée."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 3 : pare-feu, DNS et proxy : trouver la machine qui balise » : compte les NXDOMAIN, mesure les intervalles d’un domaine répété, puis relie ce domaine au volume vu dans le mandataire avant de finir par le quiz."},{"type":"resource","content":"RFC 1035 : mise en œuvre du DNS (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc1035"},{"type":"resource","content":"Squid : les formats de journaux (en anglais)","url":"https://wiki.squid-cache.org/Features/LogFormat"},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"}]}'::jsonb, 24, 30, 2),
  ('9126bae3-8396-9cc4-81a2-cf71a88f10c5', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'ed4716b0-947a-9860-7eca-36051d075eaa', 'Flux réseau et détection d’intrusion : NetFlow, Zeek et Suricata', 'Cette leçon t’apprend ce qu’un flux résume, comment lire un extrait de conn.log Zeek et une alerte EVE JSON Suricata, puis comment qualifier une alerte sans extrapoler.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer ce que résume un flux réseau, lire les champs essentiels d’un conn.log Zeek, filtrer une alerte EVE JSON Suricata, repérer « timestamp », « event_type », « flow_id », « alert.signature » et « alert.signature_id », distinguer gravité et priorité, et formuler une phrase factuelle sans transformer une alerte en certitude."},{"type":"callout","content":"Prérequis : avoir vu ce qu’un port, une adresse source, une adresse de destination et un volume d’octets signifient dans un journal réseau."},{"type":"callout","content":"Mise en situation : Nadia reçoit quatre alertes IDS en moins d’une minute. L’une parle d’un domaine rare, une autre d’un gros transfert sortant, une troisième ressemble à une mise à jour web ordinaire. Nadia doit trier vite, mais sans oublier qu’une alerte IDS n’est que le point de départ d’une vérification."},{"type":"callout","content":"Vidéo à venir : Lire un flux réseau et une alerte IDS avec méthode"},{"type":"text","content":"NetFlow et IPFIX ne conservent pas le contenu des paquets. Ils résument une conversation : qui parle à qui, sur quels ports, avec quel protocole, pendant combien de temps, et avec combien d’octets ou de paquets. Ce résumé suffit souvent pour repérer un nouveau pair réseau, un transfert sortant inhabituel, une durée anormalement longue ou un protocole inattendu entre deux segments."},{"type":"schema","content":"{\"v\":1,\"kind\":\"compare\",\"title\":\"Ce qu’un flux réseau résume, et ce qu’il ne prouve pas\",\"sides\":[{\"title\":\"Utile pour\",\"tone\":\"green\",\"items\":[\"repérer un gros transfert sortant\",\"voir si un poste parle à une destination inédite\",\"compter les connexions vers un même serveur\"]},{\"title\":\"Limites\",\"tone\":\"red\",\"items\":[\"pas de contenu applicatif\",\"pas de preuve, seulement un résumé\"]}],\"verdict\":\"Résumé : source, destination, ports, protocole, début, fin et octets.\"}"},{"type":"text","content":"Zeek produit des journaux spécialisés. Dans « conn.log », tu lis notamment « ts », « uid », « id.orig_h », « id.orig_p », « id.resp_h », « id.resp_p », « proto », « service », « duration », « orig_bytes », « resp_bytes » et « conn_state ». « conn_state » résume l’état de la conversation : « SF » pour une ouverture et une fermeture normales, « S0 » pour une tentative sans réponse, « REJ » pour une tentative rejetée. « dns.log » ajoute par exemple « query », « qtype_name » et « rcode_name », tandis que « http.log » aide à relier « method », « host », « uri » et « status_code ». Les lignes commencent souvent par des en-têtes « #fields » et « #types », utiles pour ne pas deviner les colonnes."},{"type":"code","content":"# Ligne Zeek intéressante vers la destination 192.0.2.44\nawk -F ''\\t'' ''!/^#/ && $5==\"192.0.2.44\" {print $1, $3, $5, $10, $11, $12}'' conn.log\n# exemple de sortie (valeurs fictives)\n# 1773135200.000000 10.1.2.9 192.0.2.44 1048576 26214400 SF","language":"bash"},{"type":"text","content":"Suricata écrit souvent ses alertes dans EVE JSON. Chaque ligne JSON représente un événement. Tu y lis le champ « timestamp », « event_type », les adresses et ports, le protocole, « flow_id », puis le bloc « alert » avec au moins « signature_id », « signature », « category », « severity » et l’action. Une alerte n’est pas une preuve de compromission. La règle peut être trop large, le trafic légitime, ou le flux déjà bloqué. Tu confirmes donc avec la direction du trafic, le volume, l’action prise et, si possible, une autre source comme un proxy ou un pare-feu."},{"type":"text","content":"Démonstration guidée : extrais d’abord les alertes dans un format lisible. Puis compare-les au flux Zeek. Une alerte « gros transfert sortant » est plus crédible si le flux montre vraiment beaucoup d’octets de réponse ou de destination selon le sens observé. Une alerte sur un domaine rare devient moins urgente si le même poste effectue une mise à jour attendue, depuis un service connu, avec un faible volume."},{"type":"code","content":"# Filtrer les alertes EVE et garder l’essentiel\njq -c ''select(.event_type==\"alert\") | {ts:.timestamp,event_type,flow_id,src:.src_ip,dst:.dest_ip,sig_id:.alert.signature_id,sig:.alert.signature,sev:.alert.severity,action:.alert.action}'' eve.json\n# exemple de sortie (valeurs fictives)\n# {\"ts\":\"2026-03-10T09:30:12.000000+0000\",\"event_type\":\"alert\",\"flow_id\":880001,\"src\":\"192.168.1.50\",\"dst\":\"192.0.2.77\",\"sig_id\":2030011,\"sig\":\"ET POLICY Possible Rare Domain Contact\",\"sev\":3,\"action\":\"allowed\"}\n# {\"ts\":\"2026-03-10T09:31:05.000000+0000\",\"event_type\":\"alert\",\"flow_id\":880002,\"src\":\"10.1.2.9\",\"dst\":\"192.0.2.44\",\"sig_id\":2030012,\"sig\":\"ET POLICY Large Outbound Transfer\",\"sev\":2,\"action\":\"allowed\"}\n# {\"ts\":\"2026-03-10T09:31:44.000000+0000\",\"event_type\":\"alert\",\"flow_id\":880003,\"src\":\"192.168.1.21\",\"dst\":\"192.0.2.90\",\"sig_id\":2030013,\"sig\":\"ET WEB_CLIENT Example Browser Update\",\"sev\":3,\"action\":\"allowed\"}\n# {\"ts\":\"2026-03-10T09:32:10.000000+0000\",\"event_type\":\"alert\",\"flow_id\":880004,\"src\":\"192.168.1.32\",\"dst\":\"192.0.2.70\",\"sig_id\":2030014,\"sig\":\"ET DNS Query for .example Domain\",\"sev\":4,\"action\":\"blocked\"}","language":"bash"},{"type":"code","content":"# Équivalent PowerShell 5.1 pour les alertes EVE JSON\nGet-Content eve.json | ForEach-Object { $_ | ConvertFrom-Json } | Where-Object event_type -eq ''alert'' | ForEach-Object { \"{0} {1} {2} {3} {4}\" -f $_.timestamp, $_.flow_id, $_.alert.signature_id, $_.alert.action, $_.alert.signature }\n# exemple de sortie (valeurs fictives)\n# 2026-03-10T09:30:12.000000+0000 880001 2030011 allowed ET POLICY Possible Rare Domain Contact\n# 2026-03-10T09:31:05.000000+0000 880002 2030012 allowed ET POLICY Large Outbound Transfer\n# 2026-03-10T09:31:44.000000+0000 880003 2030013 allowed ET WEB_CLIENT Example Browser Update\n# 2026-03-10T09:32:10.000000+0000 880004 2030014 blocked ET DNS Query for .example Domain","language":"powershell"},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Alerte IDS et réaction analytique\",\"columns\":[\"Alerte IDS\",\"Réaction analytique\"],\"rows\":[[\"Gravité faible, trafic légitime\",\"À surveiller ou faux positif probable\"],[\"Gros volume + action allowed\",\"À traiter rapidement\"],[\"Action blocked par une politique\",\"Vérifier, mais priorité souvent plus basse\"],[\"Signature seule\",\"Jamais suffisante\"]]}"},{"type":"example","content":"Exemple corrigé : l’alerte « ET POLICY Large Outbound Transfer » porte le « flow_id » 880002 et le « signature_id » 2030012, et vise le flux 10.1.2.9 -> 192.0.2.44. Le conn.log associé à ce flux montre 26 214 400 octets en réponse, soit environ 25,00 Mio, et l’action Suricata vaut « allowed ». Celle-ci passe donc en « à traiter ». L’alerte « Example Browser Update » ressemble plutôt à une mise à jour web ordinaire : même si la signature existe, elle devient « faux positif probable » tant qu’aucun autre indice ne l’aggrave. Enfin, « ET DNS Query for .example Domain » est déjà « blocked » : on la note, mais elle ne passe pas devant le gros transfert autorisé."},{"type":"callout","content":"Erreurs fréquentes : confondre gravité numérique de la règle et priorité de traitement ; oublier le sens du flux ; croire qu’un seul outil dit toute la vérité ; citer une signature sans noter si le trafic a été autorisé, bloqué ou si le volume reste banal."},{"type":"callout","content":"Sécurité : Suricata, Zeek et les collecteurs de flux demandent en pratique une sonde ou un serveur dédié. Analyse ces données uniquement sur ton réseau ou un environnement autorisé. Les journaux réseau restent des données sensibles : ils révèlent qui parle à qui, parfois à quel rythme. Ne les confie pas à un service tiers sans nécessité et sans cadre."},{"type":"callout","content":"À retenir : un flux réseau résume une conversation. Une alerte IDS dit qu’une règle a correspondu, pas qu’une attaque est confirmée. Le bon réflexe consiste à croiser signature, action, volume, direction et autre source avant de conclure."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 3 : pare-feu, DNS et proxy : trouver la machine qui balise » : pars d’un flux ou d’une alerte, relie-le au reste des journaux, puis justifie ce qui passe « à traiter », « à surveiller » ou « faux positif probable » avant le quiz."},{"type":"resource","content":"RFC 7011 : IPFIX, l’export de flux IP (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc7011"},{"type":"resource","content":"Suricata : la sortie EVE au format JSON (en anglais)","url":"https://docs.suricata.io/en/latest/output/eve/eve-json-output.html"},{"type":"resource","content":"NIST SP 800-92 : guide de la gestion des journaux de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/92/final"}]}'::jsonb, 24, 30, 3),
  ('1c023e94-7dc4-9d30-261a-1accb24da48c', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'b9cf9654-4f18-dd0b-f095-aa48e72eb099', 'Extraire et compter : grep, awk, sort et uniq sur des journaux', 'Tu vas construire des pipelines simples sur des journaux texte, comprendre ce que chaque maillon apporte, et refaire la même lecture avec des équivalents PowerShell sur Windows.', '{"blocks":[{"type":"callout","content":"Objectifs : filtrer un journal avec grep ou Select-String, extraire un champ utile, compter par valeur, trier un top, repérer le piège de uniq sans sort, et comparer une lecture Git Bash avec une lecture PowerShell."},{"type":"callout","content":"Prérequis : savoir ouvrir un fichier texte et lire une ligne de journal avec heure, programme et message."},{"type":"callout","content":"Mise en situation : Koffi doit résumer une rafale d’échecs SSH reçue sur un serveur. Il travaille parfois dans Git Bash, parfois dans PowerShell 5.1, selon le poste qu’il a sous la main. Son objectif n’est pas d’écrire tout de suite un gros script, mais de vérifier pas à pas quel poste échoue le plus et à quel moment."},{"type":"callout","content":"Vidéo à venir : Construire un pipeline d’analyse fiable sur un journal texte"},{"type":"text","content":"La boîte à outils minimale sur des journaux texte tient en peu de commandes. « grep » ou « Select-String » filtrent. « awk » ou une combinaison PowerShell extraient un champ. « sort » ordonne. « uniq -c » ou « Group-Object » comptent. Le bon réflexe consiste à tester chaque maillon séparément avant de les enchaîner. Ainsi, quand le résultat semble absurde, tu sais quel étage corriger. Retenir les options exactes t’évite aussi des erreurs de lecture : « grep -E » pour les regex étendues, « -i » pour ignorer la casse, « -v » pour exclure, « -c » pour compter, « -o » pour ne garder que la correspondance, « -w » pour un mot entier, et « -A/-B/-C » pour le contexte. « grep -P » existe sur certains environnements GNU, mais reste moins portable qu’une ERE avec « -E »."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Commandes et options utiles sur les journaux\",\"columns\":[\"Commande ou option\",\"Usage défensif courant\"],\"rows\":[[\"grep -E -i -v -c -n -o -w\",\"motif, casse, exclusion, compteur, ligne, sous-partie, mot\"],[\"grep -A/-B/-C\",\"voir le contexte avant ou après une ligne\"],[\"awk -F '':'' ''... END {...}''\",\"séparateur explicite, conditions, totaux\"],[\"sort -n -r -k -t -u\",\"tri numérique, inverse, par clé, avec séparateur, valeurs uniques\"],[\"uniq -c\",\"compter après tri\"],[\"cut, comm, join, column -t\",\"découper, comparer, joindre, relire un tableau\"],[\"Select-String, Group-Object\",\"équivalents courants sous PowerShell\"]],\"mono\":[0]}"},{"type":"text","content":"Deux pièges reviennent souvent. D’abord, « uniq -c » ne regroupe que des lignes identiques adjacentes : il faut presque toujours trier avant. Ensuite, un champ n’est pas toujours à la même position quand le message varie. Sur un auth.log, il vaut parfois mieux chercher le mot « from » puis prendre l’adresse qui suit, plutôt que compter aveuglement les colonnes. « cut » découpe des caractères ou des champs avec un séparateur donné ; « comm » compare deux fichiers triés ligne par ligne ; « join » rapproche deux fichiers triés sur une clé commune. Enfin, PowerShell 5.1 lit parfois mal l’UTF-8 si tu n’indiques pas explicitement l’encodage, et « Select-String » travaille lui aussi ligne par ligne : « -AllMatches » remonte plusieurs correspondances sur une même ligne, « -Context » ajoute des lignes avant et après."},{"type":"text","content":"Démonstration guidée : pars d’un journal d’authentification. Filtre les lignes « Failed password ». Observe-en quelques-unes pour confirmer le motif. Puis extrais les adresses IP après le mot « from ». Enfin, compte et trie le résultat. Rejoue la même démarche dans PowerShell : tu apprendras vite quel outil est disponible sur quel poste."},{"type":"code","content":"# Voir les premières lignes d’échec avec leur numéro\ngrep -n \"Failed password\" tool-auth.log | head -5\n# exemple de sortie (valeurs fictives)\n# 1:Mar 10 10:00:01 web01 sshd[1201]: Failed password for invalid user admin from 192.0.2.11 port 51001 ssh2\n# 2:Mar 10 10:00:12 web01 sshd[1202]: Failed password for invalid user admin from 192.0.2.11 port 51002 ssh2\n# 3:Mar 10 10:00:30 web01 sshd[1203]: Failed password for awa from 192.0.2.44 port 51003 ssh2\n# 4:Mar 10 10:01:05 web01 sshd[1204]: Failed password for invalid user test from 192.0.2.11 port 51004 ssh2\n# 6:Mar 10 10:01:44 web01 sshd[1206]: Failed password for invalid user oracle from 192.0.2.99 port 51005 ssh2\n\n# Top des adresses sources en échec\nawk ''/Failed password/ {for (i=1;i<=NF;i++) if ($i==\"from\") print $(i+1)}'' tool-auth.log | sort | uniq -c | sort -rn | head -5\n# exemple de sortie (valeurs fictives)\n#      11 192.0.2.11\n#       6 192.0.2.44\n#       5 192.0.2.99\n#       5 192.0.2.55","language":"bash"},{"type":"code","content":"# Équivalent PowerShell 5.1\nSelect-String -Path tool-auth.log -Pattern \"Failed password\" | Select-Object -First 5\n# exemple de sortie (valeurs fictives)\n# tool-auth.log:1:Mar 10 10:00:01 web01 sshd[1201]: Failed password for invalid user admin from 192.0.2.11 port 51001 ssh2\n# tool-auth.log:2:Mar 10 10:00:12 web01 sshd[1202]: Failed password for invalid user admin from 192.0.2.11 port 51002 ssh2\n\nGet-Content tool-auth.log | Where-Object { $_ -match \"Failed password\" } | ForEach-Object { if ($_ -match \"from (?<ip>[0-9.]+)\") { $Matches.ip } } | Group-Object -NoElement | Sort-Object Count -Descending | Select-Object -First 5 | ForEach-Object { \"{0} {1}\" -f $_.Count, $_.Name }\n# exemple de sortie (valeurs fictives)\n# 11 192.0.2.11\n# 6 192.0.2.44\n# 5 192.0.2.55\n# 5 192.0.2.99","language":"powershell"},{"type":"example","content":"Exemple corrigé : si tu veux les cinq adresses qui échouent le plus, la version Bash et la version PowerShell racontent la même histoire : 192.0.2.11 domine nettement. Ce n’est pas encore une attaque prouvée, mais c’est une priorité de lecture. Si tu oublies « sort » avant « uniq -c », tu sous-comptes ou tu éclates le résultat en plusieurs blocs, puis tu prends une mauvaise décision sur la source dominante."},{"type":"callout","content":"Erreurs fréquentes : utiliser « uniq -c » sur des lignes non triées ; supposer qu’une IP est toujours dans la même colonne ; confondre ce qui est filtre et ce qui est compte ; oublier « -Encoding UTF8 » en PowerShell quand le fichier n’est pas lu correctement sous Windows PowerShell 5.1."},{"type":"callout","content":"Sécurité : travaille sur une copie de journal et garde le fichier original intact. Les journaux contiennent des adresses IP, des noms de comptes et parfois des chemins sensibles : ne les colle pas dans un service en ligne. Analyse seulement des traces de ton organisation ou d’un système autorisé."},{"type":"callout","content":"À retenir : un pipeline fiable se construit par petits étages : filtrer, vérifier, extraire, compter, puis trier. Bash et PowerShell peuvent mener au même résultat, à condition de nommer clairement ce que chaque étape produit."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 1 : lire, normaliser et dater des journaux de formats différents » : refais un top d’adresses, compare les résultats Bash et PowerShell, puis vérifie que tu obtiens les mêmes nombres avant le quiz."},{"type":"resource","content":"Linux : manuel de la commande grep (en anglais)","url":"https://man7.org/linux/man-pages/man1/grep.1.html"},{"type":"resource","content":"POSIX : manuel de la commande awk (en anglais)","url":"https://man7.org/linux/man-pages/man1/awk.1p.html"},{"type":"resource","content":"Microsoft : l’applet de commande Select-String","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.utility/select-string"}]}'::jsonb, 24, 30, 1),
  ('9de9ab9c-9d8e-a2f7-9215-a6ffaf3ce30c', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'b9cf9654-4f18-dd0b-f095-aa48e72eb099', 'Expressions régulières et JSON : jq et PowerShell', 'Apprends à extraire proprement des champs avec une regex, à filtrer du JSON lignes avec jq ou ConvertFrom-Json, et à corriger un motif trop large qui produit des faux positifs.', '{"blocks":[{"type":"callout","content":"Objectifs : utiliser des ancres, classes et groupes dans une regex, extraire IP, chemin et code HTTP d’une ligne web, filtrer du JSON lignes avec jq, faire l’équivalent en PowerShell, et repérer une regex trop large."},{"type":"callout","content":"Prérequis : avoir déjà manipulé un journal texte ligne par ligne, et savoir qu’un objet JSON lignes occupe une ligne par événement."},{"type":"callout","content":"Mise en situation : Nadia doit expliquer à un collègue pourquoi sa recherche « tout ce qui contient 200 » est trompeuse. Elle veut montrer une méthode plus propre : une regex qui capture les bons champs dans un journal web, puis un filtre JSON pour isoler les erreurs applicatives. Sa contrainte : sous Windows, jq n’est pas installé par défaut, il faut donc connaître l’alternative PowerShell."},{"type":"callout","content":"Vidéo à venir : Extraire juste ce qu’il faut avec une regex et du JSON lignes"},{"type":"text","content":"Une expression régulière sert à décrire un motif. Les ancres « ^ » et « $ » bornent le début et la fin. Les classes comme « [0-9] » décrivent un ensemble de caractères. Les quantificateurs comme « + » et « {3} » disent combien de fois le motif peut revenir. Un point non échappé vaut « n’importe quel caractère » : si tu veux un point littéral dans une adresse IP, tu écris « \\. », sinon tu attrapes bien plus que prévu. Avec « grep -E », tu es en regex étendues. « grep -P » active des regex de type Perl, mais cette option n’est pas disponible partout : n’écris pas une leçon qui dépend de « -P » si tu peux rester en ERE portable avec « [0-9] » plutôt que « \\d »."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Éléments regex à connaître\",\"columns\":[\"Élément regex\",\"Sens\"],\"rows\":[[\"^\",\"début de ligne\"],[\"$\",\"fin de ligne\"],[\"[0-9]\",\"un chiffre\"],[\"+\",\"une ou plusieurs fois\"],[\"( ... )\",\"groupe capture\"],[\"|\",\"ou logique\"],[\"\\\\.\",\"point littéral\"]],\"mono\":[0]}"},{"type":"text","content":"Le JSON lignes, lui, suit une autre idée : un objet JSON par ligne. C’est très pratique pour filtrer sans recoller des blocs multi-lignes. Avec « jq », tu peux sélectionner, reformater et grouper rapidement : « -r » pour sortir une chaîne sans les guillemets JSON, « -c » pour garder une sortie compacte sur une ligne, « -s » pour rassembler toutes les lignes avant d’exécuter le filtre une seule fois, en sachant que « -s » charge tout en mémoire. Sous Windows, « jq » n’est pas installé par défaut : c’est pourquoi « ConvertFrom-Json » reste une compétence importante. En JSON lignes, tu l’utilises généralement ligne par ligne ; dans Windows PowerShell 5.1, un commentaire JSON fait échouer l’analyse. Pour un CSV, bascule plutôt vers « Import-Csv » que vers une regex fragile. Dans les deux cas, n’envoie jamais un journal réel vers un service public de test. Si tu veux valider une regex en ligne, utilise des valeurs inventées."},{"type":"text","content":"Démonstration guidée : commence par un journal d’accès web. La regex doit extraire l’adresse IP, le chemin et le code HTTP sans avaler trop de texte. Ensuite, passe sur un fichier JSON lignes d’application pour ne garder que les erreurs. Tu compares enfin la version Bash et la version PowerShell : elles doivent raconter la même histoire, même si la syntaxe diffère."},{"type":"code","content":"# Extraire adresse, code et chemin depuis un journal web\nsed -En ''s#^([0-9.]+) .* \"[A-Z]+ ([^ ]+) HTTP/[0-9.]+\" ([0-9]{3}) .*#\\1 \\3 \\2#p'' access.log\n# exemple de sortie (valeurs fictives)\n# 192.0.2.11 200 /index.html\n# 192.0.2.44 403 /admin\n# 192.0.2.55 404 /wp-login.php\n# 192.0.2.11 200 /catalogue?id=7\n# 192.0.2.44 200 /api/list\n# 192.0.2.55 500 /catalogue?id=7%27\n# 192.0.2.11 200 /status\n# 192.0.2.44 500 /catalogue?id=7%20OR%201=1\n# 192.0.2.55 200 /uploads/x.php?cmd=id\n# 192.0.2.44 204 /health\n\n# Garder seulement les erreurs applicatives en JSON lignes\njq -c ''select(.level==\"error\") | {ts,ip,path}'' app.jsonl\n# exemple de sortie (valeurs fictives)\n# {\"ts\":\"2026-03-10T10:00:21Z\",\"ip\":\"192.0.2.55\",\"path\":\"/catalogue\"}\n# {\"ts\":\"2026-03-10T10:00:41Z\",\"ip\":\"192.0.2.11\",\"path\":\"/upload\"}\n# {\"ts\":\"2026-03-10T10:01:11Z\",\"ip\":\"192.0.2.44\",\"path\":\"/catalogue\"}\n# {\"ts\":\"2026-03-10T10:01:31Z\",\"ip\":\"192.0.2.55\",\"path\":\"/upload\"}","language":"bash"},{"type":"code","content":"# Équivalent PowerShell 5.1 pour la regex\nGet-Content access.log | ForEach-Object { if ($_ -match ''^(?<ip>[0-9.]+) .* \"[A-Z]+ (?<path>[^ ]+) HTTP/[0-9.]+\" (?<code>[0-9]{3}) '') { \"{0} {1} {2}\" -f $Matches.ip, $Matches.code, $Matches.path } }\n# exemple de sortie (valeurs fictives)\n# 192.0.2.11 200 /index.html\n# 192.0.2.44 403 /admin\n# 192.0.2.55 404 /wp-login.php\n\n# Équivalent PowerShell 5.1 pour le JSON lignes\nGet-Content app.jsonl | ForEach-Object { $_ | ConvertFrom-Json } | Where-Object level -eq ''error'' | ForEach-Object { \"{0} {1} {2}\" -f $_.ts, $_.ip, $_.path }\n# exemple de sortie (valeurs fictives)\n# 2026-03-10T10:00:21Z 192.0.2.55 /catalogue\n# 2026-03-10T10:00:41Z 192.0.2.11 /upload\n# 2026-03-10T10:01:11Z 192.0.2.44 /catalogue\n# 2026-03-10T10:01:31Z 192.0.2.55 /upload","language":"powershell"},{"type":"example","content":"Exemple corrigé : la regex trop large « 200 » remonte n’importe quelle ligne qui contient ce nombre, y compris un octet ou un identifiant. La version corrigée capture explicitement le code HTTP après la requête. De même, le point non échappé dans une adresse IP accepte trop de caractères. Quand tu remplaces « . » par « \\. », tu fermes la porte à beaucoup de faux positifs."},{"type":"callout","content":"Erreurs fréquentes : oublier d’échapper un point littéral ; utiliser une regex sans vérifier quelques lignes de sortie ; croire que jq est disponible de série sous Windows ; charger des journaux réels dans un testeur web de regex."},{"type":"callout","content":"Sécurité : les journaux web et JSON applicatifs peuvent contenir des identifiants, des adresses IP et des chemins sensibles. Ne les copie pas dans un service tiers. Sous Windows, préfère « ConvertFrom-Json » si jq n’est pas installé. Tu analyses uniquement des journaux de ton organisation ou d’un environnement autorisé."},{"type":"callout","content":"À retenir : une bonne regex est précise, pas seulement « pratique ». Le JSON lignes simplifie les filtres parce qu’il garde un objet par ligne. Bash avec jq et PowerShell avec ConvertFrom-Json peuvent produire la même lecture si tu nommes bien ce que tu veux extraire."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 1 : lire, normaliser et dater des journaux de formats différents » : extrais quelques champs avec une regex, filtre un JSON lignes en Bash et en PowerShell, puis compare les sorties avant de finir par le quiz."},{"type":"resource","content":"Wikipédia : expression régulière","url":"https://fr.wikipedia.org/wiki/Expression_r%C3%A9guli%C3%A8re"},{"type":"resource","content":"jq : le manuel (en anglais)","url":"https://jqlang.github.io/jq/manual/"},{"type":"resource","content":"Microsoft : l’applet de commande ConvertFrom-Json","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.utility/convertfrom-json"}]}'::jsonb, 26, 30, 2),
  ('3447fdfe-5343-3537-75d2-69aa5f519387', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'b9cf9654-4f18-dd0b-f095-aa48e72eb099', 'Automatiser l’analyse : des scripts reproductibles et vérifiables', 'Cette leçon montre comment transformer une analyse répétitive en script rejouable, avec fichier en lecture seule, hash d’entrée, seuil clair et vérification du résultat attendu.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer pourquoi scripter une analyse, vérifier un fichier d’entrée avant lecture, compter avec un seuil, conserver une empreinte pour la reproductibilité, comparer une version Bash et PowerShell, et repérer un bug logique comme « uniq » sans tri."},{"type":"callout","content":"Prérequis : avoir déjà filtré un journal texte et compris qu’une commande manuelle peut être rejouée plus sûrement quand elle est documentée."},{"type":"callout","content":"Mise en situation : Amina doit compter chaque matin les adresses qui dépassent un seuil d’échecs de connexion. Faire les mêmes commandes à la main devient fastidieux, et un collègue obtient parfois un résultat différent parce qu’il oublie une étape. Amina veut donc livrer un petit script lisible, testable et prudent, sans modifier le journal d’origine."},{"type":"callout","content":"Vidéo à venir : Passer du one-liner au script d’analyse reproductible"},{"type":"text","content":"Scripter ne veut pas dire compliquer. Cela veut dire rejouer la même analyse sans oublier d’étape, partager exactement ce qui a été fait, et vérifier qu’un collègue retrouve le même résultat. Un bon script d’analyse commence par vérifier les arguments, lire un fichier en entrée seulement, afficher une sortie explicite, et garder la trace de l’empreinte du fichier et de la version d’outil quand c’est utile."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Checklist d’un script d’analyse\",\"numbered\":true,\"items\":[{\"title\":\"Vérifier le fichier d’entrée\"},{\"title\":\"Travailler en lecture seule\"},{\"title\":\"Nommer le seuil ou les filtres\"},{\"title\":\"Trier avant de compter si nécessaire\"},{\"title\":\"Afficher un résultat simple à relire\"},{\"title\":\"Conserver hash et commande pour rejouer\"}]}"},{"type":"text","content":"Sous Bash, « set -euo pipefail » et les guillemets autour des variables évitent bien des erreurs. « -e » fait quitter sur beaucoup d’erreurs, « -u » refuse l’expansion d’une variable non définie, et « pipefail » fait remonter l’échec d’une étape intermédiaire d’un pipeline. Cela a pourtant des limites : « -e » ne se comporte pas de la même façon dans les tests de « if », « while » ou « until », ni pour toutes les commandes d’une liste « && » ou « || ». Cela aide, mais ne remplace ni les tests explicites, ni un jeu d’essai connu. Sous PowerShell, les objets facilitent le tri et le comptage. Dans les deux cas, le principe est le même : d’abord la preuve d’entrée, ensuite le comptage, et sur de gros fichiers un traitement en flux plutôt qu’un chargement complet en mémoire."},{"type":"text","content":"Démonstration guidée : le script prend un journal et un seuil. Il vérifie d’abord que le fichier existe, affiche la version de l’outil, puis calcule l’empreinte SHA-256 du fichier d’entrée. Ensuite, il compte les adresses vues après le mot « from » dans les lignes « Failed password ». Enfin, il n’affiche que celles dont le total dépasse ou atteint le seuil. Rejoue la même logique en Bash et en PowerShell : si le résultat diffère, le problème vient d’un maillon de lecture, pas d’une « magie » du shell."},{"type":"code","content":"#!/usr/bin/env bash\nset -euo pipefail\nlogfile=\"${1:?usage: analyse-failures.sh <journal> <seuil>}\"\nthreshold=\"${2:?usage: analyse-failures.sh <journal> <seuil>}\"\n[ -f \"$logfile\" ] || { echo \"fichier introuvable: $logfile\" >&2; exit 1; }\nbash --version | head -1\nsha256sum \"$logfile\"\nawk ''/Failed password/ {for (i=1;i<=NF;i++) if ($i==\"from\") print $(i+1)}'' \"$logfile\" | sort | uniq -c | awk -v limit=\"$threshold\" ''$1 >= limit {print $2 \",\" $1}''\n# exemple de sortie (valeurs fictives)\n# bash 5.3.15(2)-release\n# c67ce98586c725e43d78f84ccc0e5c33a684343aff8e1d773996deb457d2b779 *tool-auth.log\n# 192.0.2.11,11\n# 192.0.2.44,6\n# 192.0.2.55,5\n# 192.0.2.99,5","language":"bash"},{"type":"code","content":"param([string]$Path,[int]$Threshold=5)\nif (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw \"Fichier introuvable : $Path\" }\n$PSVersionTable.PSVersion.ToString()\nGet-FileHash -LiteralPath $Path -Algorithm SHA256 | ForEach-Object { $_.Hash }\nGet-Content -LiteralPath $Path | Where-Object { $_ -match \"Failed password\" } | ForEach-Object { if ($_ -match \"from (?<ip>[0-9.]+)\") { $Matches.ip } } | Group-Object -NoElement | Where-Object Count -ge $Threshold | Sort-Object Count -Descending | ForEach-Object { \"{0},{1}\" -f $_.Name, $_.Count }\n# exemple de sortie (valeurs fictives)\n# 5.1.26100.9549\n# C67CE98586C725E43D78F84CCC0E5C33A684343AFF8E1D773996DEB457D2B779\n# 192.0.2.11,11\n# 192.0.2.44,6\n# 192.0.2.55,5\n# 192.0.2.99,5","language":"powershell"},{"type":"example","content":"Exemple corrigé : si ton premier script oublie le tri avant « uniq -c », tu obtiens un résultat incohérent selon l’ordre du fichier. Le jeu de test attendu doit ici sortir quatre adresses au seuil 5 : 192.0.2.11, 192.0.2.44, 192.0.2.55 et 192.0.2.99. Si ton script en montre moins ou fragmente les comptes, le bug n’est pas dans le journal : il est dans la logique de comptage."},{"type":"callout","content":"Erreurs fréquentes : modifier le journal original au lieu de travailler en lecture seule ; oublier de vérifier que le fichier existe ; laisser des variables non protégées sans guillemets en Bash ; croire qu’un script juste une fois est juste pour toujours sans jeu de test connu."},{"type":"callout","content":"Sécurité : un script d’analyse ne doit jamais réécrire ni nettoyer le journal d’origine. Garde les traces sensibles sur ton poste ou ton environnement autorisé, pas dans un dépôt public. N’inscris aucun secret dans le script ni dans la ligne de commande, et note toujours sur quel fichier et avec quel seuil tu as travaillé."},{"type":"callout","content":"À retenir : scripter, c’est rendre ton analyse rejouable, partageable et vérifiable. Le hash du fichier, le seuil explicite et le petit jeu de test attendu font gagner plus de fiabilité qu’un one-liner impressionnant mais opaque."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 1 : lire, normaliser et dater des journaux de formats différents » : transforme une analyse répétée en script, compare Bash et PowerShell, puis vérifie le résultat attendu avant de finir par le quiz."},{"type":"resource","content":"NIST SP 800-86 : intégrer l’investigation numérique à la réponse aux incidents (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/86/final"},{"type":"resource","content":"ShellCheck : SC2086, mettre les variables entre guillemets (en anglais)","url":"https://www.shellcheck.net/wiki/SC2086"},{"type":"resource","content":"Microsoft : l’applet de commande Where-Object","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.core/where-object"}]}'::jsonb, 24, 30, 3),
  ('02e318ea-d014-dcf2-bb23-08b07926d50e', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8dfef90e-761f-7bcb-6d62-86dc99d68558', 'Corréler plusieurs sources : clés communes, pivots et enrichissement', 'Apprends à relier plusieurs journaux sans confondre corrélation, causalité et preuve, puis à bâtir une chronologie propre en UTC avec des pivots défendables.', '{"blocks":[{"type":"callout","content":"Objectifs : choisir une clé de corrélation, pivoter d’une source à une autre, repérer une clé trompeuse, bâtir une chronologie en UTC, et défendre une conclusion par au moins deux sources indépendantes."},{"type":"callout","content":"Prérequis : avoir suivi « Relier les événements sans conclure trop vite » et savoir lire un journal web, un journal d’authentification et un journal de proxy."},{"type":"callout","content":"Mise en situation : Nadia reçoit un signal faible sur « web01 ». Un même poste interne apparaît dans un journal SSH, dans les accès d’un portail et dans le journal du mandataire. Elle doit comprendre si ces traces racontent une même histoire, ou si elles mélangent un collègue pressé, un robot de supervision et un simple téléchargement légitime."},{"type":"callout","content":"Vidéo à venir : Corréler trois journaux sans surinterpréter les indices"},{"type":"text","content":"Corréler, ce n’est pas aligner des lignes qui se ressemblent. C’est relier des événements par une clé commune : adresse IP, compte, nom de machine, identifiant de session, identifiant de requête, empreinte de fichier ou plage de temps. Le pivot est le point de départ que tu poursuis dans une autre source. Avant toute jointure, tu notes le fuseau de chaque journal puis tu convertis en UTC. Sinon, une horloge décalée peut te faire relier un effet à une cause qui n’existe pas."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Clés de corrélation utiles\",\"columns\":[\"Clé commune utile\",\"Ce qu’elle relie\"],\"rows\":[[\"IP source\",\"un poste précis ou une sortie partagée, par exemple derrière un NAT ou un VPN\"],[\"Compte utilisateur\",\"une action humaine ou un service\"],[\"Nom de machine\",\"un actif précis de l’inventaire\"],[\"Identifiant de session\",\"un parcours applicatif sur plusieurs lignes\"],[\"Identifiant de requête\",\"une transaction web ou API\"],[\"Empreinte de fichier\",\"un même artefact sur plusieurs hôtes\"],[\"Fenêtre de temps\",\"des événements proches à confirmer par une autre clé\"]]}"},{"type":"text","content":"Une bonne corrélation garde une place aux trous et aux pièges. Un NAT, une passerelle VPN de sortie, un bail DHCP, des adresses partagées, deux machines qui portent le même nom dans des domaines différents, ou une horloge non synchronisée peuvent casser le lien. Tu le notes, puis tu cherches une deuxième source indépendante. Une adresse IP prouve qu’une source a consigné une communication associée à cette adresse à ce moment-là. Elle ne prouve ni, à elle seule, la personne au clavier, ni l’intention, ni même la machine exacte derrière une sortie partagée. La corrélation montre donc un lien plausible ; elle ne prouve pas, à elle seule, la cause de ce lien."},{"type":"text","content":"Démonstration guidée : sur trois extraits inventés de 15 lignes chacun, on repère d’abord l’adresse qui réussit en SSH après plusieurs échecs, puis on regarde ce qu’elle fait dans le portail web et dans le proxy. Les commandes ci-dessous ont été rejouées sur les extraits. Elles montrent une méthode simple : détecter, pivoter, convertir l’heure en UTC, puis résumer. Avec les outils GNU, retiens aussi que « sort », « join » et « comm » travaillent sur des listes triées selon la clé utile. Tu peux refaire cette lecture avec Git Bash, WSL, Termux ou PowerShell, sans SIEM."},{"type":"code","content":"# Extraire les adresses qui réussissent après au moins deux échecs\nawk ''/Failed password|Accepted password/ {\n  if (match($0,/from ([0-9.]+)/,m)) {\n    ip=m[1]\n    if ($0 ~ /Failed password/) failed[ip]++\n    else if (failed[ip] >= 2) print ip \"\\tssh_ok_apres_\" failed[ip] \"_echecs\"\n  }\n}'' auth.log | sort -t $''\\t'' -k1,1 -u > suspect.tsv\n# exemple de sortie (valeurs fictives)\n# 10.1.4.23\tssh_ok_apres_3_echecs\n\n# Associer ensuite les chemins web vus depuis cette même adresse\nawk ''match($0,/^([0-9.]+) - - \\[[^]]+\\] \"[A-Z]+ ([^ ]+)/,m){print m[1] \"\\t\" m[2]}'' access.log | sort -t $''\\t'' -k1,1 -k2,2 -u > web.tsv\njoin -t $''\\t'' suspect.tsv web.tsv | head -3\n# exemple de sortie (valeurs fictives)\n# 10.1.4.23\tssh_ok_apres_3_echecs\t/admin/audit\n# 10.1.4.23\tssh_ok_apres_3_echecs\t/admin/dashboard\n# 10.1.4.23\tssh_ok_apres_3_echecs\t/admin/export.csv\n\n# Vérifier ce qui apparaît dans les deux listes d’adresses\ncut -f1 suspect.tsv | sort -u > suspect-ip.txt\ncut -f1 web.tsv | sort -u > web-ip.txt\ncomm -12 suspect-ip.txt web-ip.txt\n# exemple de sortie (valeurs fictives)\n# 10.1.4.23","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"timeline\",\"title\":\"Chronologie UTC à produire\",\"events\":[{\"at\":\"2026-03-12T08:12:02Z\",\"title\":\"auth\",\"text\":\"succès SSH pour awa depuis 10.1.4.23\",\"icon\":\"key\",\"tone\":\"green\"},{\"at\":\"2026-03-12T08:13:02Z\",\"title\":\"web\",\"text\":\"GET `/admin/export.csv` depuis 10.1.4.23\",\"icon\":\"document\",\"tone\":\"blue\"},{\"at\":\"2026-03-12T08:13:55Z\",\"title\":\"proxy\",\"text\":\"GET `http://files.example.org/archive.zip`\",\"icon\":\"download\",\"tone\":\"violet\"}],\"caption\":\"Preuve minimale : fichier, ligne, clé de pivot et hypothèse encore ouverte.\"}"},{"type":"text","content":"Sous PowerShell, tu peux obtenir le même type de résumé avec des objets. Le réflexe utile est de compter d’abord, puis de joindre seulement ce qui mérite une lecture humaine. En Windows PowerShell 5.1, il n’existe pas de cmdlet native de jointure tabulaire générique : on rapproche donc les sources avec « Group-Object », des tables de hachage et un filtrage explicite sur la clé choisie. Ici, on importe trois petits fichiers CSV déjà normalisés en UTC, puis on rapproche les adresses présentes dans les trois sources. Cette étape ne prouve toujours pas une compromission : elle prépare une analyse plus serrée."},{"type":"code","content":"# Importer les trois sources normalisées en UTC, puis joindre les adresses communes\n$auth = Import-Csv .\\corr-auth.csv\n$web = Import-Csv .\\corr-web.csv\n$proxy = Import-Csv .\\corr-proxy.csv\n\n$webByIp = @{}\n$web | Group-Object Ip | ForEach-Object { $webByIp[$_.Name] = ($_.Group.Path -join '', '') }\n$proxyByIp = @{}\n$proxy | Group-Object Ip | ForEach-Object { $proxyByIp[$_.Name] = ($_.Group.Url -join '', '') }\n\n$auth | Group-Object Ip -NoElement | Sort-Object Count -Descending\n# exemple de sortie (valeurs fictives)\n# Count Name\n# ----- ----\n#     1 10.1.4.52\n#     1 10.1.4.23\n\n$auth | Where-Object { $webByIp.ContainsKey($_.Ip) -and $proxyByIp.ContainsKey($_.Ip) } |\n  Select-Object Ip,User,@{Name=''Web'';Expression={$webByIp[$_.Ip]}},@{Name=''Proxy'';Expression={$proxyByIp[$_.Ip]}} |\n  Format-Table -AutoSize\n# exemple de sortie (valeurs fictives)\n# Ip        User Web                      Proxy\n# --        ---- ---                      -----\n# 10.1.4.23 awa  /login, /admin/dashboard http://intranet.example.org/notes, http://updates.example.net/tool.txt\n# 10.1.4.52 awa  /docs                    http://docs.example.org/guide, http://docs.example.org/api","language":"powershell"},{"type":"example","content":"Exemple corrigé : trois échecs puis une réussite sur « 10.1.4.52 » pourraient faire croire à une attaque. La deuxième source casse pourtant l’emballement : le portail ne montre qu’un accès à « /docs », et le proxy ne voit que de la documentation interne. Un bail DHCP ou une sortie VPN partagée peuvent aussi expliquer une adresse vue ailleurs au même moment. L’hypothèse raisonnable devient donc « mot de passe mal saisi puis correction », pas « compromission ». Une corrélation sérieuse accepte de retirer une suspicion quand la deuxième source la contredit."},{"type":"callout","content":"Erreurs fréquentes : utiliser une seule clé sans vérifier si elle est partagée ; joindre des heures locales et UTC sans conversion ; oublier NAT, DHCP, VPN ou horloge décalée ; confondre corrélation et causalité ; conclure à partir d’un seul succès ou d’un seul échec sans deuxième preuve indépendante."},{"type":"callout","content":"Sécurité : tu analyses seulement les journaux de ton organisation ou d’un système pour lequel tu as un mandat écrit. Si tu dois enrichir une adresse ou un domaine, commence par les sources internes. Ne colle jamais un extrait complet de journal réel dans un service en ligne : il peut contenir des identifiants, des adresses et des habitudes de travail."},{"type":"callout","content":"À retenir : corréler, c’est relier par une clé commune puis vérifier que cette clé tient. Convertis d’abord le temps en UTC, cherche ensuite ce qui confirme et ce qui contredit, puis garde une deuxième source avant toute conclusion. Un pivot utile ouvre une enquête, pas une causalité automatique."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 4 : corréler trois sources et dresser la chronologie » : pars d’une adresse ou d’un compte, pivote vers les autres journaux, note les trous éventuels, puis termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"},{"type":"resource","content":"NIST SP 800-92 : guide de la gestion des journaux de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/92/final"},{"type":"resource","content":"Microsoft : l’applet de commande Group-Object","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.utility/group-object"}]}'::jsonb, 24, 30, 1),
  ('84370fe4-45d9-8475-3d27-b189a6cfa86e', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8dfef90e-761f-7bcb-6d62-86dc99d68558', 'Écrire une règle de détection : seuils, fenêtres de temps et Sigma', 'Transforme une observation en règle simple, choisis un seuil défendable, compare fenêtre fixe et glissante, puis relie ta détection à Sigma, à ATT&CK et à la pyramide de la douleur sans promettre plus que ce que tu peux prouver.', '{"blocks":[{"type":"callout","content":"Objectifs : définir une condition de détection, choisir un seuil et une fenêtre de temps, grouper par source ou par compte, écrire une règle Sigma simple, et rattacher une détection à une technique ATT&CK pertinente."},{"type":"callout","content":"Prérequis : savoir compter dans un journal avec grep, awk, PowerShell, et avoir compris ce qu’est une corrélation."},{"type":"callout","content":"Mise en situation : Mamadou doit transformer une observation répétée en détection exploitable. Son équipe voit souvent des échecs SSH et quelques scans web. Il lui faut une règle qui attire l’attention sur le bruit anormal, sans noyer ses collègues sous des alertes inutiles."},{"type":"callout","content":"Vidéo à venir : Passer d’une intuition à une règle de détection simple"},{"type":"text","content":"Une règle de détection décrit ce qui doit attirer ton attention. Elle répond à cinq questions : quel événement, sur quelle source, groupé comment, au-dessus de quel seuil, et dans quelle fenêtre de temps. Exemple classique : « au moins cinq échecs SSH depuis une même adresse en cinq minutes ». Sans seuil ni fenêtre, tu crées souvent une alerte bavarde. Sans regroupement, tu mélanges plusieurs utilisateurs ou plusieurs adresses et tu perds le sens opérationnel."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Une règle simple contient\",\"columns\":3,\"items\":[{\"term\":\"condition\",\"text\":\"ce qui doit être vrai\",\"tone\":\"cyan\"},{\"term\":\"groupement\",\"text\":\"par source, par compte, par machine ou par processus\",\"tone\":\"blue\"},{\"term\":\"fenêtre\",\"text\":\"combien de minutes ou d’heures\",\"tone\":\"violet\"},{\"term\":\"seuil\",\"text\":\"à partir de combien d’occurrences\",\"tone\":\"amber\"},{\"term\":\"contexte\",\"text\":\"exclusions, heures ouvrées, biens critiques\",\"tone\":\"green\"},{\"term\":\"sortie\",\"text\":\"gravité, titre, description, prochaine action\",\"tone\":\"neutral\"}]}"},{"type":"text","content":"Sigma n’est pas un SIEM. C’est un format de règle indépendant du produit, en YAML, pour décrire une sélection et la partager. Une règle Sigma simple contient notamment « title », « id », « status », « logsource », « detection », « condition », « falsepositives », « level » et « tags ». Reste simple : champs, valeurs, condition. La corrélation avancée et l’agrégation changent selon l’outil de destination. Pour un débutant, la bonne pratique est donc d’écrire une sélection claire en Sigma, puis de tester le seuil et la fenêtre avec un script ou dans le moteur de requête de ton outil."},{"type":"code","content":"title: Échecs SSH répétés depuis une même source\nid: 11111111-2222-4333-8444-555555555555\nstatus: experimental\ndescription: Détecte des messages \"Failed password\" dans sshd.\nlogsource:\n  product: linux\n  service: sshd\ndetection:\n  selection:\n    message|contains: \"Failed password\"\n  condition: selection\nfalsepositives:\n  - faute de frappe répétée sur un bastion\nlevel: medium\ntags:\n  - attack.t1110","language":"yaml"},{"type":"text","content":"Le tag « attack.t1110 » rattache ici la règle à la technique MITRE ATT&CK « T1110 Brute Force ». C’est utile pour ranger les détections par comportement observé, pas pour faire joli. Côté défense, la pyramide de la douleur aide à choisir quoi viser. Bloquer une adresse IP gêne peu un attaquant. Détecter un comportement, comme une rafale d’échecs suivie d’un succès, lui coûte plus cher à contourner parce qu’il doit changer sa méthode, pas seulement une valeur de configuration."},{"type":"text","content":"Démonstration guidée : on prend un extrait de journal d’authentification et on applique la règle « au moins cinq échecs entre 08:14:00 et 08:18:59, groupés par adresse source ». C’est une fenêtre fixe : le temps est découpé ici en un intervalle prédéfini. Une fenêtre glissante regarderait cinq minutes à partir de chaque nouvel événement et réévaluerait la condition à chaque arrivée. La sortie a été vérifiée deux fois : une fois avec awk, une fois avec Node pour contrôler le compte final. Le résultat montre une seule adresse à suivre."},{"type":"code","content":"# Compter les échecs SSH par adresse dans une fenêtre de cinq minutes\nawk ''$3 >= \"08:14:00\" && $3 <= \"08:18:59\" && /Failed password/ {\n  if (match($0,/from ([0-9.]+)/,m)) n[m[1]]++\n}\nEND {\n  for (ip in n) if (n[ip] >= 5) print ip \"\\t\" n[ip]\n}'' auth.log | sort\n# exemple de sortie (valeurs fictives)\n# 192.0.2.44\t5","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Fenêtre et seuil doivent être explicites\",\"items\":[{\"term\":\"Fenêtre fixe\",\"text\":\"intervalle prédéfini, ici 08:14:00 à 08:18:59\",\"tone\":\"blue\"},{\"term\":\"Fenêtre glissante\",\"text\":\"cinq minutes recalculées à partir de chaque nouvel événement\",\"tone\":\"violet\"},{\"term\":\"Seuil 3\",\"text\":\"attrape aussi un utilisateur qui insiste trop vite\",\"tone\":\"amber\"},{\"term\":\"Seuil 5\",\"text\":\"garde ici le scanner 192.0.2.44, laisse passer le poste 10.1.4.23\",\"tone\":\"green\"},{\"term\":\"Seuil 8\",\"text\":\"risque de rater l’attaque lente\",\"tone\":\"red\"}]}"},{"type":"example","content":"Exemple corrigé : si ton extrait contient cinq échecs de « 192.0.2.44 » entre 08:14:10 et 08:14:28, puis seulement trois échecs de « 10.1.4.23 » avant un succès légitime plus tôt dans la matinée, un seuil de 5 en cinq minutes est plus défendable qu’un seuil de 3. Le seuil de 3 ferait remonter l’utilisateur pressé, alors que celui de 5 garde le comportement agressif. Tu documentes aussi si ta fenêtre est fixe ou glissante, car ce choix change le moment où l’alerte se déclenche."},{"type":"callout","content":"Erreurs fréquentes : écrire une règle sans dire comment elle regroupe les événements ; oublier de préciser si la fenêtre est fixe ou glissante ; confondre un exemple Sigma simple avec une corrélation complète dépendante d’un SIEM ; coller un identifiant ATT&CK sans lien réel avec le comportement observé ; choisir un seuil « parce qu’il sonne bien » sans test sur un extrait connu."},{"type":"callout","content":"Sécurité : les exemples servent à reconnaître des traces défensivement. Tu n’essaies pas de reproduire une force brute sur un système réel. Analyse uniquement des journaux fournis, les tiens, ou des systèmes sur lesquels tu as une autorisation écrite."},{"type":"callout","content":"À retenir : une règle utile décrit une condition, un regroupement, un seuil et une fenêtre de temps. Dis toujours si la fenêtre est fixe ou glissante. Sigma t’aide à partager la sélection de base. ATT&CK t’aide à nommer le comportement. Le bon seuil vient d’un test, pas d’une intuition."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : règles de détection : seuils, fenêtres et faux positifs » : applique plusieurs seuils au même jeu de journaux, relie la règle à une technique pertinente, puis termine par le quiz."},{"type":"resource","content":"Sigma : écrire une règle (en anglais)","url":"https://sigmahq.io/docs/basics/rules.html"},{"type":"resource","content":"MITRE ATT&CK : T1110, force brute (en anglais)","url":"https://attack.mitre.org/techniques/T1110/"},{"type":"resource","content":"David Bianco : la pyramide de la douleur (en anglais)","url":"https://detect-respond.blogspot.com/2013/03/the-pyramid-of-pain.html"}]}'::jsonb, 26, 30, 2),
  ('b3360077-4ea7-967d-471d-831ed39073f6', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8dfef90e-761f-7bcb-6d62-86dc99d68558', 'Faux positifs et réglage : mesurer et améliorer une détection', 'Mesure ce que ta règle voit vraiment, calcule précision et rappel, puis règle un seuil ou une exclusion documentée sans sacrifier la surveillance.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer vrai positif, faux positif et faux négatif, calculer précision et rappel, comparer deux seuils, documenter une exclusion, et choisir un réglage qui reste défendable."},{"type":"callout","content":"Prérequis : avoir déjà écrit une règle simple avec un seuil et une fenêtre de temps."},{"type":"callout","content":"Mise en situation : Awa a enfin une règle qui lève des alertes, mais son équipe soupire : certaines sont utiles, d’autres tombent à chaque lundi matin sur les mêmes postes. Elle doit mesurer le problème, pas seulement le ressentir, puis corriger la règle sans la désactiver par fatigue."},{"type":"callout","content":"Vidéo à venir : Réduire les faux positifs sans rendre une règle aveugle"},{"type":"text","content":"Une alerte utile est un vrai positif : elle signale quelque chose qui mérite réellement l’attention. Un faux positif alerte à tort. Un faux négatif est pire : l’attaque existe, mais la règle ne la voit pas. Un vrai négatif correspond à une activité bénigne que la règle ne signale pas. Pour améliorer une détection, tu comptes donc d’abord VP, FP et FN, et tu gardes le VN pour le raisonnement global si besoin. La précision répond à « parmi les alertes levées, combien étaient justifiées ? ». Le rappel répond à « parmi les attaques réelles, combien ont été détectées ? ». Il faut regarder les deux, sinon tu risques de féliciter une règle silencieuse qui laisse tout passer."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Mesures de base\",\"items\":[{\"term\":\"VP\",\"text\":\"vrai positif\",\"tone\":\"green\"},{\"term\":\"FP\",\"text\":\"faux positif\",\"tone\":\"red\"},{\"term\":\"FN\",\"text\":\"faux négatif\",\"tone\":\"amber\"},{\"term\":\"VN\",\"text\":\"vrai négatif\",\"tone\":\"blue\"},{\"term\":\"précision\",\"text\":\"VP / (VP + FP)\",\"tone\":\"violet\"},{\"term\":\"rappel\",\"text\":\"VP / (VP + FN)\",\"tone\":\"cyan\"},{\"term\":\"seuil bas\",\"text\":\"plus sensible, souvent plus bruyant\",\"tone\":\"amber\"},{\"term\":\"seuil haut\",\"text\":\"moins bruyant, mais peut rater des attaques lentes\",\"tone\":\"red\"}]}"},{"type":"text","content":"Le réglage ne se fait pas au bruit ambiant. Il se fait sur un jeu de vérité : un petit lot d’événements étiquetés, dont tu connais le résultat attendu. C’est la seule manière honnête de comparer deux seuils, deux fenêtres, ou une exclusion. Si tu exclus un compte de supervision, tu notes qui l’a décidé, pourquoi, jusqu’à quand, et dans quel contexte cette exclusion reste valide."},{"type":"text","content":"Démonstration guidée : le fichier « jeu-verite.csv » contient 30 événements étiquetés, avec un nombre d’échecs par source et l’étiquette finale « attaque » ou « normal ». On calcule ensuite VP, FP et FN pour deux seuils. Les résultats PowerShell ont été recalculés avec Node sur le même fichier pour vérifier les chiffres et les formules. Tu peux refaire exactement la même méthode sur un vrai export de ton organisation."},{"type":"code","content":"# Comparer deux seuils sur le même jeu de vérité\n$rows = Import-Csv .\\jeu-verite.csv\nforeach ($threshold in 3,5) {\n  $flagged = $rows | Where-Object { [int]$_.failures -ge $threshold }\n  $vp = @($flagged | Where-Object truth -eq ''attaque'').Count\n  $fp = @($flagged | Where-Object truth -eq ''normal'').Count\n  $fn = @($rows | Where-Object { $_.truth -eq ''attaque'' -and [int]$_.failures -lt $threshold }).Count\n  [pscustomobject]@{ Seuil=$threshold; Alertes=@($flagged).Count; VP=$vp; FP=$fp; FN=$fn }\n} | Format-Table -AutoSize\n# exemple de sortie (valeurs fictives)\n# Seuil Alertes VP FP FN\n# ----- ------- -- -- --\n#     3      16  8  8  0\n#     5       8  6  2  2","language":"powershell"},{"type":"text","content":"La règle a besoin d’un compromis explicite. Ici, le seuil 3 n’oublie aucune attaque, mais il produit autant de faux positifs que de vrais. Le seuil 5 réduit fortement le bruit, au prix de deux faux négatifs. Le bon choix dépend du contexte : un compte d’administration exposé justifie plus de sensibilité qu’un poste bureautique connu. L’important est de choisir consciemment, puis de mesurer à nouveau après chaque changement."},{"type":"code","content":"// Rejouer tous les calculs de précision et de rappel avec Node.js\nconst scenarios = [\n  { nom: ''seuil_3'', vp: 8, fp: 8, fn: 0 },\n  { nom: ''seuil_5'', vp: 6, fp: 2, fn: 2 },\n  { nom: ''autre_scenario'', vp: 6, fp: 34, fn: 2 },\n];\nfor (const s of scenarios) {\n  const precision = s.vp / (s.vp + s.fp);\n  const rappel = s.vp / (s.vp + s.fn);\n  console.log(`${s.nom}\\tprecision=${(precision * 100).toFixed(1)}%\\trappel=${(rappel * 100).toFixed(1)}%`);\n}\n// exemple de sortie (valeurs fictives)\n// seuil_3\tprecision=50.0%\trappel=100.0%\n// seuil_5\tprecision=75.0%\trappel=75.0%\n// autre_scenario\tprecision=15.0%\trappel=75.0%","language":"javascript"},{"type":"example","content":"Exemple corrigé : sur le jeu de 30 événements, le seuil 3 donne ici VP=8, FP=8 et FN=0, donc une précision de 50,0 % et un rappel de 100,0 %. Le seuil 5 donne VP=6, FP=2 et FN=2, donc une précision de 75,0 % et un rappel de 75,0 %. Sur l’autre scénario connu, 40 alertes dont 6 justifiées pour 8 attaques réelles donnent bien 34 faux positifs et 2 faux négatifs, soit 15,0 % de précision et 75,0 % de rappel. Si ton équipe croule déjà sous le bruit, le seuil 5 peut être plus tenable à court terme, à condition de l’accompagner d’une revue périodique et d’un plan pour récupérer les deux attaques ratées. En revanche, désactiver la règle sans mesure serait une décision aveugle."},{"type":"callout","content":"Erreurs fréquentes : juger une règle au ressenti sans jeu de vérité ; ne regarder que la précision ou seulement le rappel ; monter le seuil jusqu’au silence puis déclarer la règle « réglée » ; créer une exclusion permanente sans propriétaire ni date de révision ; couper une règle devenue bruyante sans comprendre d’où viennent les faux positifs."},{"type":"callout","content":"Sécurité : ne publie pas un jeu de vérité réel contenant des identifiants ou des traces internes. Si tu dois partager un cas, désarme les indicateurs et retire tout détail personnel qui n’est pas nécessaire à l’apprentissage."},{"type":"callout","content":"À retenir : une règle se règle avec des mesures, pas avec de l’agacement. Compte VP, FP et FN, refais les formules à la main, puis mesure avant et après le changement. Une exclusion défendable est datée, motivée, et révisée. Une règle silencieuse n’est pas forcément une bonne règle."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : règles de détection : seuils, fenêtres et faux positifs » : compare au moins deux réglages, calcule précision et rappel, documente une exclusion prudente, puis termine par le quiz."},{"type":"resource","content":"NIST SP 800-92 : guide de la gestion des journaux de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/92/final"},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"},{"type":"resource","content":"Sigma : des règles de détection indépendantes du produit (en anglais)","url":"https://sigmahq.io/"}]}'::jsonb, 22, 30, 3),
  ('2a9d1cf9-c38f-80f9-0202-6a143b8f32ff', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '9bbc731c-3ce3-2024-c67b-c719856c68ac', 'Gravité, priorité et escalade : décider quoi traiter en premier', 'Distingue la gravité de la priorité, calcule la gravité par impact × probabilité puis la priorité par gravité × criticité du bien × certitude, et décide quoi traiter d’abord sans inventer de délai standard.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer gravité et priorité, calculer la gravité, transformer une qualification en certitude, appliquer une formule de priorité cohérente, classer plusieurs alertes, et préparer une escalade claire en quelques lignes."},{"type":"callout","content":"Prérequis : avoir compris le triage d’une alerte et savoir distinguer faits, hypothèses et décision."},{"type":"callout","content":"Mise en situation : Koffi ouvre sa file d’attente et voit six alertes en même temps : un scan web, un compte de service ajouté à un groupe admin, un DNS inhabituel, un échec isolé, un export sensible et un effacement de journal Security. Il doit décider quoi traiter d’abord sans céder au réflexe « premier arrivé, premier servi »."},{"type":"callout","content":"Vidéo à venir : Choisir une priorité sans inventer une norme de réponse"},{"type":"text","content":"La gravité mesure ce que l’événement pourrait causer. La priorité décide ce que tu traites en premier. Dans ce parcours, on garde une seule formule de classement : « priorité = gravité × criticité du bien × certitude ». La gravité décrit le dommage potentiel. La priorité ordonne l’action. La certitude vient de la qualification du triage : vrai positif, à surveiller, ou faux positif. Deux alertes peuvent donc partager la même gravité et ne pas avoir la même priorité."},{"type":"schema","content":"{\"v\":1,\"kind\":\"formula\",\"title\":\"Repères utiles\",\"items\":[{\"label\":\"Gravité\",\"formula\":\"gravité = impact × probabilité\",\"example\":\"impact = ce qui pourrait être cassé, perdu ou exposé\\nprobabilité = vraisemblance du scénario redouté\",\"result\":\"la gravité estime le dommage potentiel\",\"tone\":\"amber\"},{\"label\":\"Priorité\",\"formula\":\"priorité = gravité × criticité du bien × certitude\",\"example\":\"criticité = importance du bien concerné\\ncertitude = confiance issue de la qualification\",\"result\":\"chaque organisation fixe ses entiers et ses seuils\",\"tone\":\"red\"}]}"},{"type":"text","content":"Une manière simple d’enseigner la méthode consiste à choisir des échelles entières locales. Ici, on prend impact, probabilité et criticité sur 1 à 4, puis certitude sur 0 à 4 avec un exemple prudent : faux positif = 0, à surveiller = 2, vrai positif = 4. Ce sont des choix pédagogiques, pas une norme universelle. Le calcul aide au classement ; chaque organisation fixe ses propres échelles, ses seuils d’escalade et ses objectifs de réaction."},{"type":"text","content":"Démonstration guidée : sur quatre alertes inventées, on calcule d’abord la gravité, puis la priorité complète avec la formule du parcours. Les commandes Git Bash et PowerShell ci-dessous ont été rejouées, puis les totaux ont été recalculés avec Node pour vérifier les produits, les pourcentages éventuels et le classement final."},{"type":"code","content":"# Rejouer le classement dans Git Bash à partir d’un TSV\nawk -F ''\\t'' ''NR==1 {print $0 \"\\tgravite\\tpriorite\"; next} {\n  gravite = $2 * $3\n  priorite = gravite * $4 * $5\n  print $0 \"\\t\" gravite \"\\t\" priorite\n}'' priorites.tsv | sort -t $''\\t'' -k7,7nr -k6,6nr\n# exemple de sortie (valeurs fictives)\n# alerte\timpact\tprobabilite\tcriticite\tcertitude\tgravite\tpriorite\n# export_admin_confirme\t4\t3\t4\t4\t12\t192\n# effacement_security\t4\t1\t4\t4\t4\t64\n# dns_inhabituel_metier\t3\t2\t3\t2\t6\t36\n# scan_404_vitrine\t2\t2\t2\t2\t4\t16","language":"bash"},{"type":"code","content":"$rows = Import-Csv .\\priorites.csv | ForEach-Object {\n  $impact = [int]$_.impact; $probabilite = [int]$_.probabilite; $criticite = [int]$_.criticite; $certitude = [int]$_.certitude\n  [pscustomobject]@{\n    Alerte=$_.alerte; Impact=$impact; Probabilite=$probabilite; Criticite=$criticite; Certitude=$certitude;\n    Gravite=$impact*$probabilite; Priorite=($impact*$probabilite)*$criticite*$certitude\n  }\n}\n$rows | Sort-Object Priorite -Descending, Gravite -Descending | Format-Table -AutoSize\n# exemple de sortie (valeurs fictives)\n# Alerte                 Impact Probabilite Criticite Certitude Gravite Priorite\n# ------                 ------ ----------- --------- --------- ------- --------\n# export_admin_confirme       4           3         4         4      12      192\n# effacement_security         4           1         4         4       4       64\n# dns_inhabituel_metier       3           2         3         2       6       36\n# scan_404_vitrine            2           2         2         2       4       16","language":"powershell"},{"type":"code","content":"// Vérifier les produits et le classement avec Node.js\nconst certitude = { vrai_positif: 4, a_surveiller: 2, faux_positif: 0 };\nconst alertes = [\n  { alerte: ''export_admin_confirme'', impact: 4, probabilite: 3, criticite: 4, certitude: certitude.vrai_positif },\n  { alerte: ''effacement_security'', impact: 4, probabilite: 1, criticite: 4, certitude: certitude.vrai_positif },\n  { alerte: ''dns_inhabituel_metier'', impact: 3, probabilite: 2, criticite: 3, certitude: certitude.a_surveiller },\n  { alerte: ''scan_404_vitrine'', impact: 2, probabilite: 2, criticite: 2, certitude: certitude.a_surveiller },\n];\nconst classes = alertes.map(a => ({\n  ...a,\n  gravite: a.impact * a.probabilite,\n  priorite: a.impact * a.probabilite * a.criticite * a.certitude,\n})).sort((a, b) => b.priorite - a.priorite || b.gravite - a.gravite || b.criticite - a.criticite);\nconsole.table(classes);\n// exemple de sortie (valeurs fictives) : export_admin_confirme reste devant effacement_security,\n// puis dns_inhabituel_metier, puis scan_404_vitrine.","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Exemple d’échelles locales à expliquer\",\"items\":[{\"term\":\"impact\",\"text\":\"1 à 4\",\"tone\":\"amber\"},{\"term\":\"probabilité\",\"text\":\"1 à 4\",\"tone\":\"amber\"},{\"term\":\"criticité\",\"text\":\"1 à 4\",\"tone\":\"amber\"},{\"term\":\"certitude 0\",\"text\":\"faux positif confirmé\",\"tone\":\"green\"},{\"term\":\"certitude 2\",\"text\":\"à surveiller\",\"tone\":\"violet\"},{\"term\":\"certitude 4\",\"text\":\"vrai positif confirmé\",\"tone\":\"red\"},{\"term\":\"rappel\",\"text\":\"même gravité ≠ même priorité\",\"tone\":\"blue\"}]}"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Escalade claire en dix lignes maximum\",\"items\":[{\"title\":\"quoi\",\"text\":\"type d’alerte et système\"},{\"title\":\"quand\",\"text\":\"heure UTC\"},{\"title\":\"preuve\",\"text\":\"journal et ligne clé\"},{\"title\":\"gravité\",\"text\":\"ce que l’événement pourrait causer\"},{\"title\":\"priorité\",\"text\":\"pourquoi ce cas passe avant les autres\"},{\"title\":\"proposition\",\"text\":\"surveiller, bloquer, appeler, passer la main\"}]}"},{"type":"text","content":"Deux alertes peuvent donc partager la même gravité et ne pas avoir la même priorité. Dans l’exemple, « effacement_security » et « scan_404_vitrine » ont tous deux une gravité de 4. Pourtant, leurs priorités diffèrent fortement, car la criticité du bien et la certitude ne sont pas les mêmes. Le calcul est une aide au classement. Il ne remplace ni la procédure, ni le contexte métier, ni le jugement d’un responsable si une mesure risque de couper un service. Il ne fixe jamais, à lui seul, un délai « standard » de réaction."},{"type":"example","content":"Exemple corrigé : deux alertes ont la même gravité 4. La première est « effacement_security » avec impact 4, probabilité 1, criticité 4 et certitude 4, soit une priorité de 64. La seconde est « scan_404_vitrine » avec impact 2, probabilité 2, criticité 2 et certitude 2, soit une priorité de 16. Même gravité, ordre différent : tu traites d’abord la première parce qu’elle touche un bien plus critique et qu’elle est mieux confirmée. Tu n’inventes pas un délai standard : la formule aide à classer, puis la procédure locale fixe l’escalade et les délais."},{"type":"callout","content":"Erreurs fréquentes : confondre gravité et priorité ; mélanger dans une seule formule des échelles que personne n’a définies ; oublier que la certitude vient de la qualification ; traiter le calcul comme un pilote automatique ; annoncer un délai de réaction « standard » qui n’existe pas dans ton organisation."},{"type":"callout","content":"Sécurité : une priorisation ne t’autorise pas à accuser une personne ni à prendre seul une mesure lourde sur un service critique. Si une action coupe un accès ou touche des données personnelles, suis la procédure et garde une trace de la décision."},{"type":"callout","content":"À retenir : la gravité dit ce qui pourrait arriver. La priorité dit ce que tu traites maintenant. Dans ce parcours, la priorité se classe avec « gravité × criticité du bien × certitude ». Les échelles restent locales à l’organisation. L’escalade doit être courte, sourcée et prudente."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : trier une semaine d’alertes et rédiger le rapport d’analyse » : classe les alertes, justifie leur ordre de traitement, rédige une escalade claire, puis termine par le quiz."},{"type":"resource","content":"NIST SP 800-86 : intégrer l’investigation numérique à la réponse aux incidents (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/86/final"},{"type":"resource","content":"CNIL : guide de la sécurité des données personnelles","url":"https://www.cnil.fr/fr/guide-de-la-securite-des-donnees-personnelles-nouvelle-edition-2024"},{"type":"resource","content":"FIRST : le protocole TLP pour partager de l’information sensible (en anglais)","url":"https://www.first.org/tlp/"}]}'::jsonb, 22, 30, 2),
  ('515eb089-daaf-367f-a846-068c45986091', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '9bbc731c-3ce3-2024-c67b-c719856c68ac', 'Enrichir une alerte : réputation, WHOIS et sources de renseignement', 'Ajoute du contexte à une alerte avec prudence, désarme les indicateurs avant partage, puis utilise inventaire, WHOIS ou RDAP, RIPEstat et réputation sans exposer de données internes sensibles.', '{"blocks":[{"type":"callout","content":"Objectifs : choisir une source d’enrichissement adaptée, désarmer un indicateur, noter la source et la date d’une recherche, indiquer un niveau de confiance, interpréter prudemment un résultat contradictoire, et protéger la confidentialité des données internes."},{"type":"callout","content":"Prérequis : avoir compris le triage d’une alerte et savoir quels indicateurs doivent être protégés dans un rapport."},{"type":"callout","content":"Mise en situation : Fatou reçoit une alerte sur une adresse IP externe et un domaine peu connu. Son responsable veut un peu de contexte, mais sans envoyer un extrait de journal complet à un service tiers. Elle doit enrichir proprement, puis écrire ce qu’elle sait, ce qu’elle ignore, et ce qu’elle n’a pas le droit de publier."},{"type":"callout","content":"Vidéo à venir : Enrichir une alerte sans divulguer tes propres données"},{"type":"text","content":"L’enrichissement ajoute du contexte à un indicateur. Tu peux chercher un DNS inverse, un enregistrement WHOIS ou RDAP, une plage réseau dans RIPEstat, un historique de réputation dans un service comme VirusTotal ou URLhaus, ou simplement l’inventaire interne de ton organisation. WHOIS reste un service de consultation de données d’enregistrement. RDAP est son successeur structuré sur HTTP et JSON. Chaque source répond à une question différente. Aucune ne donne la vérité entière. Une adresse peut être partagée, dynamique, louée à un hébergeur légitime ou déjà réattribuée. Une mauvaise réputation aide à prioriser, mais ne prouve pas une attaque. L’absence de réputation ne prouve pas l’innocence non plus."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Sources d’enrichissement et leurs limites\",\"columns\":[\"Source\",\"Ce qu’elle apporte\",\"Limite principale\"],\"rows\":[[\"inventaire interne\",\"propriété, usage, criticité\",\"parfois incomplet\"],[\"DNS inverse\",\"nom parfois parlant\",\"souvent absent ou trompeur\"],[\"WHOIS ou RDAP\",\"données d’enregistrement\",\"pas toujours la machine réelle ni l’activité\"],[\"RIPEstat\",\"contexte IP, ASN, mesures réseau\",\"vue macro, pas l’intention\"],[\"VirusTotal\",\"analyses et réputation externes\",\"un verdict n’est pas une preuve ; ne pas soumettre un fichier sensible\"],[\"URLhaus\",\"URLs malveillantes recensées\",\"centré sur la diffusion de malwares ; absence ≠ innocence\"]]}"},{"type":"text","content":"Commence toujours par ce que tu contrôles. Un journal interne, un inventaire d’actifs, une CMDB ou l’historique d’un proxy sont souvent plus utiles qu’une recherche publique immédiate. Si tu sors de l’organisation, protège la confidentialité. Tu n’envoies jamais un fichier confidentiel, un extrait complet de journal, un jeton, un nom de machine interne ou un identifiant applicatif vers un service en ligne sans base légale, sans procédure et sans nécessité établie. Tu désarmes aussi les indicateurs dans tes notes : « hxxp://example[.]org » et « 192[.]0[.]2[.]77 » se partagent mieux qu’une URL directement cliquable."},{"type":"text","content":"Démonstration guidée : ici, on prépare seulement la partie locale et le rapport. Les étapes en ligne sont décrites, mais pas jouées avec des valeurs réelles internes. On transforme d’abord les indicateurs en forme non cliquable, puis on note ce que l’on cherchera : propriétaire du préfixe, DNS inverse éventuel, réputation, date de la recherche, outil utilisé et niveau de confiance. Les commandes ont été rejouées sur des indicateurs inventés."},{"type":"code","content":"# Désarmer une IP et une URL dans PowerShell\n$indicator = ''192.0.2.77''\n$url = ''http://login.example.org/reset?ticket=abc123''\n$indicator -replace ''\\\\.'', ''[.]''\n($url -replace ''^http'', ''hxxp'') -replace ''\\\\.'', ''[.]''\n# exemple de sortie (valeurs fictives)\n# 192[.]0[.]2[.]77\n# hxxp://login[.]example[.]org/reset?ticket=abc123\n\n# Même principe dans un terminal bash\nprintf ''%s\\n'' ''http://login.example.org/reset?ticket=abc123'' | sed -e ''s#^http#hxxp#'' -e ''s/\\./[.]/g''\n# exemple de sortie (valeurs fictives)\n# hxxp://login[.]example[.]org/reset?ticket=abc123","language":"powershell"},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Fiche d’enrichissement minimale\",\"items\":[{\"term\":\"indicateur\",\"text\":\"192[.]0[.]2[.]77\",\"tone\":\"blue\"},{\"term\":\"source\",\"text\":\"RIPEstat\",\"tone\":\"violet\"},{\"term\":\"date UTC\",\"text\":\"2026-03-14T09:20:00Z\",\"tone\":\"neutral\"},{\"term\":\"requête\",\"text\":\"prefix overview\",\"tone\":\"cyan\"},{\"term\":\"résultat\",\"text\":\"hébergeur mutualisé, à confirmer par l’inventaire\",\"tone\":\"amber\"},{\"term\":\"confiance\",\"text\":\"moyenne\",\"tone\":\"green\"},{\"term\":\"prudence\",\"text\":\"adresse potentiellement partagée\",\"tone\":\"red\"}]}"},{"type":"text","content":"Le TLP sert ensuite à partager le bon niveau d’information avec le bon public. En version 2.0, les libellés valides sont « TLP:CLEAR », « TLP:GREEN », « TLP:AMBER », « TLP:AMBER+STRICT » et « TLP:RED ». « TLP:CLEAR » peut être diffusé largement. « TLP:GREEN » reste dans la communauté prévue, sans publication ouverte. « TLP:AMBER » se limite au besoin d’en connaître dans l’organisation et ses clients. « TLP:AMBER+STRICT » restreint ce partage à l’organisation seule. « TLP:RED » reste limité aux destinataires individuels. Le label n’efface pas la prudence : tu partages seulement ce qui est nécessaire."},{"type":"example","content":"Exemple corrigé : le DNS inverse de « 192.0.2.77 » est vide, RIPEstat renvoie un hébergeur mutualisé, et l’inventaire interne dit qu’un prestataire approuvé utilise ce même hébergeur pour les mises à jour du portail. Un service de réputation de domaines signale en plus une observation ancienne, mais sans détail exploitable. La conclusion prudente n’est pas « indicateur malveillant », mais « hébergeur partagé, contexte externe insuffisant, confiance faible à moyenne, à recouper avec l’URL exacte, l’heure et le poste ayant lancé la connexion ». Trois enrichissements contradictoires appellent plus de contexte, pas une certitude forcée."},{"type":"callout","content":"Erreurs fréquentes : envoyer un extrait complet de journal à un service public ; traiter un résultat de réputation comme une preuve définitive ; oublier de noter la source, la date et le niveau de confiance d’un enrichissement ; publier une URL active dans un rapport partagé."},{"type":"callout","content":"Sécurité : les journaux réels peuvent contenir des données personnelles, des identifiants et parfois des secrets. Tu travailles d’abord avec des sources internes et tu sors seulement des indicateurs minimaux, désarmés, sur des services autorisés par ta procédure."},{"type":"callout","content":"À retenir : enrichir, c’est ajouter du contexte sans trahir la confidentialité. Commence par l’interne, désarme les indicateurs, note la source, la date et le niveau de confiance, puis accepte qu’un résultat externe reste souvent ambigu tant qu’il n’est pas recoupé."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 4 : corréler trois sources et dresser la chronologie » : enrichis seulement les indicateurs nécessaires, note leur origine, désarme ce que tu partages, puis termine par le quiz."},{"type":"resource","content":"CNIL : guide de la sécurité des données personnelles","url":"https://www.cnil.fr/fr/guide-de-la-securite-des-donnees-personnelles-nouvelle-edition-2024"},{"type":"resource","content":"RIPEstat : informations sur une adresse IP ou un réseau (en anglais)","url":"https://stat.ripe.net/"},{"type":"resource","content":"VirusTotal : analyser un fichier, une adresse ou un domaine (en anglais)","url":"https://www.virustotal.com/"},{"type":"resource","content":"FIRST : le protocole TLP pour partager de l’information sensible (en anglais)","url":"https://www.first.org/tlp/"}]}'::jsonb, 22, 30, 3),
  ('8484fe84-4638-d6ef-3566-93906fd80ffd', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '5dd6e48c-0126-4785-322d-289797dd3f4e', 'Centraliser les journaux : rsyslog, agents et transport sécurisé', 'Comprends pourquoi une copie distante change une enquête, quelles sources centraliser d’abord, et comment choisir entre syslog, agents et redirection Windows sans promettre un SIEM magique.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer pourquoi une copie distante protège mieux la preuve, distinguer « @ » et « @@ » dans « rsyslog », comparer WEF, « systemd-journal-remote » et les agents, dire ce qu’un collecteur fait ou ne fait pas, et estimer un besoin de stockage avec des hypothèses affichées."},{"type":"callout","content":"Prérequis : avoir suivi « Corréler plusieurs sources : clés communes, pivots et enrichissement » et « Automatiser l’analyse : des scripts reproductibles et vérifiables »."},{"type":"callout","content":"Mise en situation : Nadia reprend la sécurité de la coopérative Harmattan. Chaque machine garde encore ses journaux localement, ce qui oblige à se connecter partout quand une alerte arrive. Pire, si une machine compromise efface « auth.log » ou son journal Windows, l’équipe perd une partie de l’histoire. Nadia veut donc commencer simple : une copie distante, des horloges synchronisées, puis des recherches rejouables."},{"type":"callout","content":"Vidéo à venir : Centraliser sans construire une usine à gaz"},{"type":"text","content":"Centraliser des journaux consiste à envoyer une copie des événements vers un point de collecte distinct de la machine qui les produit. Le bénéfice principal n’est pas le confort, c’est la résilience de la preuve : si un poste ou un serveur est compromis, ses traces locales peuvent être tronquées, écrasées ou effacées, alors qu’une copie distante reçue presque en temps réel reste exploitable. Cela rend aussi la recherche plus réaliste : une seule requête sur le collecteur vaut mieux qu’une tournée manuelle sur vingt hôtes. Comme ces journaux contiennent souvent des adresses IP, des comptes et parfois des noms d’hôtes internes, tu les traites comme des données à protéger, pas comme un simple tas de texte."},{"type":"schema","content":"{\"v\":1,\"kind\":\"network\",\"title\":\"Quatre sources, quatre chemins vers la collecte\",\"cols\":5,\"rows\":4,\"nodes\":[{\"id\":\"linux\",\"label\":\"serveur Linux\",\"icon\":\"server\",\"col\":0,\"row\":0},{\"id\":\"fw\",\"label\":\"pare-feu\",\"icon\":\"firewall\",\"col\":0,\"row\":1,\"tone\":\"amber\"},{\"id\":\"dns\",\"label\":\"DNS\",\"icon\":\"server\",\"col\":0,\"row\":2},{\"id\":\"win\",\"label\":\"Windows\",\"icon\":\"pc\",\"col\":0,\"row\":3,\"tone\":\"blue\"},{\"id\":\"syslog\",\"label\":\"collecteur syslog\",\"icon\":\"server\",\"col\":2,\"row\":0,\"tone\":\"green\"},{\"id\":\"central\",\"label\":\"centralisation\",\"icon\":\"server\",\"col\":2,\"row\":1,\"tone\":\"green\"},{\"id\":\"siem\",\"label\":\"SIEM\",\"sub\":\"ou centralisation\",\"icon\":\"server\",\"col\":2,\"row\":2,\"tone\":\"violet\"},{\"id\":\"wec\",\"label\":\"abonnements WEC\",\"icon\":\"server\",\"col\":2,\"row\":3,\"tone\":\"blue\"},{\"id\":\"archives\",\"label\":\"archives\",\"icon\":\"archive\",\"col\":4,\"row\":0},{\"id\":\"recherches\",\"label\":\"recherches\",\"icon\":\"search\",\"col\":4,\"row\":1},{\"id\":\"alertes\",\"label\":\"alertes\",\"icon\":\"bell\",\"col\":4,\"row\":2,\"tone\":\"red\"},{\"id\":\"cas\",\"label\":\"cas\",\"icon\":\"briefcase\",\"col\":4,\"row\":3}],\"links\":[{\"from\":\"linux\",\"to\":\"syslog\",\"label\":\"@@\",\"arrow\":\"to\"},{\"from\":\"syslog\",\"to\":\"archives\",\"arrow\":\"to\"},{\"from\":\"fw\",\"to\":\"central\",\"label\":\"@@\",\"arrow\":\"to\"},{\"from\":\"central\",\"to\":\"recherches\",\"arrow\":\"to\"},{\"from\":\"dns\",\"to\":\"siem\",\"label\":\"agent\",\"arrow\":\"to\"},{\"from\":\"siem\",\"to\":\"alertes\",\"arrow\":\"to\"},{\"from\":\"win\",\"to\":\"wec\",\"label\":\"WEF\",\"arrow\":\"to\"},{\"from\":\"wec\",\"to\":\"cas\",\"arrow\":\"to\"}],\"caption\":\"`@` = UDP, simple mais muet si un message se perd. `@@` = TCP, plus fiable mais ne chiffre pas seul. TLS ajoute confidentialité et authentification du transport.\"}"},{"type":"text","content":"Tu ne centralises pas tout au hasard. Commence par ce qui sert vite pendant une enquête : authentification, pare-feu, DNS, mandataire, serveurs exposés au web, puis journaux Windows importants. Tant que les horloges ne sont pas alignées, le collecteur ne répare pas la chronologie : il ne fait qu’agréger des événements faux au même endroit. Sur Linux, « rsyslog » relaie très bien du syslog et peut aussi lire des fichiers texte via « imfile » ; « systemd-journal-remote » reçoit des événements « journald » sérialisés au format Journal Export, souvent via HTTPS, mais il ne collecte pas magiquement tous les journaux texte du système. Sur Windows, Windows Event Forwarding, souvent abrégé WEF, envoie des événements choisis vers un collecteur Windows Event Collector ; il reste passif vis-à-vis des journaux de la source et ne remplace pas un agent qui doit lire des fichiers applicatifs ou normaliser des champs non Windows."},{"type":"text","content":"Les composants de collecte ont chacun un rôle précis. L’agent Wazuh remonte surtout des événements d’hôte vers le serveur Wazuh pour analyse. Filebeat lit des fichiers, Winlogbeat lit les journaux d’événements Windows via les API Windows, et Fluent Bit est un agent de télémétrie léger qui peut aussi servir d’agrégateur. Aucun de ces composants ne « comprend l’incident » à ta place. Un collecteur simple copie et range ; un SIEM ou une pile de recherche ajoute l’indexation, les champs normalisés et les règles. Si les noms de champs changent d’une source à l’autre, la corrélation restera difficile même après centralisation."},{"type":"text","content":"Démonstration guidée : les extraits ci-dessous sont volontairement inventés pour l’apprentissage. Le premier montre un envoi « rsyslog » chiffré en TCP/TLS vers le port 6514, qui est le port enregistré par défaut pour syslog sur TLS. Le second montre un collecteur « rsyslog » qui écoute en TCP/TLS, lit aussi un fichier local via « imfile », puis range une copie par hôte et par programme. Lis chaque commentaire avant la ligne suivante : l’objectif est de comprendre la logique et les noms réels des paramètres RainerScript, pas de coller une configuration en production sans relecture des certificats et des chemins."},{"type":"code","content":"# Émetteur rsyslog fictif : envoi en TCP + TLS vers le collecteur\naction(\n  type=\"omfwd\"\n  target=\"logs.example.com\"\n  port=\"6514\"\n  protocol=\"tcp\"\n  StreamDriver=\"ossl\"\n  StreamDriverMode=\"1\"\n  StreamDriverAuthMode=\"x509/name\"\n  StreamDriverPermittedPeers=\"logs.example.com\"\n  queue.type=\"linkedList\"\n  Template=\"RSYSLOG_SyslogProtocol23Format\"\n)\n\n# Collecteur rsyslog fictif : réception TCP + TLS et fichier par machine\nmodule(load=\"imtcp\")\nmodule(load=\"imfile\")\ninput(type=\"imtcp\" port=\"6514\"\n      StreamDriver.Name=\"ossl\"\n      StreamDriver.Mode=\"1\"\n      StreamDriver.AuthMode=\"x509/name\"\n      streamDriver.CAFile=\"/etc/rsyslog.d/ca.pem\"\n      streamDriver.CertFile=\"/etc/rsyslog.d/collector-cert.pem\"\n      streamDriver.KeyFile=\"/etc/rsyslog.d/collector-key.pem\"\n      PermittedPeer=\"client.example.org\")\ninput(type=\"imfile\" File=\"/var/log/app-demo.log\" Tag=\"app-demo:\")\ntemplate(name=\"HostFile\" type=\"string\" string=\"/var/log/central/%HOSTNAME%/%PROGRAMNAME%.log\")\n*.* ?HostFile\n& stop","language":"text"},{"type":"text","content":"Le choix du transport change le niveau de confiance. UDP est léger, mais il peut perdre un message sans retour. TCP améliore la fiabilité du transport, mais ne protège ni le contenu ni l’identité du collecteur à lui seul. Pour cela, on ajoute TLS, défini pour syslog dans la RFC 5425. Côté Windows, WEF évite d’installer un agent partout quand on veut d’abord rediriger des événements bien choisis. Côté applications, un agent devient utile quand les journaux sont en JSON, dispersés ou trop nombreux pour des règles de fichiers simples. Dans tous les cas, le serveur central mérite un durcissement supplémentaire, car il devient une cible intéressante : qui le contrôle lit tout, et qui le casse brouille beaucoup d’enquêtes."},{"type":"code","content":"# Calcul Node.js testé ici : hypothèse sans compression\nnode calcul-stockage.cjs\n# exemple de sortie (valeurs fictives)\n# 20 machines x 18000 lignes/jour x 300 octets = 108000000 octets/jour\n# soit 103.00 MiB/jour et 3.02 GiB sur 30 jours sans compression","language":"bash"},{"type":"example","content":"Exemple corrigé : pour 20 machines qui produisent chacune 18 000 lignes par jour d’environ 300 octets, on obtient 108 000 000 octets par jour, soit 103,00 MiB par jour et 3,02 GiB sur 30 jours sans compression. Ce calcul ne donne pas « la bonne taille universelle » : il donne un premier ordre de grandeur qui t’aide à discuter disque, rotation et sauvegarde avant la saturation."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un collecteur corrige des horloges fausses ; envoyer « tout » sans priorité ni estimation de volume ; laisser le serveur central accessible comme un simple partage ; confondre TCP avec chiffrement alors que TLS reste un choix séparé."},{"type":"callout","content":"Sécurité : n’envoie que les journaux de ton organisation ou d’un système pour lequel tu as un mandat écrit. Les configurations montrées ici servent à comprendre la centralisation. Relis-les sur une machine de test avant toute mise en production, et n’envoie pas de journaux réels vers un service tiers sans nécessité ni contrôle de confidentialité."},{"type":"callout","content":"À retenir : centraliser, c’est protéger la preuve et gagner en visibilité. Commence par les sources les plus utiles, synchronise les horloges, choisis un transport adapté, puis protège fortement le collecteur. Un calcul simple de volume vaut mieux qu’une promesse vague de « stockage illimité »."},{"type":"callout","content":"Pour pratiquer : Le « Projet final : trier une semaine d’alertes et rédiger le rapport d’analyse » ne te demande pas de déployer un collecteur, mais cette leçon t’aide à comprendre pourquoi les preuves y sont déjà réunies au même endroit. Tu peux aussi relire dans ce projet quelles sources auraient dû être centralisées en premier. Termine par le quiz."},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"},{"type":"resource","content":"RFC 5425 : transport de syslog sur TLS (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc5425"},{"type":"resource","content":"Microsoft : la redirection d’événements Windows","url":"https://learn.microsoft.com/fr-fr/windows/security/threat-protection/use-windows-event-forwarding-to-assist-in-intrusion-detection"},{"type":"resource","content":"rsyslog : la documentation (en anglais)","url":"https://www.rsyslog.com/doc/"}]}'::jsonb, 24, 30, 1),
  ('09342c50-8429-00f3-2a4c-31ef4ee28f6a', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '5dd6e48c-0126-4785-322d-289797dd3f4e', 'Détection et recherche : Wazuh, Graylog Open, OpenSearch, Loki et Security Onion', 'Découvre ce qu’un SIEM fait vraiment, ce qu’il ne fera jamais à ta place, et comment choisir un outillage réaliste entre agents, recherche centralisée et surveillance réseau.', '{"blocks":[{"type":"callout","content":"Objectifs : décrire les briques d’un SIEM, résumer le rôle de Wazuh, Graylog Open, Elastic ou OpenSearch, Security Onion, OSSEC et Loki, rappeler qu’un produit gratuit n’est pas forcément libre, lire une règle Wazuh simple, et choisir un point de départ adapté à trois contextes différents."},{"type":"callout","content":"Prérequis : avoir suivi « Centraliser les journaux : rsyslog, agents et transport sécurisé » et savoir ce qu’est une règle de détection."},{"type":"callout","content":"Mise en situation : Mamadou entend trois demandes la même semaine. Atlas veut mieux surveiller ses postes Windows et Linux. L’association Teranga veut surtout un endroit unique pour lire ses journaux applicatifs et ses accès web. Une petite équipe réseau veut comprendre ce qui entre et sort autour de son pare-feu. Tous disent « il nous faut un SIEM », mais ce mot cache des besoins différents."},{"type":"callout","content":"Vidéo à venir : Choisir un outillage réaliste sans se raconter d’histoire"},{"type":"text","content":"Un SIEM, c’est d’abord une chaîne : collecte, normalisation, stockage, recherche, règles, alertes, tableaux de bord, puis suivi du cas. Ce n’est pas une boîte magique qui transforme du bruit en vérité sans réglage. Si les sources sont incomplètes, si les horloges divergent ou si les règles alertent sur tout, le SIEM reproduit ces défauts à grande vitesse. Son intérêt est ailleurs : il met des journaux de formats différents dans une même grammaire de recherche et il garde l’historique assez longtemps pour comparer, pivoter et documenter."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Chaîne minimale d’un SIEM\",\"items\":[{\"title\":\"Collecte\",\"text\":\"les événements arrivent depuis les sources\"},{\"title\":\"Décodeurs\",\"text\":\"le format brut est compris\"},{\"title\":\"Champs normalisés\",\"text\":\"les mêmes idées portent les mêmes noms\"},{\"title\":\"Index et recherche\",\"text\":\"l’historique devient consultable\"},{\"title\":\"Règles\",\"text\":\"des seuils et conditions sont évalués\"},{\"title\":\"Alertes\",\"text\":\"les signaux utiles remontent\"},{\"title\":\"Qualification et cas\",\"text\":\"un analyste confirme puis documente\"}],\"caption\":\"Sans collecte fiable : pas de preuve. Sans normalisation : pas de corrélation. Sans réglage : trop de faux positifs. Sans analyste : pas de conclusion défendable.\"}"},{"type":"text","content":"Les outils de centralisation et de détection ne couvrent pas exactement le même terrain. Wazuh est centré sur les agents, les journaux d’hôte, les règles et les décodeurs. Graylog Open couvre le cœur de la gestion centralisée de journaux, et les éditions payantes ajoutent d’autres fonctions. OpenSearch est une suite de recherche et d’analytique open source ; les distributions récentes d’Elastic suivent une licence distincte. Security Onion vise davantage la surveillance réseau avec Suricata, Zeek, la capture de paquets et une console d’analyse orientée chasse, tout en pouvant aussi ingérer de la visibilité hôte. OSSEC est plus ancien, historiquement centré HIDS et corrélation. Grafana Loki convient bien à des journaux applicatifs et à des métadonnées légères : il indexe surtout des labels, pas le contenu complet des lignes, donc ce n’est pas un SIEM complet à lui seul."},{"type":"text","content":"Démonstration guidée : lis cette règle Wazuh inventée comme un petit formulaire logique. Elle n’a pas été exécutée ici. Son intérêt pédagogique est de te montrer comment un moteur compare des champs déjà décodés, assigne un niveau et ajoute une description lisible. Commence par le groupe, puis la condition principale, puis la description finale."},{"type":"code","content":"<group name=\"web,attack\">\n  <rule id=\"100200\" level=\"10\" frequency=\"6\" timeframe=\"120\">\n    <if_group>nginx</if_group>\n    <field name=\"status\">401</field>\n    <same_srcip />\n    <description>Six réponses 401 depuis la même adresse en deux minutes</description>\n  </rule>\n</group>","language":"xml"},{"type":"text","content":"Tu peux résumer cette règle ainsi : « si un journal déjà classé comme nginx contient six réponses 401 depuis la même adresse en 120 secondes, crée une alerte de niveau 10 ». La logique ressemble à celle d’une règle Sigma, mais avec une syntaxe propre à Wazuh. Ce qui compte pour le débutant, ce n’est pas de mémoriser la balise exacte : c’est de voir qu’une détection repose sur des champs normalisés, un seuil, une fenêtre de temps et une description testable. Les licences et l’emballage commercial de certains projets évoluent : pour un choix réel, consulte toujours la licence en vigueur et la documentation officielle du moment. Si tu compares avec une édition gratuite d’un outil commercial, vérifie aussi ses limites de volume, de fonctions et de durée : « gratuit » ne veut ni dire « libre », ni dire « adapté »."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Choisir un point de départ crédible\",\"columns\":[\"Besoin principal\",\"Point de départ crédible\"],\"rows\":[[\"postes et serveurs, agents, règles\",\"Wazuh\"],[\"journaux texte centralisés, pipelines\",\"Graylog\"],[\"fort volume, recherche et tableaux\",\"Elastic ou OpenSearch\"],[\"surveillance réseau et IDS\",\"Security Onion\"],[\"journaux applicatifs légers\",\"Loki\"]],\"highlight\":1}"},{"type":"example","content":"Exemple corrigé : pour l’association Teranga, qui a peu de moyens et veut d’abord relire des accès web, un serveur « rsyslog » central puis Graylog peut suffire. Pour Atlas, qui veut suivre des postes Windows et Linux avec des règles d’hôte, Wazuh est un meilleur premier choix. Pour une équipe qui a un port miroir, des pare-feu et un besoin de visibilité réseau, Security Onion devient plus cohérent. Le bon outil n’est donc pas « le plus célèbre », mais celui qui répond au besoin dominant sans faire exploser la charge d’exploitation."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un SIEM remplace le triage ; choisir sur le logo ou la mode plutôt que sur les sources disponibles ; vouloir tout indexer avant d’avoir une question claire ; oublier qu’un agent, un pipeline ou un décodeur est aussi un composant à maintenir."},{"type":"callout","content":"Sécurité : déploie ces outils sur des systèmes que ton organisation t’autorise à administrer. Un SIEM centralise des données sensibles : comptes, adresses IP, noms d’hôtes, parfois commandes. Restreins l’accès, documente les habilitations et n’enrichis pas tes journaux avec un service en ligne si cela expose des données internes."},{"type":"callout","content":"À retenir : un SIEM est une chaîne de traitement, pas une baguette magique. Commence petit, avec des sources fiables et un besoin clair. Wazuh, Graylog Open, OpenSearch, les distributions Elastic, Security Onion, OSSEC et Loki répondent à des priorités différentes, même s’ils partagent des principes communs de collecte, recherche et détection."},{"type":"callout","content":"Pour pratiquer : Le « Projet final : trier une semaine d’alertes et rédiger le rapport d’analyse » ne te demande pas d’installer un SIEM, mais il te montre ce qu’un bon outillage doit rendre facile : retrouver, filtrer, regrouper et documenter. Utilise cette leçon pour expliquer quel point de départ serait crédible dans ton contexte, puis termine par le quiz."},{"type":"resource","content":"Wazuh : la documentation (en anglais)","url":"https://documentation.wazuh.com/current/index.html"},{"type":"resource","content":"Graylog : la documentation (en anglais)","url":"https://go2docs.graylog.org/current/home.htm"},{"type":"resource","content":"OpenSearch : la documentation (en anglais)","url":"https://opensearch.org/docs/latest/"},{"type":"resource","content":"Grafana Loki : la documentation (en anglais)","url":"https://grafana.com/docs/loki/latest/"}]}'::jsonb, 24, 30, 2),
  ('d601e4ef-ef50-dbda-d6c8-9a8086da400f', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '5dd6e48c-0126-4785-322d-289797dd3f4e', 'Conserver et protéger les journaux : rétention, intégrité et vie privée', 'Apprends à fixer une rétention proportionnée, à protéger l’intégrité des archives et à traiter les journaux comme des données personnelles sensibles plutôt que comme de simples fichiers techniques.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer base active, archivage intermédiaire et archivage définitif, citer le repère CNIL de six mois à un an pour les traces quand il s’applique, vérifier une archive avec « sha256sum », expliquer la proportionnalité de la conservation, et décrire qui doit pouvoir lire ou effacer un journal."},{"type":"callout","content":"Prérequis : avoir suivi « Centraliser les journaux : rsyslog, agents et transport sécurisé » et savoir lire une empreinte SHA-256."},{"type":"callout","content":"Mise en situation : Awa a réussi à centraliser quelques journaux pour Cabinet Moussa. Très vite, une question plus difficile arrive : combien de temps les garder, qui peut y accéder, et comment prouver qu’une archive n’a pas été modifiée entre deux revues ? En même temps, l’équipe RH rappelle que les traces peuvent concerner des salariés. Awa doit donc penser à la fois enquête, coût, confidentialité et intégrité."},{"type":"callout","content":"Vidéo à venir : Rétention, intégrité et vie privée des journaux"},{"type":"text","content":"Conserver un journal ne veut pas dire « garder tout pour toujours ». La CNIL rappelle que la durée dépend de la finalité du traitement, des obligations éventuelles et du besoin de contentieux ou d’analyse post-incident. Elle distingue la base active, l’archivage intermédiaire et, dans certains cas, l’archivage définitif. Pour les événements journalisés à des fins de sécurité, la CNIL recommande une période glissante comprise entre six mois et un an, sauf obligation ou besoin documenté plus long. Ce repère n’est pas une excuse pour copier aveuglément une durée : il faut documenter pourquoi on garde, qui relit, et quand on supprime ou on isole. Si ton activité est soumise à une obligation sectorielle précise, vérifie ce texte officiel à part au lieu d’étendre mécaniquement la règle CNIL à tous les journaux."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Trois phases de conservation\",\"columns\":[\"Phase\",\"Usage principal\"],\"rows\":[[\"base active\",\"exploitation quotidienne, recherche rapide\"],[\"archivage intermédiaire\",\"dossiers clos, contentieux, accès ponctuel\"],[\"archivage définitif\",\"valeur historique ou légale particulière\"]],\"caption\":\"Questions à noter : pourquoi ? qui accède ? quand supprime-t-on ?\"}"},{"type":"text","content":"Les journaux contiennent souvent des données personnelles : adresses IP, comptes, adresses électroniques, parfois commandes ou noms de fichiers. Le RGPD impose donc de définir une finalité, de limiter les données et la durée, de sécuriser le traitement et d’informer les personnes quand c’est requis. Quand il s’agit de surveiller des salariés, la proportionnalité et l’information préalable comptent particulièrement. Il ne s’agit pas d’espionner pour « tout savoir », mais de tracer ce qui est nécessaire pour détecter un incident, comprendre une action sensible et démontrer la conformité. On n’enregistre ni mot de passe ni jeton complet, et on ne publie pas un journal réel dans un forum ou un service tiers."},{"type":"text","content":"L’intégrité répond à une autre question : comment savoir que l’archive de mardi soir est bien celle que tu as conservée ? Plusieurs gestes se complètent : restreindre les droits en écriture, conserver une copie distante, limiter les personnes capables d’effacer, séparer les rôles, et calculer des empreintes sur les archives. Une empreinte ne protège pas seule contre l’effacement, mais elle révèle une modification. La rotation, la compression et la restauration testée comptent aussi : une archive qu’on ne peut plus ouvrir au moment critique est une fausse sécurité."},{"type":"text","content":"Démonstration guidée : la séquence ci-dessous a été testée dans Git Bash sur un fichier temporaire. Elle archive un petit journal, calcule son empreinte, vérifie l’empreinte, modifie un octet, puis constate l’échec de la vérification. Lis bien le résultat final : ce n’est pas le contenu du journal qui est inspecté, c’est l’intégrité de l’archive."},{"type":"code","content":"printf ''%s\\n'' ''2026-03-10T08:15:00Z auth failed password for awa from 192.0.2.25'' > journal.log\ntar -czf journal.tar.gz journal.log\nsha256sum journal.tar.gz > SHA256SUMS\nsha256sum -c SHA256SUMS\nprintf ''X'' | dd of=journal.tar.gz bs=1 seek=12 count=1 conv=notrunc status=none\nsha256sum -c SHA256SUMS\n\n# sortie observée\njournal.tar.gz: OK\njournal.tar.gz: FAILED\nsha256sum: WARNING: 1 computed checksum did NOT match","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"relations\",\"title\":\"Qui peut lire, effacer et archiver ?\",\"pairs\":[{\"from\":\"Lecture des journaux\",\"label\":\"réservée à\",\"to\":\"analystes et admins habilités\",\"tone\":\"green\",\"icon\":\"users\"},{\"from\":\"Effacement des journaux\",\"label\":\"doit rester\",\"to\":\"très limité, avec trace et justification\",\"tone\":\"red\",\"icon\":\"lock\"},{\"from\":\"Archivage\",\"label\":\"sur\",\"to\":\"support séparé ou accès logique restreint\",\"tone\":\"blue\",\"icon\":\"archive\"},{\"from\":\"Restauration testée\",\"label\":\"doit être\",\"to\":\"oui, sinon conservation fictive\",\"tone\":\"amber\",\"icon\":\"check\"}]}"},{"type":"example","content":"Exemple corrigé : pour Baobab Tech, une politique de départ crédible peut tenir en trois lignes. « Les traces d’authentification et d’administration suivent une durée proportionnée à la finalité ; pour les événements journalisés à des fins de sécurité, le repère CNIL de six mois à un an sert de base, sauf obligation ou besoin documenté plus long. Les archives intermédiaires sont séparées de la base active et accessibles seulement aux personnes habilitées. Les empreintes SHA-256 des archives sont vérifiées avant toute exploitation. » Cette politique ne remplace pas un texte sectoriel, mais elle montre déjà finalité, accès et intégrité."},{"type":"callout","content":"Erreurs fréquentes : choisir une durée « parce que tout le monde fait pareil » ; laisser la même personne lire, effacer et archiver seule ; croire qu’une compression suffit comme protection ; conserver des données sensibles dans les journaux alors qu’elles n’aident pas l’enquête."},{"type":"callout","content":"Sécurité : les journaux réels de ton organisation sont sensibles. N’envoie pas leur contenu complet à un service en ligne sans nécessité, et n’utilise jamais des traces d’un tiers sans mandat écrit. Les tests d’archive et d’empreinte se refont sur des fichiers de démonstration, sous Git Bash, WSL, Termux ou une machine virtuelle."},{"type":"callout","content":"À retenir : une bonne conservation est proportionnée, documentée et protégée. Tu gardes ce qui sert à l’enquête et à la conformité, pas plus. Tu sépares les accès, tu archives proprement, tu vérifies l’intégrité et tu testes la restauration avant le jour où l’incident arrive."},{"type":"callout","content":"Pour pratiquer : Le « Projet final : trier une semaine d’alertes et rédiger le rapport d’analyse » te montre des preuves déjà conservées. Utilise cette leçon pour juger si la politique derrière ces traces semble crédible, puis complète avec ce que tu changerais pour mieux protéger leur intégrité. Termine par le quiz."},{"type":"resource","content":"CNIL : sécurité, tracer les opérations","url":"https://www.cnil.fr/fr/securite-tracer-les-operations"},{"type":"resource","content":"CNIL : les durées de conservation des données","url":"https://www.cnil.fr/fr/passer-laction/les-durees-de-conservation-des-donnees"},{"type":"resource","content":"CNIL : sécurité, archiver de manière sécurisée","url":"https://www.cnil.fr/fr/securite-archiver-de-maniere-securisee"},{"type":"resource","content":"ANSSI : recommandations pour la mise en œuvre d’un système de journalisation","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-pour-la-mise-en-oeuvre-dun-systeme-de-journalisation"}]}'::jsonb, 24, 30, 3),
  ('9564cd85-5229-a1c9-d025-cc8cd2231543', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', 'Préserver les preuves et rédiger le rapport d’investigation', 'Apprends à travailler sur une copie, à noter une chaîne de conservation claire, puis à transformer une chronologie technique en rapport défendable pour la direction et pour les techniciens.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer l’ordre de volatilité, distinguer l’original de la copie de travail, noter une chaîne de conservation minimale, structurer un rapport d’investigation, reformuler une conclusion trop affirmative en constat défendable, et rester prudent sur l’attribution."},{"type":"callout","content":"Prérequis : avoir suivi « Qualifier une alerte et documenter la suite » et « Reconstituer la chronologie d’un incident »."},{"type":"callout","content":"Mise en situation : Koffi termine une investigation pour Sahel Services. Il a une chronologie, plusieurs extraits de journaux et une liste d’actions urgentes, mais son responsable lui demande un rapport qui puisse être relu demain par la direction, puis repris la semaine suivante par un technicien. Koffi doit donc protéger ses preuves et écrire sans confondre ce qu’il sait, ce qu’il suppose et ce qu’il n’a pas encore vérifié."},{"type":"callout","content":"Vidéo à venir : De la preuve fragile au rapport défendable"},{"type":"text","content":"Quand un incident démarre, toutes les preuves n’ont pas la même fragilité. La RFC 3227 rappelle un ordre de volatilité : certaines informations disparaissent vite, d’autres restent plus longtemps. Cela pousse à réfléchir avant d’agir. Redémarrer une machine, tuer un processus ou lancer un nettoyage peut détruire des éléments utiles à l’étape suivante. En pratique, l’analyse de journaux s’appuie souvent sur des traces déjà écrites, mais elle doit quand même respecter la même discipline : copie de travail, notes datées en UTC, empreinte avant et après, et capacité à expliquer comment la preuve a été trouvée, manipulée, stockée et transférée."},{"type":"schema","content":"{\"v\":1,\"kind\":\"layers\",\"title\":\"Ordre de volatilité des preuves\",\"side\":\"du plus volatil au moins volatil\",\"layers\":[{\"label\":\"Registres et caches\",\"icon\":\"chip\",\"tone\":\"red\"},{\"label\":\"Routage, ARP, processus, mémoire\",\"icon\":\"activity\",\"tone\":\"amber\"},{\"label\":\"Fichiers temporaires\",\"icon\":\"file\",\"tone\":\"amber\"},{\"label\":\"Disque local\",\"icon\":\"database\",\"tone\":\"green\"},{\"label\":\"Journaux distants\",\"icon\":\"server\",\"tone\":\"blue\"},{\"label\":\"Config physique et topologie\",\"icon\":\"network\",\"tone\":\"violet\"},{\"label\":\"Archives\",\"icon\":\"archive\",\"tone\":\"neutral\"}]}"},{"type":"text","content":"La bonne habitude est simple à dire et facile à oublier : on travaille sur une copie. L’original reste préservé autant que possible, la copie reçoit les extractions, les tris et les hypothèses. Chaque commande rejouable, chaque empreinte calculée et chaque changement d’état doivent être notés en UTC. Une chaîne de conservation minimale documente au moins où, quand et par qui la preuve a été découverte et collectée, où et par qui elle a été manipulée, qui en a eu la garde, comment elle a été stockée et comment les transferts ont eu lieu. Cette discipline ne sert pas seulement à « faire joli » : elle permet à un collègue de refaire ton analyse, et elle t’évite de prétendre qu’une modification vient de l’attaquant alors qu’elle a été causée par ton propre geste de collecte."},{"type":"text","content":"Démonstration guidée : pars de cinq lignes de chronologie, puis transforme-les en trois paragraphes lisibles. Le premier paragraphe résume l’accès initial et la persistance. Le deuxième décrit l’impact observé. Le troisième sépare les recommandations immédiates du niveau de certitude. Tu écris pour deux lecteurs à la fois : la direction, qui veut comprendre l’essentiel, et le technicien, qui doit pouvoir refaire les vérifications."},{"type":"code","content":"2026-03-10T08:15:00Z web   401 repetes sur /admin depuis 192.0.2.25\n2026-03-10T08:16:12Z web   302 sur /admin/login depuis 192.0.2.25\n2026-03-10T08:18:40Z app   creation du compte support-temp\n2026-03-10T08:23:05Z ssh   connexion reussie du compte support-temp\n2026-03-10T08:31:44Z proxy 95 Mo envoyes vers hxxps://sync[.]example","language":"text"},{"type":"text","content":"Il n’existe pas un plan unique imposé à tous les rapports d’incident, mais une structure simple et défendable aide à ne pas mélanger les faits, l’analyse et les recommandations."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Plan simple d’un rapport d’investigation\",\"items\":[{\"title\":\"1. Résumé dirigeant\",\"text\":\"quoi, quand, impact, état\"},{\"title\":\"2. Périmètre et sources\",\"text\":\"journaux, machines, limites\"},{\"title\":\"3. Chronologie UTC\",\"text\":\"faits et preuves\"},{\"title\":\"4. Analyse\",\"text\":\"techniques observées, certitude, doutes\"},{\"title\":\"5. Actions menées\",\"text\":\"recommandations priorisées\"},{\"title\":\"6. Annexes\",\"text\":\"indicateurs désarmés, commandes, empreintes\"}]}"},{"type":"text","content":"Le rapport distingue trois niveaux : certain, probable, non vérifié. « Certain » correspond à un fait observé directement, par exemple un compte créé dans un journal applicatif. « Probable » signifie qu’un faisceau d’indices concorde, sans preuve directe absolue. « Non vérifié » reste une piste à documenter, pas une phrase spectaculaire à glisser dans le résumé. Tu peux relier tes constats à ATT&CK pour parler d’une technique observée, mais sans transformer cette taxonomie en verdict juridique. Une adresse IP, un fuseau horaire ou une langue dans un fichier ne suffisent pas à attribuer une intrusion à une personne, un groupe ou un pays. Si des données personnelles sont concernées, la notification suit les règles décrites par la CNIL : tu renvoies à la page officielle au lieu d’inventer un délai ou une obligation que tu n’as pas relue."},{"type":"example","content":"Exemple corrigé : remplace « l’attaquant a forcément volé la base complète » par « un transfert sortant de 95 Mo a été observé à 08:31:44 UTC via le mandataire. Ce volume est cohérent avec une exfiltration, mais la nature exacte des données transférées n’est pas confirmée à ce stade ». La seconde phrase est moins spectaculaire, mais elle protège ton rapport : elle distingue le fait, l’hypothèse et la limite actuelle."},{"type":"callout","content":"Erreurs fréquentes : mélanger les faits et les hypothèses dans la même phrase ; travailler directement sur l’original ; oublier le fuseau horaire dans les notes ; remplir le résumé de détails techniques au lieu de commencer par l’impact et l’état."},{"type":"callout","content":"Sécurité : l’investigation se fait sur les systèmes de ton organisation ou d’un client avec autorisation écrite. Ne modifie pas un système compromis sans décision réfléchie, et ne partage dans un rapport que les indicateurs nécessaires, idéalement sous forme désarmée comme « hxxp » ou « 192[.]0[.]2[.]25 »."},{"type":"callout","content":"À retenir : préserver la preuve, c’est d’abord éviter de la détruire soi-même. Un bon rapport part d’une chronologie en UTC, cite ses preuves, annonce ses limites et parle clairement à la fois aux décideurs et aux techniciens. Une conclusion prudente mais sourcée vaut mieux qu’une certitude spectaculaire et fragile."},{"type":"callout","content":"Pour pratiquer : Travaille le « Projet final : trier une semaine d’alertes et rédiger le rapport d’analyse », puis compare ta structure à celle de « Investigation SOC : reconstituer une intrusion complète ». Le premier t’entraîne au rapport, le second à la chronologie détaillée. Termine ensuite par le quiz."},{"type":"resource","content":"RFC 3227 : recommandations pour la collecte et l’archivage des preuves (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc3227"},{"type":"resource","content":"NIST SP 800-86 : intégrer l’investigation numérique à la réponse aux incidents (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/86/final"},{"type":"resource","content":"MITRE ATT&CK : la base de connaissances des techniques d’attaque (en anglais)","url":"https://attack.mitre.org/"},{"type":"resource","content":"CNIL : les violations de données personnelles, les règles à suivre","url":"https://www.cnil.fr/fr/violations-de-donnees-personnelles-les-regles-suivre"}]}'::jsonb, 24, 30, 4)
