  ('12d45e53-0fb6-9959-eacd-81f129e8b17e', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '8dfef90e-761f-7bcb-6d62-86dc99d68558', '84370fe4-45d9-8475-3d27-b189a6cfa86e', 'Quiz : écrire une règle de détection', 70, 2),
