  ('04a35407-2abc-a4e8-c613-07c6d2ab3f71', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '9bbc731c-3ce3-2024-c67b-c719856c68ac', '2a9d1cf9-c38f-80f9-0202-6a143b8f32ff', 'Quiz : gravité, priorité et escalade', 70, 2),
