insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'tp-logs-formats-temps', 'TP 1 : lire, normaliser et dater des journaux de formats différents', 'Tu lis cinq formats de journaux de la même matinée, tu remets les heures en UTC et tu compares ensuite des comptes, des chemins, des codes et des volumes sans supposer que tous les fichiers racontent les choses de la même façon.', 'securite', 'debutant', 130, array['Reconnaître rapidement plusieurs formats de journaux', 'Convertir une heure locale en UTC avant de comparer deux sources', 'Compter, filtrer et regrouper des lignes sans perdre le contexte', 'Croiser un identifiant de requête ou un indicateur simple entre deux fichiers']::text[], array['Commence par noter le format d’horodatage et le fuseau de chaque fichier.', 'Pour un maximum, compte d’abord puis vérifie qu’il n’y a pas d’ex æquo.', 'Dans nginx, le code HTTP et le chemin se lisent dans la même ligne mais pas dans la même zone.', 'Un identifiant de requête te permet de comparer deux journaux qui n’utilisent pas le même format.']::text[], '{}'::text[], 700, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le mardi 19 mai 2026, Kader Sow veut montrer comment des journaux qui parlent de la même matinée peuvent utiliser des horodatages et des structures très différents. Il exporte un syslog traditionnel, un journal applicatif JSON lignes, un export de proxy, un accès web nginx et quelques lignes RFC 5424. Ton rôle est d’aligner les heures en UTC, de reconnaître les champs utiles et de répondre à des questions précises sans te fier à ton intuition. Les événements sont fictifs, mais leurs formats restent réalistes. Tout ce dont tu as besoin est dans les fichiers fournis et dans le guide.', array['Tu travailles sur des exports figés et fictifs.', 'Le syslog traditionnel du TP 1 est écrit en UTC+01:00, alors que les autres sources sont déjà en UTC.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, awk, sort et uniq', 'PowerShell 5.1 si tu es sur Windows']::text[], false, false, 40),
  ('81000621-4e50-9c2c-adf2-2ef3713c4ca5', 'tp-logs-windows', 'TP 2 : journaux Windows : sessions, comptes et PowerShell', 'Tu relies un export de sécurité Windows, des événements Sysmon et des journaux PowerShell pour retrouver un enchaînement de sessions, de comptes et de processus sans confondre activité légitime et activité suspecte.', 'securite', 'intermediaire', 150, array['Lire les champs essentiels d’un export de sécurité Windows', 'Relier un processus Sysmon à sa résolution DNS et à sa connexion réseau', 'Identifier un compte créé, un groupe modifié et un verrouillage de compte', 'Remettre plusieurs événements dans leur ordre chronologique plausible']::text[], array['Ne commence pas par les messages : regarde d’abord EventId, heure, poste et compte cible.', 'Pour un type de session, décide si tu dois compter, lister ou seulement prendre le maximum.', 'Un ProcessGuid aide à suivre le même processus entre plusieurs événements Sysmon.', 'Une commande encodée en PowerShell se décode avant de s’interpréter.']::text[], '{}'::text[], 710, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le jeudi 21 mai 2026, la direction de l’Hôtel Palmier d’Or s’inquiète d’ouvertures de session inhabituelles sur « pc-compta01 » et « pc-reception01 ». Kader Sow exporte alors le journal de sécurité au format CSV, des événements Sysmon et le journal PowerShell en JSON lignes. Tu dois reconstruire l’ordre des faits utiles, distinguer les connexions normales des épreuves plus suspectes et vérifier ce qu’une commande encodée essayait de joindre. Les journaux restent fictifs, mais leurs champs suivent de près les formats réels. Toutes les réponses se trouvent dans les fichiers et dans le guide.', array['Tu travailles uniquement sur des exports déjà fournis.', 'La commande encodée du TP 2 ne fait que joindre un domaine fictif en « .example ».']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour trier et compter', 'PowerShell 5.1 pour les variantes Windows et le décodage Base64 UTF-16LE']::text[], false, false, 50),
  ('108c6b74-381d-0d8b-13d2-3b360c41fdb8', 'tp-logs-reseau', 'TP 3 : pare-feu, DNS et proxy : trouver la machine qui balise', 'Tu relies un journal de pare-feu, un journal DNS et un journal de proxy pour distinguer un scan externe, une mise à jour légitime et une machine interne qui balise de façon très régulière.', 'securite', 'intermediaire', 150, array['Lire un journal de pare-feu et reconnaître un balayage de ports', 'Repérer un balisage en calculant des intervalles', 'Interpréter des réponses DNS « NXDOMAIN » et des requêtes TXT', 'Utiliser le proxy pour mesurer un volume ou un nombre de refus']::text[], array['Une seule source qui essaie beaucoup de ports différents sur peu de temps ressemble à un scan.', 'Pour un balisage, le rythme compte autant que le domaine ou le client.', 'Dans le proxy Squid, les octets ne sont pas au même endroit que l’URL ou le code HTTP.', 'Ne confonds pas une mise à jour lourde mais régulière avec une petite communication répétitive.']::text[], '{}'::text[], 720, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le vendredi 22 mai 2026, la supervision remarque un volume sortant inhabituel depuis le réseau des bureaux de l’Hôtel Palmier d’Or. Kader Sow exporte alors le journal du pare-feu, celui du résolveur DNS et l’access log du proxy Squid pour tout l’après-midi. Tu dois identifier la source du scan externe, la machine interne qui balise régulièrement, le domaine qui génère le plus d’erreurs DNS et le client qui accumule les refus du proxy. Les données sont fictives, mais les formats suivent de près des journaux réels. Aucune sonde ni SIEM n’est nécessaire : tout se résout avec les trois fichiers et le guide.', array['Tu analyses seulement des exports textuels déjà capturés.', 'Le TP 3 contient à la fois du bruit légitime et des activités qui se ressemblent : ne conclus pas avant d’avoir compté.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, awk, sort et uniq', 'PowerShell 5.1 pour filtrer et sommer sous Windows']::text[], false, false, 50),
  ('58886b77-40ab-af65-885e-cb7d5979bc64', 'tp-logs-correlation', 'TP 4 : corréler trois sources et dresser la chronologie', 'Tu relies le journal d’authentification, le journal web, le proxy et les baux DHCP pour attribuer une adresse à une machine, corriger un décalage d’horloge et reconstituer une modification frauduleuse.', 'securite', 'intermediaire', 145, array['Attribuer une adresse IP à la bonne machine au bon instant', 'Corriger un décalage d’horloge en comparant deux traces du même fait', 'Relier une action web, une modification et une connexion SSH en une seule chronologie UTC', 'Justifier une conclusion sans te laisser tromper par un ancien bail ou par le bruit normal']::text[], array['Choisis d’abord un événement rare visible dans deux journaux pour mesurer le décalage du proxy.', 'Un ancien détenteur d’adresse n’est pas une preuve si le bail a déjà expiré au moment du fait.', 'La chronologie doit être triée en UTC avant toute comparaison entre accès, proxy et auth.', 'La dernière preuve d’activité n’est pas forcément dans le même journal que la première.']::text[], '{}'::text[], 730, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le samedi 23 mai 2026, une réservation a été modifiée alors qu’aucun client n’avait demandé ce changement. Kader Sow a exporté les journaux de srv-reservation01, le proxy des bureaux, les baux DHCP et un modèle de chronologie. Tu dois convertir les heures en UTC, mesurer le décalage du proxy, rattacher l’adresse source à la bonne machine au bon instant puis reconstituer la suite web puis SSH. Le bruit est volontaire : plusieurs postes consultent l’application, des scans SSH publics existent déjà, et une adresse interne a changé de machine en cours de matinée. Chaque réponse doit s’appuyer sur les fichiers fournis et sur les règles du guide, pas sur une intuition.', array['Tu travailles uniquement sur des exports fictifs fournis par le labo, sans SIEM et sans accès à un vrai serveur.', 'Pour les baux DHCP, applique la règle écrite dans le guide : début inclus et fin exclue.']::text[], array['Visionneuse CyberPingo pour filtrer les lignes', 'Git Bash, WSL ou Termux pour grep, awk et sort', 'Windows PowerShell 5.1 si tu préfères Select-String et Import-Csv']::text[], false, false, 55),
  ('7dff56d8-fe55-a57b-0128-84821681fa92', 'tp-logs-detection', 'TP 5 : règles de détection : seuils, fenêtres et faux positifs', 'Tu appliques trois règles de détection à un journal d’authentification applicative, comptes VP, FP et FN, ajustes un seuil et mesures l’effet d’une exclusion.', 'securite', 'intermediaire', 145, array['Appliquer une fenêtre glissante définie sans ambiguïté', 'Mesurer VP, FP et FN sur la ligne déclencheuse de chaque alerte', 'Comparer trois règles par précision, rappel et score F1', 'Vérifier l’effet d’un seuil ou d’une exclusion avant de la recommander']::text[], array['Une alerte est attachée à la ligne d’échec qui fait franchir le seuil, pas à toute la série.', 'Lis bien le regroupement de chaque règle avant de compter sa fenêtre.', 'Un faux négatif est ici une ligne d’attaque non alertée, pas une adresse entière.', 'Une exclusion peut baisser le bruit, mais elle peut aussi enlever de vrais positifs.']::text[], '{}'::text[], 740, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le lundi 25 mai 2026, Kader Sow veut automatiser la détection de la force brute sur la page de connexion de l’application de réservation. Il fournit un journal CSV des événements d’authentification, déjà horodatés en UTC, avec une étiquette de vérité sur chaque ligne, ainsi qu’un document de règles candidates. Tu dois appliquer exactement la fenêtre, le regroupement et les exclusions écrits dans les fichiers, puis mesurer la précision, le rappel et le compromis obtenu. Le jeu de données contient du bruit utile : utilisateurs distraits, comptes de service bruyants, vérification connue et attaques de rythmes différents. Tu ne dois rien deviner hors des fichiers : toutes les formules et conventions d’arrondi sont données.', array['Tu calcules VP, FP, FN, précision, rappel et F1 uniquement avec les définitions écrites dans les fichiers du labo.', 'Les règles ne regardent que les lignes dont la colonne Result vaut failure.']::text[], array['Visionneuse CyberPingo pour filtrer le CSV et les règles', 'Git Bash, WSL ou Termux pour awk, sort et de petits comptages', 'Windows PowerShell 5.1 si tu préfères Import-Csv et Group-Object']::text[], false, false, 55),
  ('daad28f7-f152-e17d-7c96-a065f3d094f5', 'projet-soc-pme', 'Projet final : trier une semaine d’alertes et rédiger le rapport d’analyse', 'Tu qualifies douze alertes d’une PME, calcules leurs priorités à partir d’une grille explicite, relies plusieurs sources et choisis une conclusion défendable.', 'securite', 'avance', 200, array['Qualifier une alerte en distinguant fait direct, corroboration et simple soupçon', 'Calculer une priorité numérique à partir d’une formule explicite', 'Relier les preuves Linux, web, DNS, proxy, réseau et Windows dans une chronologie unique', 'Rédiger une conclusion défendable, un indicateur partageable et une action de confinement prioritaire']::text[], array['Commence par la grille de triage, puis seulement après ouvre les preuves.', 'Une source unique suffit rarement à conclure à un vrai positif dans ce projet.', 'Le proxy, le DNS et le pare-feu peuvent confirmer ensemble une même communication sortante.', 'Quand tu hésites entre faux positif et à surveiller, cherche d’abord s’il existe un repère bénin explicitement autorisé par la grille.']::text[], '{}'::text[], 750, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le lundi 25 mai 2026, l’Hôtel Palmier d’Or te confie une semaine d’alertes, du 18 au 24 mai 2026, pour vérifier si le petit dispositif de détection local remonte des incidents réels ou du simple bruit. Kader Sow a exporté les alertes, l’inventaire des machines et plusieurs sources de preuve, sans filtrer le trafic légitime. Ton rôle est de qualifier chaque signal comme vrai positif, faux positif ou à surveiller, puis de recalculer une priorité numérique fondée sur la gravité annoncée, la criticité de la machine et la certitude. Tu dois ensuite reconstituer l’incident réel, choisir la première action de confinement et préparer un rapport qui reste factuel. Aucun SIEM ni système réel n’est nécessaire : tout se décide à partir des fichiers fournis.', array['Tu travailles uniquement sur des exports fictifs et tu ne te connectes à aucune machine du scénario.', 'Les seules règles de qualification, de certitude et de priorité autorisées sont celles qui figurent dans la grille fournie.']::text[], array['Visionneuse de journaux CyberPingo pour rechercher dans les exports', 'Git Bash, WSL ou Termux pour filtrer des lignes avec grep, awk ou sort', 'Windows PowerShell 5.1 avec Get-Content -Encoding UTF8 et Select-String']::text[], false, true, 95)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('31e8234d-52ad-5b3f-9917-8784792fc5ed', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 1, 'Dans « slg-tp1-syslog.log », combien de lignes ont été écrites par le programme « sshd » ?', 'Compte seulement les lignes dont le nom du programme vaut exactement « sshd » dans la partie avant le message.', 'Un nombre entier'),
  ('8ae8663e-c7bf-2396-ff05-c8becb70dce1', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 2, 'Dans « slg-tp1-syslog.log », quelle est la première heure UTC d’un échec SSH, au format HH:MM:SS ?', 'Le syslog du TP 1 est écrit en UTC+01:00 : convertis d’abord l’heure locale avant de chercher la première occurrence utile.', 'Une heure UTC au format HH:MM:SS'),
  ('de7242cb-aa14-59be-b8cb-869f73f8b055', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 3, 'Dans « slg-tp1-rfc5424.log », la ligne qui commence par « <34>1 » est de quelle gravité ? Réponds par une lettre. a) warning b) error c) critical d) notice', 'Rappelle-toi qu’un PRI se lit par « facilité × 8 + gravité » puis retrouve la valeur finale de gravité.', 'Une seule lettre'),
  ('88cad9cd-250c-c25c-17e5-abdc0b171a0a', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 4, 'Dans « slg-tp1-application.jsonl », combien d’événements ont le niveau « error » ?', 'Chaque ligne est un objet JSON : filtre uniquement sur la clé « level » avant de compter.', 'Un nombre entier'),
  ('2418268a-ee56-f129-2869-3bf01f523cfd', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 5, 'Quel utilisateur subit le plus d’échecs « auth.login.failed » dans « slg-tp1-application.jsonl », sans ex æquo ?', 'Isole l’action demandée puis groupe les lignes par utilisateur avant de trier les totaux.', 'Un identifiant utilisateur en minuscules'),
  ('0c110d66-9fd3-e9ab-6ad4-1690142d75d7', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 6, 'Dans « slg-tp1-export-proxy.csv », combien d’octets ont été refusés au total par les lignes « TCP_DENIED/403 » ?', 'Le fichier est séparé par des points-virgules : garde les refus puis additionne la colonne des octets.', 'Un nombre entier d’octets'),
  ('b4c392bf-9907-df97-9cb3-85286ac7e05f', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 7, 'Quelle adresse IP a émis le plus de requêtes dans « slg-tp1-acces.log », sans ex æquo ?', 'Compte la première colonne du journal web puis trie les totaux avant de conclure.', 'Une adresse IPv4'),
  ('d9b3c4bf-c174-05eb-39f2-1813ee874b25', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 8, 'Combien de réponses 5xx vois-tu dans « slg-tp1-acces.log » ?', 'Le code HTTP apparaît juste après la requête entre guillemets. Filtre les codes compris entre 500 et 599.', 'Un nombre entier'),
  ('57126bac-ccc2-d13f-c0a5-2f7408b13288', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 9, 'Quel chemin revient le plus souvent parmi les réponses 404 de « slg-tp1-acces.log » ?', 'Isole d’abord les 404, puis groupe les chemins demandés pour trouver le seul maximum.', 'Un chemin web exact'),
  ('52508c2d-d369-2faa-02a8-3a16318da2b7', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 10, 'À quelle minute UTC se situe le pic de requêtes dans « slg-tp1-acces.log » ?', 'Ignore les secondes : coupe l’horodatage à la minute, puis compte les lignes par minute UTC.', 'Une heure UTC au format HH:MM'),
  ('c615fa3c-ef86-efc3-00cf-b6b8db913e97', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 11, 'Pour l’identifiant de requête « req-2042 », de combien de minutes l’horloge de l’application retarde-t-elle encore par rapport à l’accès web une fois les fuseaux alignés ?', 'Repère la même requête dans les deux fichiers (champ « requestId » côté application, paramètre « rid » dans l’URL du journal web), mets d’abord les deux horodatages en UTC, puis calcule l’écart résiduel.', 'Un nombre entier de minutes'),
  ('172cdd97-7bad-d721-eb88-594b5e4b8038', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 12, 'Combien d’adresses IP sources distinctes apparaissent dans les échecs SSH de « slg-tp1-syslog.log » ?', 'Garde seulement les lignes d’échec SSH, extrais l’adresse après « from », supprime les doublons puis compte.', 'Un nombre entier'),
  ('ce6b46c7-36f5-6028-be54-ebd7835ba37e', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 13, 'Combien de requêtes de « slg-tp1-acces.log » portent un agent utilisateur qui contient « python-requests » ?', 'L’agent utilisateur est le dernier champ entre guillemets dans le format combined.', 'Un nombre entier'),
  ('277569d9-9d1e-6f97-c941-918e1ff26e79', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 14, 'Quel fichier faut-il consulter en priorité pour décoder proprement une valeur « PRI » complète, avec facilité et gravité ? Réponds par une lettre. a) le syslog traditionnel b) le journal applicatif JSON lignes c) l’export du proxy d) le journal RFC 5424', 'Cherche la source qui porte explicitement le champ « PRI » au début de la ligne.', 'Une seule lettre'),
  ('12856389-97d6-5427-aeb7-d610b2657afc', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 15, 'Dans « slg-tp1-export-proxy.csv », quel client interne cumule le plus de refus « TCP_DENIED/403 », sans ex æquo ?', 'Groupe uniquement les refus par adresse cliente, puis garde le total le plus élevé.', 'Une adresse IPv4 interne'),
  ('54a4b186-fdaf-633f-abea-d66b9b15d14f', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 1, 'Quel compte subit le plus d’échecs 4625 dans « slg-tp2-securite.csv », sans ex æquo ?', 'Filtre l’identifiant d’événement 4625, groupe ensuite les lignes par compte cible puis trie les totaux.', 'Un identifiant de compte en minuscules'),
  ('fdcf88d7-b954-2fb1-5e78-15027214065b', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 2, 'Pour les échecs 4625 qui portent le sous-code « 0xC000006A », quelle signification est correcte ? Réponds par une lettre. a) journal d’audit effacé b) bon identifiant, mauvais mot de passe c) compte verrouillé d) utilisateur inexistant', 'Le guide donne les significations générales des principaux sous-codes 4625.', 'Une seule lettre'),
  ('9cf871f5-b905-c2d4-5263-2f51a9170ac5', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 3, 'Combien d’adresses IP sources distinctes vois-tu dans l’arrosage de mots de passe contre « pc-compta01 » qui vise plusieurs comptes en type 10 ?', 'Reste sur les 4625 du poste demandé, en type 10, puis compte les adresses sources distinctes de la série concernée. Les adresses d’une même série peuvent appartenir à des plages différentes : retiens toutes celles qui y participent.', 'Un nombre entier'),
  ('33f08e21-25c1-36bb-6377-d3908d1f8cc1', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 4, 'Parmi les comptes visés par l’arrosage de mots de passe contre « pc-compta01 », l’un d’eux finit par ouvrir une session en type 10. À quelle heure UTC cette première réussite a-t-elle lieu ?', 'Relève d’abord les comptes visés par la rafale d’échecs, puis cherche, sur le même poste et en type 10, la première réussite de l’un d’eux après la rafale.', 'Une heure UTC au format HH:MM:SS'),
  ('b6b0e986-cad7-5f07-1c32-d6f258746f46', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 5, 'Quel compte a été créé par l’événement 4720 dans « slg-tp2-securite.csv » ?', 'Filtre l’identifiant 4720 puis relève le compte cible créé, pas le compte qui a lancé l’action.', 'Un identifiant de compte en minuscules'),
  ('a4273806-bdd2-8603-e7db-f47130ac08a4', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 6, 'Quel groupe est ensuite touché par l’événement 4732 pour ce compte nouvellement créé ?', 'Cherche la ligne 4732 qui suit la création précédente et lis son champ de groupe.', 'Un nom de groupe exact'),
  ('067981a5-edff-2bea-c659-65f02d4ae63b', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 7, 'Combien de comptes distincts sont verrouillés par des événements 4740 dans « slg-tp2-securite.csv » ?', 'Les lignes 4740 peuvent se répéter : compte seulement les comptes ciblés distincts.', 'Un nombre entier'),
  ('f41ec1e3-ec55-84dd-670a-c6ea61319785', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 8, 'À quelle heure UTC le journal de sécurité est-il effacé par l’événement 1102 ?', 'Il n’y a pas besoin de conversion ici : le champ « TimeCreatedUtc » est déjà en UTC.', 'Une heure UTC au format HH:MM:SS'),
  ('0f212b9c-6e47-40ee-89e3-eea8a61a643b', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 9, 'Dans « slg-tp2-sysmon.jsonl », quel est le processus parent du « powershell.exe » suspect lancé sur « pc-compta01 » ?', 'Filtre l’événement Sysmon de création de processus sur le binaire cible puis lis le champ « ParentImage ».', 'Un chemin Windows complet, en minuscules'),
  ('4f30b7eb-0000-76a8-f1d0-0a19213ec7bb', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 10, 'Quelle destination complète, sous la forme adresse:port, voit-on ensuite pour ce même processus dans « slg-tp2-sysmon.jsonl » ?', 'Utilise le même ProcessGuid ou la même fenêtre temporelle pour retrouver la connexion réseau associée.', 'Une destination au format adresse:port'),
  ('6631db6e-4519-1df8-01a0-9b409fef87bb', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 11, 'Quel domaine ce même processus résout-il dans l’événement Sysmon 22 associé ?', 'Reste sur le même processus et lis le champ « QueryName » de l’événement DNS Sysmon.', 'Un nom de domaine exact'),
  ('bff9ee0a-e0fb-82aa-4c39-fb1eef67a837', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 12, 'Quel domaine apparaît dans la commande encodée de « slg-tp2-powershell.jsonl » une fois la Base64 UTF-16LE décodée ?', 'Repère « -EncodedCommand », décode la charge UTF-16LE, puis relève seulement le domaine contacté.', 'Un nom de domaine exact'),
  ('8ce78c95-90d4-3c89-7c51-31ba200ebcc0', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 13, 'Quel numéro de type de session est le plus fréquent pour le compte de service « svc-sauvegarde » dans « slg-tp2-securite.csv », sans ex æquo ?', 'Filtre les ouvertures de session réussies du compte demandé, puis compare les valeurs de « LogonType ».', 'Un numéro de type de session'),
  ('c062ec22-33a6-e917-7833-1e0e32cda0c0', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 14, 'Combien de postes distincts apparaissent dans les sessions réseau de type 3 du compte « svc-resa » ?', 'Garde seulement les 4624 du compte demandé avec « LogonType » égal à 3, puis compte les postes distincts.', 'Un nombre entier'),
  ('030de78e-0b15-b08f-2e8a-30fa0627a72f', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 15, 'Quelle proposition respecte le mieux l’ordre chronologique plausible de l’activité suspecte sur « pc-compta01 » ? Réponds par une lettre. a) effacement du journal, puis échec distant, puis création de compte, puis PowerShell b) création de compte, puis réussite distante, puis échec de mot de passe, puis effacement du journal c) échec distant, puis réussite distante, puis PowerShell, puis effacement du journal d) PowerShell, puis effacement du journal, puis échec distant, puis création de compte', 'Trie d’abord les heures UTC des familles d’événements citées, puis compare les quatre ordres proposés.', 'Une seule lettre'),
  ('80c440b7-8331-13ce-d0da-ccd6fb2d0696', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 1, 'Quelle adresse publique balaie le plus de ports différents dans « slg-tp3-pare-feu.log », sans ex æquo ?', 'Cherche une même source publique, puis compte les ports de destination distincts visés sur un temps court.', 'Une adresse IPv4 publique'),
  ('210f82c1-1743-2b5e-1222-f66f216797cc', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 2, 'Combien de ports de destination distincts cette même adresse balaie-t-elle ?', 'Après avoir trouvé la source, dédoublonne les ports de destination qu’elle vise avant de compter.', 'Un nombre entier'),
  ('b40f0b4e-2f59-34af-34c3-aafc785946c0', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 3, 'Quel port de destination revient le plus souvent dans les tentatives de cette adresse de scan ?', 'Reste sur les lignes de la source déjà identifiée, puis groupe les valeurs de « DPT ».', 'Un numéro de port'),
  ('4a9fe238-e611-873b-47bf-11262612f2f2', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 4, 'Quelle destination externe apparaît dans le premier « UFW ALLOW » sortant du réseau des bureaux dont le port de destination n’est ni 53, ni 80, ni 443 ?', 'Ignore le bruit de scan externe et concentre-toi sur les flux autorisés depuis une machine interne vers l’extérieur ; écarte ceux qui visent les ports 53, 80 et 443.', 'Une adresse IPv4'),
  ('143a861c-9882-b18b-9bdf-be5cef40b1d5', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 5, 'Quel est le port de destination de ce même premier « UFW ALLOW » hors ports 53, 80 et 443 ?', 'Une fois la bonne ligne repérée, lis simplement la valeur « DPT » sur cette même ligne.', 'Un numéro de port'),
  ('143fca48-f913-141e-e02a-af350fc5dca9', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 6, 'Quelle machine interne contacte un même domaine externe à intervalles parfaitement identiques, avec de petites requêtes et sans télécharger de gros fichiers ?', 'Croise le DNS et le proxy : calcule, pour chaque client, l’écart entre ses requêtes successives vers un même domaine. Un balisage garde exactement le même écart, alors que le trafic normal varie. N’oublie pas d’écarter la mise à jour lourde.', 'Une adresse IPv4 interne'),
  ('63b46f00-beed-4993-f558-cca188b55b35', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 7, 'Quel est l’intervalle médian, en secondes, entre deux requêtes successives de cette machine vers ce domaine ?', 'Trie les heures de ses requêtes vers ce domaine (dans le proxy ou dans le DNS, le résultat est le même), calcule les écarts successifs, puis prends la médiane.', 'Un nombre entier de secondes'),
  ('1aabdb0c-cd0d-dbf5-5df8-263e369cdc7d', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 8, 'Quel domaine cumule le plus de réponses « NXDOMAIN » dans « slg-tp3-dns.log », sans ex æquo ?', 'Garde les lignes de réponse qui disent « NXDOMAIN », puis groupe-les par domaine.', 'Un nom de domaine exact'),
  ('e2d0b3d3-987f-fcf2-e788-fc5d4651d7c1', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 9, 'Quelle est la longueur, en caractères, du plus long nom de domaine demandé dans « slg-tp3-dns.log » ?', 'Mesure la longueur du nom dans les lignes « query », pas celle de l’adresse IP de réponse.', 'Un nombre entier'),
  ('1d13046d-c60f-c60a-1b3c-ee0ede5fd21e', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 10, 'Combien d’octets le proxy transfère-t-il au total entre cette machine et ce domaine ?', 'Garde les lignes du proxy dont l’URL vise ce domaine, puis additionne la colonne des octets.', 'Un nombre entier d’octets'),
  ('2c6974b1-c55b-f9bf-470c-82c2a1958b27', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 11, 'Quelle machine interne émet le plus de requêtes DNS de type TXT, sans ex æquo ?', 'Isole les lignes « query[TXT] », puis groupe-les par adresse cliente avant de trier.', 'Une adresse IPv4 interne'),
  ('02cfd0de-c854-1bfd-58a3-cbc4eb6b2bf0', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 12, 'Quel client interne accumule le plus de refus « TCP_DENIED/403 » dans « slg-tp3-proxy.log », sans ex æquo ?', 'Compte uniquement les lignes de refus du proxy puis regroupe-les par client.', 'Une adresse IPv4 interne'),
  ('f954701c-f078-5d4a-ecad-b0e7c15871ec', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 13, 'Combien de refus « TCP_DENIED/403 » ce client cumule-t-il ?', 'Reste sur le client trouvé juste avant et recompte seulement ses lignes de refus.', 'Un nombre entier'),
  ('b9b7c159-1970-ee1c-2755-7a24179a3f0e', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 14, 'Quelle proposition ressemble le plus à un service légitime périodique plutôt qu’à un balisage ? Réponds par une lettre. a) de petites requêtes à intervalle strictement identique vers un même domaine depuis une seule machine b) un téléchargement lourd toutes les 15 minutes depuis un poste connu pour les mises à jour c) une suite de requêtes TXT depuis la même machine vers un domaine rare d) un flux sortant autorisé vers un port inattendu juste avant des requêtes répétitives', 'Compare à la fois la taille, la régularité et le contexte fonctionnel du client qui émet les requêtes.', 'Une seule lettre'),
  ('aa36bfbe-777a-918e-e8d4-cc4e9b849e43', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 15, 'Quelle machine faut-il isoler en premier si tu dois agir immédiatement ? Réponds par une lettre. a) l’adresse publique qui scanne depuis Internet b) le serveur DNS interne c) le client qui accumule le plus de refus proxy d) la machine interne qui balise régulièrement', 'Priorise la machine interne qui montre à la fois un rythme de communication anormal et une cible répétitive claire.', 'Une seule lettre'),
  ('53531fb7-6b9a-367a-c1cc-c8d99730feea', '58886b77-40ab-af65-885e-cb7d5979bc64', 1, 'Selon la règle du guide, quelle machine détenait l’adresse 172.20.10.57 à 2026-05-23T10:19:31Z dans « slg-tp4-baux-dhcp.log » ?', 'Cherche le bail dont l’heure de début couvre ce fait et dont l’heure de fin n’est pas encore atteinte.', 'Nom exact de machine'),
  ('ae898630-a3ed-9621-b2d0-787c40ef4eef', '58886b77-40ab-af65-885e-cb7d5979bc64', 2, 'Toujours à 2026-05-23T10:19:31Z, quelle adresse MAC est associée à 172.20.10.57 dans « slg-tp4-baux-dhcp.log » ?', 'Reste sur le même bail que pour la question précédente et relève seulement la colonne de l’adresse matérielle.', 'Adresse MAC en minuscules'),
  ('d3dd6c83-0c34-0f4c-5ac0-aa93d824f6a2', '58886b77-40ab-af65-885e-cb7d5979bc64', 3, 'Dans « slg-tp4-acces.log », à quelle heure UTC la source 172.20.10.57 demande-t-elle pour la première fois un chemin commençant par « /reservation/admin/booking/8842 » ?', 'Filtre par adresse source puis par préfixe de chemin, et garde la première occurrence chronologique.', 'Heure UTC au format HH:MM:SS'),
  ('7e887dc9-d313-c993-ef4e-a0f52627cad0', '58886b77-40ab-af65-885e-cb7d5979bc64', 4, 'Dans « slg-tp4-acces.log », à quelle heure UTC la même source envoie-t-elle le POST vers « /reservation/api/bookings/8842/edit » ?', 'Isole d’abord la source, puis la méthode POST et enfin le chemin exact de modification.', 'Heure UTC au format HH:MM:SS'),
  ('8feb503e-3575-0a36-1db5-7f212f92e6ed', '58886b77-40ab-af65-885e-cb7d5979bc64', 5, 'Combien de minutes s’écoulent entre la première requête sur « /reservation/admin/booking/8842 » et le POST sur « /reservation/api/bookings/8842/edit » ?', 'Convertis d’abord les deux preuves dans le même fuseau, puis soustrais-les sans arrondir au hasard.', 'Un nombre entier de minutes'),
  ('10305144-5053-8d9a-a1a4-f6d22d968fe2', '58886b77-40ab-af65-885e-cb7d5979bc64', 6, 'En croisant « slg-tp4-acces.log » et « slg-tp4-auth.log », quel compte ouvre une session SSH réussie depuis 172.20.10.57 après le POST de modification ?', 'Repère d’abord l’adresse dans auth.log, puis garde le premier succès qui suit la modification web.', 'Nom de compte en minuscules'),
  ('3aa30359-82f4-05d2-22f3-b084673ff1ad', '58886b77-40ab-af65-885e-cb7d5979bc64', 7, 'Toujours dans « slg-tp4-auth.log », à quelle heure UTC se produit le premier succès SSH depuis 172.20.10.57 ?', 'N’oublie pas que ce journal est en UTC+01:00 et qu’il faut donc revenir en UTC avant de répondre.', 'Heure UTC au format HH:MM:SS'),
  ('e1915457-77a7-a628-ac67-19e973aaa4f6', '58886b77-40ab-af65-885e-cb7d5979bc64', 8, 'Quel est l’écart d’horloge du proxy, en minutes (valeur positive, sans signe), si tu compares le POST « /reservation/api/bookings/8842/edit » visible dans « slg-tp4-acces.log » et dans « slg-tp4-proxy.log » ?', 'Utilise exactement le même fait dans les deux journaux, pas deux requêtes seulement semblables, puis donne l’écart sans te soucier du sens.', 'Un nombre entier de minutes, sans signe'),
  ('cae6ec99-ed5d-f8b5-cfb0-e86d1824d84e', '58886b77-40ab-af65-885e-cb7d5979bc64', 9, 'Combien de sources parmi « slg-tp4-acces.log », « slg-tp4-proxy.log » et « slg-tp4-auth.log » confirment la consultation « /reservation/admin/booking/8842?view=full » par 172.20.10.57 ?', 'Compte une source seulement si tu retrouves ce fait dans cette source précise, pas seulement la même adresse.', 'Un nombre entier'),
  ('53009e39-01b2-b343-de6a-0d5d03b9dbeb', '58886b77-40ab-af65-885e-cb7d5979bc64', 10, 'Une fois les heures corrigées en UTC, quel ordre est le bon ?
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('31e8234d-52ad-5b3f-9917-8784792fc5ed', array['38']::text[], 'Un syslog traditionnel place le nom du programme juste avant les deux-points. En comptant uniquement les lignes « sshd », on obtient 38. Cette méthode évite de mélanger des messages sshd avec d’autres lignes qui parleraient de SSH dans leur texte.'),
  ('8ae8663e-c7bf-2396-ff05-c8becb70dce1', array['07:12:14', '7:12:14']::text[], 'L’horodatage du syslog ne porte ni fuseau ni année, donc il faut suivre la règle donnée par l’énoncé puis retrancher une heure. La première ligne d’échec SSH convertie en UTC tombe à 07:12:14. Sans cette normalisation, la chronologie serait fausse dès la deuxième ligne comparée.'),
  ('de7242cb-aa14-59be-b8cb-869f73f8b055', array['c']::text[], 'Le PRI 34 se décompose en facilité 4 et gravité 2. La gravité 2 correspond à « critical », donc la bonne réponse est la lettre c. Savoir faire ce calcul te permet de lire un RFC 5424 sans table externe quand la gravité suffit.'),
  ('88cad9cd-250c-c25c-17e5-abdc0b171a0a', array['53']::text[], 'Le journal applicatif est en JSON lignes, donc chaque événement porte son propre champ « level ». En comptant seulement les lignes où ce champ vaut « error », on obtient 53. Cette lecture est plus fiable qu’une recherche de texte libre dans le message.'),
  ('2418268a-ee56-f129-2869-3bf01f523cfd', array['svc-resa']::text[], 'Il faut garder uniquement les événements « auth.login.failed », puis compter les occurrences par utilisateur. Le total le plus élevé revient à svc-resa, sans égalité. Regrouper les échecs de cette façon aide à séparer une mauvaise habitude d’un vrai ciblage.'),
  ('0c110d66-9fd3-e9ab-6ad4-1690142d75d7', array['8261']::text[], 'Une fois les lignes « TCP_DENIED/403 » isolées, il suffit d’additionner la colonne « Octets ». Le total vaut 8261. Ce calcul montre qu’un simple nombre de refus ne dit pas tout : le volume associé peut aussi compter.'),
  ('b4c392bf-9907-df97-9cb3-85286ac7e05f', array['203.0.113.77']::text[], 'Le journal nginx combined commence par l’adresse du client. En regroupant toutes les lignes par IP, une seule arrive en tête : 203.0.113.77. Ce comptage sert souvent de premier pivot avant d’examiner les chemins ou les codes associés.'),
  ('d9b3c4bf-c174-05eb-39f2-1813ee874b25', array['22']::text[], 'Les réponses 5xx sont les erreurs serveur. En filtrant les lignes dont le code est compris entre 500 et 599, on en compte 22. C’est une bonne mesure de bruit technique ou de panne au moment d’un incident.'),
  ('57126bac-ccc2-d13f-c0a5-2f7408b13288', array['/admin/backup.sql']::text[], 'Il faut commencer par garder uniquement les lignes 404, puis compter les chemins demandés. Le plus fréquent est /admin/backup.sql. Cette méthode permet de distinguer le bruit opportuniste d’un scan qui insiste sur une ressource précise.'),
  ('52508c2d-d369-2faa-02a8-3a16318da2b7', array['08:37']::text[], 'Le pic se cherche par minute, pas par seconde. En regroupant les lignes du journal web sur la minute UTC, le maximum apparaît à 08:37. Ce type d’agrégation aide à voir un emballement bref qu’une lecture ligne à ligne ferait manquer.'),
  ('c615fa3c-ef86-efc3-00cf-b6b8db913e97', array['2']::text[], 'L’identifiant de requête permet de comparer exactement le même événement dans deux sources. Une fois les fuseaux alignés, il reste un décalage de 2 minute(s) entre l’application et le journal web. C’est une dérive d’horloge résiduelle, pas une erreur de fuseau.'),
  ('172cdd97-7bad-d721-eb88-594b5e4b8038', array['5']::text[], 'Ici, il faut compter les sources distinctes et non le nombre total de lignes. En extrayant l’adresse après « from » sur chaque échec SSH puis en supprimant les doublons, on obtient 5 source(s). Cette nuance change souvent l’interprétation d’un bruit de connexion.'),
  ('ce6b46c7-36f5-6028-be54-ebd7835ba37e', array['71']::text[], 'Le format combined place l’agent utilisateur à la fin de chaque ligne, entre guillemets. En filtrant les lignes qui contiennent « python-requests », on en trouve 71. Ce comptage aide à différencier une navigation humaine d’un client automatisé.'),
  ('277569d9-9d1e-6f97-c941-918e1ff26e79', array['d']::text[], 'Pour décoder un PRI complet, la source la plus adaptée est le journal RFC 5424, car il affiche ce nombre au début de chaque ligne avec un horodatage déjà normalisé. La bonne lettre est donc d. Les autres fichiers parlent d’événements utiles, mais pas avec cette structure.'),
  ('12856389-97d6-5427-aeb7-d610b2657afc', array['172.20.10.31']::text[], 'Une fois les lignes de refus isolées, il faut regrouper par client interne. Le seul maximum revient à 172.20.10.31. Cette lecture permet de voir rapidement si les refus restent dispersés ou si une machine insiste davantage que les autres.'),
  ('54a4b186-fdaf-633f-abea-d66b9b15d14f', array['adiop']::text[], 'Les épreuves 4625 représentent les échecs d’ouverture de session. En les regroupant par compte cible, on voit que adiop arrive seul en tête. Ce comptage permet de savoir si un compte est nettement plus ciblé que les autres.'),
  ('fdcf88d7-b954-2fb1-5e78-15027214065b', array['b']::text[], 'Le sous-code 0xC000006A signifie que le nom de compte est correct mais que le mot de passe ne l’est pas. La bonne lettre est donc b. Cette distinction aide à séparer un oubli de mot de passe d’un compte totalement inventé.'),
  ('9cf871f5-b905-c2d4-5263-2f51a9170ac5', array['3']::text[], 'Pour cette série d’échecs, il faut compter les adresses sources distinctes et non les lignes. En filtrant « pc-compta01 », le type 10 et la rafale visant plusieurs comptes, on obtient 3 source(s). Cette mesure aide à reconnaître un arrosage plutôt qu’un simple oubli local.'),
  ('33f08e21-25c1-36bb-6377-d3908d1f8cc1', array['07:21:43', '7:21:43']::text[], 'Il faut relier la rafale d’échecs à la première réussite du même compte sur le même poste, avec le type 10. Cette réussite apparaît à 07:21:43 UTC. Retrouver ce basculement est une étape classique pour dater un accès qui finit par aboutir.'),
  ('b6b0e986-cad7-5f07-1c32-d6f258746f46', array['audit-temp']::text[], 'L’événement 4720 correspond à la création d’un compte. En lisant le compte cible de cette ligne, on trouve audit-temp. Il faut bien distinguer le compte créé du compte qui a effectué l’action.'),
  ('a4273806-bdd2-8603-e7db-f47130ac08a4', array['backup operators']::text[], 'La ligne 4732 indique dans quel groupe le compte nouvellement créé a été ajouté. Ici, le groupe concerné est backup operators. Croiser 4720 et 4732 permet de mesurer rapidement l’impact réel de la création de compte.'),
  ('067981a5-edff-2bea-c659-65f02d4ae63b', array['2']::text[], 'L’identifiant 4740 signale un verrouillage de compte. Comme un même compte pourrait apparaître plusieurs fois, il faut supprimer les doublons avant de compter. On obtient 2 compte(s) distinct(s) verrouillé(s).'),
  ('f41ec1e3-ec55-84dd-670a-c6ea61319785', array['07:38:11', '7:38:11']::text[], 'L’identifiant 1102 signale l’effacement du journal d’audit. Comme l’export est déjà en UTC, il suffit de relever l’heure du champ « TimeCreatedUtc ». On lit 07:38:11, ce qui constitue un signal fort de dissimulation ou de maintenance à vérifier.'),
  ('0f212b9c-6e47-40ee-89e3-eea8a61a643b', array['c:\program files\microsoft office\root\office16\winword.exe']::text[], 'Pour retrouver le parent d’un processus, Sysmon événement 1 fournit directement le champ « ParentImage ». Ici, le parent du PowerShell suspect est c:\program files\microsoft office\root\office16\winword.exe. Le parent raconte souvent mieux le contexte qu’un simple nom de binaire.'),
  ('4f30b7eb-0000-76a8-f1d0-0a19213ec7bb', array['203.0.113.88:443']::text[], 'Le même processus apparaît ensuite dans l’événement Sysmon 3 de connexion réseau. Sa destination complète est 203.0.113.88:443. Lier création de processus et connexion sortante aide à passer d’un binaire suspect à une preuve de communication.'),
  ('6631db6e-4519-1df8-01a0-9b409fef87bb', array['cdn-miseajour-cache.example']::text[], 'Sysmon événement 22 porte le nom résolu par le processus. Pour la séquence suspecte du TP 2, le domaine résolu est cdn-miseajour-cache.example. Ce pivot DNS donne souvent un indicateur plus stable qu’une simple adresse IP.'),
  ('bff9ee0a-e0fb-82aa-4c39-fb1eef67a837', array['telemetrie-catalogue.example']::text[], 'Une commande PowerShell encodée se lit après décodage Base64 UTF-16LE. Une fois cette étape faite, le domaine contacté apparaît clairement : telemetrie-catalogue.example. Il faut toujours vérifier ce contenu avant de conclure sur l’intention de la commande.'),
  ('8ce78c95-90d4-3c89-7c51-31ba200ebcc0', array['4']::text[], 'Le compte de service doit être analysé à part, car ses sessions peuvent être normales. En regroupant ses ouvertures réussies par type, un seul maximum apparaît : 4. Cette mesure aide à distinguer le comportement attendu d’un service de celui d’un utilisateur humain.'),
  ('c062ec22-33a6-e917-7833-1e0e32cda0c0', array['3']::text[], 'Pour le compte « svc-resa », il faut isoler les ouvertures réussies de type 3 puis compter les postes distincts. On en voit 3. Ce type de vue aide à savoir si un compte de service reste cantonné à quelques machines ou circule trop largement.'),
  ('030de78e-0b15-b08f-2e8a-30fa0627a72f', array['c']::text[], 'Les horodatages montrent d’abord les échecs, puis la réussite distante, ensuite le lancement de PowerShell, et enfin l’effacement du journal. L’ordre correct correspond à la lettre c. Reconstituer cette séquence t’aide à passer d’événements isolés à une histoire cohérente.'),
  ('80c440b7-8331-13ce-d0da-ccd6fb2d0696', array['203.0.113.77']::text[], 'Un balayage de ports se voit comme une source unique qui tente beaucoup de ports différents. Dans le fichier du pare-feu, cette source est 203.0.113.77. Il faut raisonner sur les ports distincts, pas seulement sur le nombre total de lignes.'),
  ('210f82c1-1743-2b5e-1222-f66f216797cc', array['17']::text[], 'Une fois la source de scan identifiée, il faut compter ses ports de destination distincts. On en trouve 17. Ce total mesure mieux l’ampleur du balayage qu’une simple suite de tentatives sur un seul service.'),
  ('b40f0b4e-2f59-34af-34c3-aafc785946c0', array['22']::text[], 'En regroupant les tentatives de la source de scan par port de destination, un seul port revient le plus souvent : 22. Cela permet de voir quel service attire ou focalise davantage les essais.'),
  ('4a9fe238-e611-873b-47bf-11262612f2f2', array['203.0.113.45']::text[], 'Pour cette question, il faut repérer le premier flux sortant autorisé dont le port de destination n’est ni 53, ni 80, ni 443, c’est-à-dire qui sort du cadre habituel du réseau des bureaux. La destination externe relevée est 203.0.113.45. Le mot important ici est « premier », donc l’ordre chronologique compte autant que le motif.'),
  ('143a861c-9882-b18b-9bdf-be5cef40b1d5', array['8443']::text[], 'Le même flux sortant autorisé pointe vers le port 8443. Associer destination et port permet ensuite de vérifier si ce service paraît attendu ou non pour la machine source.'),
  ('143fca48-f913-141e-e02a-af350fc5dca9', array['172.20.10.23']::text[], 'Un balisage se reconnaît à un écart identique entre les requêtes, vers un domaine peu fréquent, avec de petits échanges. Ici, la machine interne qui ressort est 172.20.10.23. Une mise à jour lourde d’un autre poste est régulière elle aussi, mais ce n’est pas un balisage : il faut croiser le rythme, le volume et le domaine, pas un seul des trois.'),
  ('63b46f00-beed-4993-f558-cca188b55b35', array['420']::text[], 'La médiane des écarts successifs est plus robuste qu’une simple moyenne. Pour la machine répétant ses contacts, elle vaut 420 seconde(s). C’est une façon efficace de distinguer un rythme de balisage d’un trafic plus aléatoire.'),
  ('1aabdb0c-cd0d-dbf5-5df8-263e369cdc7d', array['pool-check.sync-anchor.example']::text[], 'Les réponses « NXDOMAIN » indiquent qu’un nom demandé n’existe pas. En les regroupant par domaine, le seul maximum revient à pool-check.sync-anchor.example. Ce type de vue aide à repérer un domaine mal formé, mal distribué ou artificiellement généré.'),
  ('e2d0b3d3-987f-fcf2-e788-fc5d4651d7c1', array['33']::text[], 'Il faut mesurer le texte du nom de domaine sur les lignes « query », puis garder la longueur maximale. Le plus long nom demandé contient 33 caractère(s). Cette mesure peut aider à détecter des noms anormalement verbeux ou générés.'),
  ('1d13046d-c60f-c60a-1b3c-ee0ede5fd21e', array['44640']::text[], 'Une fois les lignes du proxy filtrées sur ce domaine, on additionne simplement les octets. Le total transmis vaut 44640. Le volume donne un complément utile au simple rythme des requêtes.'),
  ('2c6974b1-c55b-f9bf-470c-82c2a1958b27', array['172.20.10.23']::text[], 'En filtrant les requêtes DNS de type TXT puis en regroupant les clients, une seule machine ressort : 172.20.10.23. Les requêtes TXT ne sont pas suspectes en elles-mêmes, mais leur concentration sur un seul client peut devenir intéressante.'),
  ('02cfd0de-c854-1bfd-58a3-cbc4eb6b2bf0', array['172.20.10.25']::text[], 'Les refus du proxy doivent être regroupés par client pour éviter les impressions visuelles trompeuses. Le client qui en cumule le plus est 172.20.10.25. Cela permet ensuite de vérifier si ces refus suivent un motif régulier ou opportuniste.'),
  ('f954701c-f078-5d4a-ecad-b0e7c15871ec', array['9']::text[], 'Une fois le bon client identifié, il suffit de recompter ses seules lignes « TCP_DENIED/403 ». Le total est de 9. Associer un nom ou une adresse à son volume de refus aide à prioriser ce qui mérite un examen humain.'),
  ('b9b7c159-1970-ee1c-2755-7a24179a3f0e', array['b']::text[], 'Le comportement qui ressemble le plus à une mise à jour légitime est le téléchargement lourd et périodique d’un poste attendu pour cette fonction. La bonne réponse est donc b. Le volume et le contexte aident ici à séparer la maintenance du balisage.'),
  ('aa36bfbe-777a-918e-e8d4-cc4e9b849e43', array['d']::text[], 'Le scan externe mérite une mesure de filtrage, mais la priorité d’isolement porte ici sur la machine interne qui semble déjà communiquer de façon répétée et structurée. La bonne réponse est la lettre d. En triage, on isole d’abord l’hôte susceptible d’être compromis dans le réseau interne.'),
  ('53531fb7-6b9a-367a-c1cc-c8d99730feea', array['adm-pc02']::text[], 'Le bon bail est celui qui commence avant 10:19:31Z et finit après cet instant. En appliquant strictement début inclus et fin exclue, la machine qui porte cette adresse est adm-pc02.'),
  ('ae898630-a3ed-9621-b2d0-787c40ef4eef', array['9c:b6:d0:11:4a:57']::text[], 'Une fois le bon bail identifié, il suffit de reprendre sa colonne MAC. L’adresse matérielle associée à 172.20.10.57 à cet instant est 9c:b6:d0:11:4a:57.'),
  ('d3dd6c83-0c34-0f4c-5ac0-aa93d824f6a2', array['10:14:12']::text[], 'La première consultation de ce préfixe par cette source apparaît à 10:14:12 UTC. C’est le premier jalon utile pour la chronologie de la séquence malveillante.'),
  ('7e887dc9-d313-c993-ef4e-a0f52627cad0', array['10:17:12']::text[], 'La ligne de POST sur le chemin de modification apparaît à 10:17:12 UTC. C’est la preuve directe de l’écriture sur la réservation.'),
  ('8feb503e-3575-0a36-1db5-7f212f92e6ed', array['3']::text[], 'En partant de la première consultation puis du POST de modification, on mesure 3 minute(s). Cette durée montre une action courte et volontaire, pas une simple navigation lente.'),
  ('10305144-5053-8d9a-a1a4-f6d22d968fe2', array['svc-resa']::text[], 'La connexion SSH réussie qui suit la modification vient du compte svc-resa. Le lien temporel entre le POST et ce succès renforce la cohérence de la séquence.'),
  ('3aa30359-82f4-05d2-22f3-b084673ff1ad', array['10:19:31']::text[], 'Après conversion du syslog local en UTC, le premier succès SSH depuis cette source tombe à 10:19:31. Cette conversion est indispensable pour relier correctement les trois sources.'),
  ('e1915457-77a7-a628-ac67-19e973aaa4f6', array['4']::text[], 'Le même POST apparaît dans les deux journaux avec 4 minute(s) d’écart. Cet événement partagé permet de corriger la chronologie du proxy sans deviner.'),
  ('cae6ec99-ed5d-f8b5-cfb0-e86d1824d84e', array['2']::text[], 'La consultation précise est confirmée par 2 source(s). Ce comptage distingue une preuve unique d’un fait recoupé.'),
  ('53009e39-01b2-b343-de6a-0d5d03b9dbeb', array['c']::text[], 'Une fois tous les horodatages ramenés en UTC, la séquence correcte est bien la consultation initiale, puis la modification, puis le succès SSH et enfin la consultation externe de notes. La bonne lettre est donc c.'),
  ('fcb82e69-83b7-1e11-c7c1-9b8b991e6f40', array['a']::text[], 'Le bail de pc-compta01 est déjà terminé à 10:19:31Z. L’option a est donc la seule piste à écarter pour contradiction avec le DHCP.'),
  ('7cdcdfee-e35c-5997-5e8c-9e89df843d48', array['3']::text[], 'Le modèle contient cinq lignes fixes et seules deux d’entre elles sont directement confirmables par le journal web. Il en reste donc trois qui exigent une autre source.'),
  ('d456a735-fb7d-9f21-2619-868d03d09cb2', array['10:28:12']::text[], 'La dernière ligne qui porte l’adresse de l’attaquant apparaît à 10:28:12 UTC. C’est le dernier jalon utile pour borner l’incident dans le temps ; la ligne « session closed » du PAM qui suit ne cite plus l’adresse et n’est donc pas retenue.'),
  ('132e04a9-5387-f1c3-ce73-66b168772fa8', array['11']::text[], 'Entre la modification et la dernière apparition de l’adresse, il s’écoule 11 minute(s). Cette borne aide à resserrer la fenêtre d’investigation.'),
  ('f7a2bd79-1581-587d-b85c-14cc7e5dcbba', array['d']::text[], 'Les quatre sources convergent vers adm-pc02 au bon moment, puis vers une séquence cohérente web puis SSH. La conclusion défendable est donc d.'),
  ('ea301817-e8b4-88ab-3dbd-3112958b3d85', array['10']::text[], 'En appliquant strictement la règle 1 sur les seules lignes en échec, on obtient 10 alerte(s). Chaque alerte correspond à une ligne déclencheuse, pas à une adresse comptée une seule fois.'),
  ('5ee68018-944b-391c-ddc8-08ff1d46c1cd', array['7']::text[], 'La règle 1 déclenche 7 vrai(s) positif(s). Il faut vérifier la vérité de chaque ligne déclencheuse, pas seulement celle du groupe entier.'),
  ('4d6cae4c-a098-fee8-27f3-16f0a6fec200', array['3']::text[], 'La règle 1 produit 3 faux positif(s). Ce bruit vient d’échecs légitimes qui ressemblent superficiellement à une force brute.'),
  ('80e6ae8a-2f36-1bd4-ba0d-85496a580dda', array['23']::text[], 'Avec la définition du TP, la règle 1 laisse 23 faux négatif(s). Il s’agit de lignes attaque qui ne déclenchent aucune alerte de cette règle.'),
  ('968082c9-63aa-321e-41ce-cbc98b5686aa', array['70', '70%', '70 %']::text[], 'La précision de la règle 1 vaut 70 %. Elle mesure la part d’alertes justifiées parmi toutes les alertes de cette règle.'),
  ('399564b4-bed1-bc32-fd3c-2db35de17be9', array['23', '23%', '23 %']::text[], 'Le rappel de la règle 1 vaut 23 %. Il mesure la part des lignes d’attaque que la règle 1 parvient effectivement à alerter.'),
  ('7132a797-c854-7b13-ca3c-440db1732442', array['3']::text[], 'Une fois ses exclusions appliquées, la règle 3 lève 3 alerte(s). Son regroupement plus strict réduit fortement le volume d’alertes.'),
  ('590b66a5-e663-3a15-cecc-cd40d81bbadc', array['3']::text[], 'La meilleure précision appartient à la règle 3. C’est celle qui laisse le moins de bruit relatif.'),
  ('322a56bf-72f5-a4b1-a795-bbd66fa2a720', array['2']::text[], 'Le meilleur rappel appartient à la règle 2. Elle couvre la plus grande part des lignes d’attaque alertées.'),
  ('b5cc2e7a-ddf1-78da-d833-c9bff0735f3b', array['6']::text[], 'Le premier seuil qui fait disparaître tous les faux positifs de la règle 1 est 6. Il faut le trouver expérimentalement sur la même fenêtre et le même regroupement.'),
  ('8e1a7c64-8329-b27f-8c01-a87b144e51ee', array['svc-resa']::text[], 'Sous la règle 2, le compte qui concentre le plus de faux positifs est svc-resa. C’est donc le premier candidat à examiner avant de proposer une exclusion.'),
  ('fbd1513f-5fb7-d674-419c-f6994d4871cf', array['33', '33%', '33 %']::text[], 'Avec cette exclusion supplémentaire, le rappel vaut 33 %. Les lignes du compte exclu ne déclenchent plus d’alerte, donc leurs faux positifs disparaissent, mais elles restent dans le jeu de données : une ligne d’attaque visant ce compte compte comme faux négatif. Une exclusion réduit le bruit, mais elle crée un angle mort sur ce compte.'),
  ('994669d6-acbb-9ae7-02d7-66129d63adf1', array['203.0.113.93']::text[], 'Aucune des trois règles ne détecte l’attaque lente issue de 203.0.113.93. Son rythme reste sous tous les seuils dans toutes les fenêtres définies.'),
  ('558de910-38fa-3aee-becd-d3a7d7b8731a', array['a']::text[], 'Avec le plancher de précision donné, la meilleure candidate restante est la règle 1. La lettre correcte est donc a.'),
  ('ef66a051-002e-b8ae-b3ae-e51d57d94906', array['2']::text[], 'Le meilleur score F1 appartient à la règle 2. Ce score sert ici de compromis objectif entre précision et rappel.'),
  ('0f48c36c-6818-25e0-f7aa-26aaa370572b', array['fp']::text[], 'La grille autorise un faux positif quand plusieurs 4625 sont suivis, sous 120 secondes, d’un 4624 pour le même compte, la même source interne et le même poste, sans signe de privilège ni de propagation. ALT-01 suit exactement ce schéma, il faut donc le classer comme un oubli de mot de passe et non comme une compromission.'),
  ('2d4e709d-6a35-31f9-45ea-0bc35eeb4a67', array['sv']::text[], 'ALT-03 montre une activité suspecte réelle, mais les preuves associées restent limitées à des échecs SSH sans succès ni conséquence confirmée dans une deuxième source. La bonne qualification n’est donc ni un faux positif ni un incident établi, mais une alerte à surveiller.'),
  ('c52f4bc7-d2f8-987d-1213-b4be3bcb31f4', array['vp']::text[], 'Le journal web contient un téléversement suivi d’appels avec un paramètre de commande, puis une autre source montre la suite de l’incident sur le même serveur. Comme la grille exige un fait direct et une corroboration distincte pour conclure, ALT-04 est un vrai positif établi.'),
  ('89f98ffc-032f-8a85-bbbc-bfa46963edee', array['vp']::text[], 'Le pare-feu voit la sortie, le DNS montre la résolution juste avant, et le proxy confirme le tunnel vers la même destination. L’alerte repose donc sur plusieurs faits concordants : elle doit être qualifiée comme un vrai positif.'),
  ('d3ac4f79-431f-7e51-2187-1942a8711bd3', array['fp']::text[], 'La grille de triage décrit explicitement le comportement attendu de la synchronisation d’inventaire de adm-pc02 : parent taskeng.exe, utilisateur ksow et trafic vers le domaine d’inventaire. Les preuves recoupent exactement ce motif, ce qui impose la qualification faux positif.'),
  ('c939aa79-bdcd-72a6-cde6-fec04b01c717', array['sv']::text[], 'Le journal web montre une suite de 404 depuis une même source, mais rien n’indique une exécution, une authentification ou une communication sortante associée. D’après la grille, ce type de scan reste dans la catégorie à surveiller.'),
  ('fab6256a-f1e2-dafd-c911-965e7588fa68', array['48']::text[], 'La priorité ne se lit pas à l’œil : il faut multiplier la gravité annoncée par la criticité de la machine puis par la certitude associée à la qualification retenue. Ce calcul donne la valeur numérique attendue pour ALT-04.'),
  ('2b4c363e-cc7d-cdfe-099d-5b79ac614656', array['32']::text[], 'Il faut réutiliser la même formule, mais avec les valeurs propres à ALT-05. La différence de gravité et de contexte explique pourquoi sa priorité n’est pas la même que celle des autres alertes du serveur.'),
  ('3ac509ee-1cb8-ce41-03d0-d897540cf5b8', array['64']::text[], 'ALT-06 combine une gravité élevée, une machine critique et une certitude forte. Le calcul complet permet de justifier sa place dans l’ordre de traitement au lieu de s’appuyer sur une impression.'),
  ('c8d988ca-b429-e9c0-5c79-5fce7a2aa122', array['alt-06']::text[], 'Une fois les priorités calculées, il faut simplement retenir l’alerte dont la valeur est strictement la plus haute. Le corpus a été construit pour qu’il n’y ait pas d’égalité sur cette première place.'),
  ('f07434d7-8255-01ef-5f90-9e5d9594f529', array['srv-reservation01']::text[], 'Le point d’entrée se déduit de la première action malveillante confirmée dans le journal web, puis de la suite de la compromission visible dans le journal Linux. Il faut donc nommer la même machine du début à la fin de la chaîne.'),
  ('ab0d478d-17a1-723f-daf7-fdfa6ac218e6', array['svc-resa']::text[], 'Le compte compromis n’est pas deviné : il apparaît dans le succès SSH qui suit l’exploitation web. Cette transition de source est justement ce qui rend la conclusion défendable.'),
  ('d4452c11-1777-6224-57a7-77c46365917b', array['09:11:43', '9:11:43']::text[], 'Il faut remonter à la toute première trace de la source externe appartenant à la chaîne de l’incident confirmé : elle précède les requêtes qui exécutent des commandes. Cette heure ouvre la chronologie défendable du rapport.'),
  ('3a253d7d-66f0-8eb2-b519-621c1bf3efb7', array['198.51.100.77']::text[], 'L’adresse d’accès initial doit être retrouvée dans au moins deux sources de la chaîne réelle. C’est cette répétition qui permet d’éviter de confondre l’attaquant principal avec un simple scanner.'),
  ('01b7eebe-1cd7-d5ca-f376-a83da1110731', array['cache-sync.palmier-or.example:8443']::text[], 'Le nom du domaine et le port ne sont pas visibles au même endroit. Il faut relier la résolution DNS et le tunnel proxy sur la même fenêtre horaire pour produire une destination complète et défendable.'),
  ('6ecfc40a-2795-cca0-783b-4748cfff5298', array['b']::text[], 'L’étape visée n’est ni la force brute, ni le compte valide, ni le canal sortant. Elle correspond à l’usage d’un shell web, ce qui renvoie à la technique précise de la liste ATT&CK fournie.'),
  ('1de7163b-4184-afbd-bfc7-494b9a6a2bb2', array['c']::text[], 'Le confinement initial doit interrompre la communication malveillante, mais aussi préserver les preuves encore en mémoire et dans les journaux. L’option correcte est donc celle qui isole la machine sans la redémarrer ni modifier les traces.'),
  ('f69a3d63-a884-f509-6f6b-284643356361', array['cache-sync[.]palmier-or[.]example']::text[], 'Le domaine de destination doit être repris tel qu’il est confirmé par les preuves, mais écrit sous forme désarmée pour pouvoir être partagé sans devenir cliquable. C’est une pratique de rapport standard et explicite dans la grille.'),
  ('6b1bc626-dbe3-10b9-eb76-0a9c40529b1f', array['b']::text[], 'Une conclusion défendable reprend uniquement ce que les preuves établissent vraiment. Parmi les propositions, une seule relie correctement l’exploitation web, l’authentification et la communication sortante confirmées par le corpus.')
insert into public.lab_assets (id, lab_id, kind, title, description, url, position) values
  ('b1416670-3bc6-ab84-b5f5-4b935ceca28b', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'log', 'Syslog traditionnel', 'Export d’un syslog traditionnel de « srv-reservation01 », écrit en heure locale UTC+01:00 pour ce TP.', '/labs/slg-tp1-syslog.log', 1),
  ('f733767e-8b38-8901-887d-71aabbdefc3b', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'log', 'Journal applicatif JSON lignes', 'Événements applicatifs de réservation au format JSON lignes, horodates en UTC.', '/labs/slg-tp1-application.jsonl', 2),
  ('9bcb2aee-76f7-9997-4732-f125706d4366', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'log', 'Export de proxy', 'CSV séparé par des points-virgules avec décisions, octets et clients, déjà en UTC.', '/labs/slg-tp1-export-proxy.csv', 3),
  ('e0553d9c-1e3c-1369-711d-762ee7c6f6dd', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'log', 'Journal web nginx', 'Journal d’accès au format combined, horodaté en UTC avec « +0000 ».', '/labs/slg-tp1-acces.log', 4),
  ('bcb64ac9-b4cb-5e33-98df-a70b412a512e', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'log', 'Extrait RFC 5424', 'Quelques lignes RFC 5424 pour lire un PRI complet et comparer le format.', '/labs/slg-tp1-rfc5424.log', 5),
  ('b6154322-9403-5db1-0557-bd5b64a10f3e', '6e2ffa96-ab8a-1ba7-e2b2-e70a16b47526', 'guide', 'Guide du TP 1', 'Méthode de lecture des formats, de normalisation des heures et de comptage simple.', '/labs/slg-tp1-guide.pdf', 6),
  ('ed12560a-26ea-6816-9589-6c6ead4b4afa', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 'log', 'Journal de sécurité Windows', 'Export CSV des événements de sécurité des postes concernés, avec heures déjà en UTC.', '/labs/slg-tp2-securite.csv', 1),
  ('3908caf5-6f94-537b-77aa-e61fc7bc1d54', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 'log', 'Journal Sysmon', 'Événements Sysmon au format JSON lignes pour suivre processus, DNS et connexions.', '/labs/slg-tp2-sysmon.jsonl', 2),
  ('87ab82d8-b2b1-40f4-00a5-d164ead09a5a', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 'log', 'Journal PowerShell', 'Événements 4104 au format JSON lignes, dont une commande encodée en Base64 UTF-16LE.', '/labs/slg-tp2-powershell.jsonl', 3),
  ('b9a733b8-a60e-2fea-ff88-85ceb40a3d3a', '81000621-4e50-9c2c-adf2-2ef3713c4ca5', 'guide', 'Guide du TP 2', 'Rappels sur les EventId, les types de session, les sous-codes 4625 et le décodage PowerShell.', '/labs/slg-tp2-guide.pdf', 4),
  ('e1f56a42-d614-5c37-f9b6-a0607ecdc9c4', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 'log', 'Journal du pare-feu', 'Export de décisions UFW « BLOCK » et « ALLOW » sur l’après-midi du 22 mai.', '/labs/slg-tp3-pare-feu.log', 1),
  ('c7c79cee-61a3-ec01-860f-794a602ab5e2', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 'log', 'Journal DNS', 'Export dnsmasq avec requêtes et réponses, y compris des « NXDOMAIN » et des requêtes TXT.', '/labs/slg-tp3-dns.log', 2),
  ('3ddcf506-2959-991a-b303-52f75042252f', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 'log', 'Journal du proxy', 'Access log Squid au format natif, avec décisions, octets et URL.', '/labs/slg-tp3-proxy.log', 3),
  ('c3ad711f-8e0e-46b5-f71f-d3ed506af4c0', '108c6b74-381d-0d8b-13d2-3b360c41fdb8', 'guide', 'Guide du TP 3', 'Méthode pour lire un scan, un balisage, des réponses DNS et des refus du proxy.', '/labs/slg-tp3-guide.pdf', 4),
  ('424039fa-6378-578c-4ac5-7e0e08b8e229', '58886b77-40ab-af65-885e-cb7d5979bc64', 'log', 'Journal d’authentification', 'Le syslog d’authentification de srv-reservation01, en heure locale UTC+01:00.', '/labs/slg-tp4-auth.log', 1),
  ('9ade71ac-0e56-8d28-09ca-3f90fb311764', '58886b77-40ab-af65-885e-cb7d5979bc64', 'log', 'Journal d’accès web', 'Le journal nginx de l’application de réservation, déjà en UTC.', '/labs/slg-tp4-acces.log', 2),
  ('8c8dc502-d979-f8d4-eb60-5c91dd167e78', '58886b77-40ab-af65-885e-cb7d5979bc64', 'log', 'Journal du proxy', 'Le journal natif du proxy des bureaux, en epoch.', '/labs/slg-tp4-proxy.log', 3),
  ('5e807f8b-ce95-c4b0-423a-a82893fe79ea', '58886b77-40ab-af65-885e-cb7d5979bc64', 'log', 'Baux DHCP', 'Les baux qui permettent de rattacher une adresse à une machine et à une adresse MAC.', '/labs/slg-tp4-baux-dhcp.log', 4),
  ('31d03715-d186-5df0-023c-0d1f06c6ccea', '58886b77-40ab-af65-885e-cb7d5979bc64', 'report_template', 'Modèle de chronologie', 'Le tableau de travail à remplir en UTC pour ne rien oublier.', '/labs/slg-tp4-modele-chronologie.pdf', 5),
