insert into public.skills (id, domain_id, slug, name, description, position) values
  ('b5fefc99-902d-c2c3-795b-95a9716c3e80', '33d65715-cce7-a7f8-69f7-5a20378661d5', 'formats-horodatage', 'Formats de journaux et horodatage', 'Reconnaître le format d’un journal, en extraire les champs et ramener tous les horodatages en UTC avant de les comparer.', 610),
