  ('044937fa-f553-f0e7-db2f-9c35202d1ba1', '33d65715-cce7-a7f8-69f7-5a20378661d5', 'journaux-windows', 'Journaux Windows et Sysmon', 'Lire les événements de session, de compte et de processus de Windows et repérer une exécution suspecte.', 630),
